import{a as e}from"./Pd4fdmUI.js";var t={version:1,categories:[{id:`methods`,title:`Cooking methods`,intro:`Understand what heat, salt and time do to food.`},{id:`vegetables`,title:`Vegetables & greens`,intro:`Recognise the ingredient, its flavour and the preparation it suits.`},{id:`southern`,title:`Southern table`,intro:`Explore the dishes and ingredients behind Southern hospitality.`},{id:`mushrooms`,title:`Mushrooms & truffles`,intro:`Learn texture, cooking behaviour and the names that overlap.`},{id:`meats`,title:`Poultry, game & offal`,intro:`Know the animal, the part and how to explain it at the table.`},{id:`cured`,title:`Cured meats`,intro:`Separate cut, cure, smoke and cooking before describing a product.`},{id:`cuts`,title:`Meat cuts`,intro:`Connect anatomy and connective tissue with the right cooking method.`},{id:`fish`,title:`Fish & shellfish`,intro:`Describe species and texture without turning broad tendencies into guarantees.`},{id:`dairy`,title:`Cheese, milk & makers`,intro:`Distinguish a maker, a milk and a named cheese.`},{id:`sauces`,title:`Sauces and preparations`,intro:`Name the base, the thickener and the finish before you describe a sauce.`},{id:`grains`,title:`Grains, rice and pasta`,intro:`Tell the grain, the shape and the cooking apart, from the rice pot to the pasta plate.`},{id:`sweets`,title:`Sweets and pastry`,intro:`Know the batter, the custard and the sugar work behind each dessert.`}],entries:[{id:`methods-boiled`,term:`Boiled`,category:`methods`,aliases:[],ref:`c:fd_0025`,definition:`Cooked fully submerged in water at a full, rolling bubble. A rolling boil is as hot as water gets at sea level, 100 C (212 F), and the bubbles keep everything moving. That suits pasta, potatoes, lobster and crab, which want fast, even heat. Delicate fish and meat toughen at a hard boil, so kitchens simmer or poach those.`,guest:`It is cooked in boiling liquid; the sauce and seasoning supply the rest of the character.`,kitchen:`Watch the whole liquid surface: rolling bubbles suit pasta; fragile pieces need gentler treatment.`,compare:`Boiling rolls; simmering bubbles gently; steaming suspends food above liquid.`,correction:``,sources:[{title:`Escoffier: Learning How to Cook`,url:`https://www.escoffier.edu/blog/value-of-culinary-education/learning-how-to-cook-a-guide-for-beginners/`}],reviewedOn:`2026-10-15`},{id:`methods-braised`,term:`Braised`,category:`methods`,aliases:[],ref:`c:fd_0026`,definition:`Often browned, then cooked slowly, covered, in a little liquid. Braising suits tough, hard-working cuts like short rib, shank and cheek. The meat sits partly in liquid under a lid at gentle heat for hours, and its connective tissue melts into gelatin. That makes the meat silky and turns the liquid into a glossy sauce.`,guest:`Braised means browned and then cooked slowly, covered, in a little liquid until it is tender, and that liquid becomes the sauce. On Thanksgiving Day the turkey leg was braised for rich, tender dark meat beside the roast breast.`,kitchen:`Use cheek or short rib to connect a working muscle with a long, gentle covered cook.`,compare:`A stew usually uses smaller pieces; a braise often keeps a larger cut.`,correction:``,sources:[{title:`Escoffier / Gisslen: Professional Cooking, chapter 6`,url:`https://resources.escoffier.edu/textbooks/gisslen/professional_cooking_06.pdf`},{title:`Meat & Livestock Australia: Beef Cheek`,url:`https://www.aussiebeefandlamb.me/meat-cuts/cuts-by-protein/beef/cheek`},{title:`Merriam-Webster: braise`,url:`https://www.merriam-webster.com/dictionary/braise`},{title:`Dictionary.com: braise`,url:`https://www.dictionary.com/browse/braise`},{title:`Wiktionary: braiser`,url:`https://en.wiktionary.org/wiki/braiser`},{title:`Vintage French Copper: Cooking with a copper daubière`,url:`https://www.vintagefrenchcopper.com/2020/11/cooking-with-a-copper-daubiere/`},{title:`Le Creuset: If This Dish Could Talk: the Doufeu`,url:`https://www.lecreuset.com/blog/if-this-dish-could-talk-doufeu.html`},{title:`Wikipedia: Dutch oven`,url:`https://en.wikipedia.org/wiki/Dutch_oven`},{title:`Oxford Learner’s Dictionaries: braise`,url:`https://www.oxfordlearnersdictionaries.com/us/definition/english/braise`}],reviewedOn:`2026-10-15`,say:`BRAYZD`,background:`The word is French: braiser is formed from braise, live coals or embers, a word probably of Germanic origin, and it entered English in the eighteenth century. The name records how braising was first done. On the open hearth the cook nestled a tightly lidded pan, the braisière, into the embers and heaped more hot coals into the rim of its lid, so the heat came from above and below at once. Later pots kept the shape: the recessed lid of the doufeu first held embers, and the colonial Dutch oven had a flanged lid to keep coals out of the food.`,metAt:`Brennan's Thanksgiving Day 2026: the braised leg of the Roasted Buttermilk-Brined Turkey Breast, and the Veal Grillades simmered in their gravy`},{id:`methods-brined`,term:`Brined`,category:`methods`,aliases:[],ref:`c:fd_0027`,definition:`Seasoned ahead with salt, wet or dry, to help retain moisture. Wet brining uses salted water; dry brining applies salt without added water. Salt changes muscle proteins so they retain moisture during cooking. Sugar and aromatics add flavor, but ordinary pre-cook brining is not a preservation process.`,guest:`Brined means the meat rested in salted liquid before it was cooked, which seasons it right through and helps it stay juicy. On Thanksgiving Day our turkey breast was brined in buttermilk, which adds a gentle tang to the salt.`,kitchen:`Identify whether the kitchen uses a salt-water soak or salt applied directly. Sugar and aromatics are optional.`,compare:`Brining is not automatically pickling, curing or a shelf-life guarantee.`,correction:``,sources:[{title:`USDA FSIS: Poultry: Basting, Brining, and Marinating`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/poultry/poultry-basting-brining-and-marinating`},{title:`New England Today: What Is Brining a Turkey?`,url:`https://newengland.com/today/food/cooking-advice/what-is-brining-a-turkey/`},{title:`Toronto Star: The rise and fall of turkey brining`,url:`https://www.pressreader.com/canada/toronto-star/20181222/282969631177198`},{title:`ckbk, On Food and Cooking: Brining`,url:`https://app.ckbk.com/reference/food00011c03s001e009se001se003/brining`},{title:`America’s Test Kitchen: The Science of Brining`,url:`https://www.americastestkitchen.com/how-tos/8243-the-science-of-brining`},{title:`Discover Magazine: What Brining Does to Your Holiday Turkey`,url:`https://www.discovermagazine.com/the-sciences/what-brining-does-to-your-holiday-turkey`},{title:`Chowhound: Pickle Juice Vs Buttermilk for Fried Chicken`,url:`https://www.chowhound.com/2264098/pickle-juice-vs-buttermilk-fried-chicken-brine/`},{title:`Food Republic: Is Buttermilk an Essential Ingredient for Fried Chicken?`,url:`https://www.foodrepublic.com/1807281/fried-chicken-buttermilk-purpose/`},{title:`Cook’s Illustrated: How to Brine a Turkey`,url:`https://www.americastestkitchen.com/cooksillustrated/articles/36-how-to-brine-a-turkey`}],reviewedOn:`2026-10-15`,say:`BRYND`,background:`Chefs have long soaked lean meats such as poultry in salted water so they would not dry out, but brining reached home Thanksgiving cooks in a wave only from the 1990s: Cook’s Illustrated introduced its brined turkey in 1993, and brining recipes flourished through the early 2000s. Food science explains the effect: a salt solution dissolves part of the protein structure inside muscle fibers, so the meat takes up brine and holds on to more water, and a brined breast loses less of its juice in the oven. Southern cooks have their own brine in buttermilk, soaking chicken before frying, and its lactic acid tenderizes the meat more gently than vinegar or citrus.`,metAt:`Brennan's Thanksgiving Day 2026: Roasted Buttermilk-Brined Turkey Breast`},{id:`methods-caramelized`,term:`Caramelized`,category:`methods`,aliases:[],ref:`c:fd_0028`,definition:`Cooked until sugar, natural or added, browns to a nutty sweetness. Heat breaks sugar down into hundreds of new compounds that taste nutty, toasty and a little bitter, like the top of a crème brûlée. Strictly that is sugar alone; browning meat is a separate reaction that needs protein. Menus use it loosely for any slow, deep browning of onions or fruit.`,guest:`Caramelized means the sugar has been cooked until it browns, turning plain sweetness into something toasty, nutty and a little bitter. In the Bananas Foster the butter and brown sugar cook into a caramel right in the pan at your table, and on Thanksgiving Day the candied nuts on our desserts wore a thin caramel coat.`,kitchen:`Compare a browned sugar topping with a seared steak: similar color can come from different reactions.`,compare:`Caramelization is sugar chemistry; Maillard browning also involves amino compounds.`,correction:``,sources:[{title:`Exploratorium: Caramels: A Story of Sugar`,url:`https://annex.exploratorium.edu/cooking/bread/caramels-story.html`},{title:`Merriam-Webster: caramel`,url:`https://www.merriam-webster.com/dictionary/caramels`},{title:`Dictionary.com: caramel`,url:`https://www.dictionary.com/browse/caramel`},{title:`Wiktionary: caramel`,url:`https://en.wiktionary.org/wiki/caramel`},{title:`Wikipedia: Caramelization`,url:`https://en.wikipedia.org/wiki/Caramelization`},{title:`Tasting Table: Here’s The Exact Temperature Sugar Starts To Caramelize`,url:`https://www.tastingtable.com/1974297/temperature-sugar-starts-caramelize`},{title:`University of Illinois, Food for the Future: caramelization below the melting point of sugar`,url:`https://publish.illinois.edu/foodforthefuture/?p=472`},{title:`CBS News: Recipe: Brennan’s Bananas Foster`,url:`https://www.cbsnews.com/news/recipe-brennans-bananas-foster`},{title:`Hong Kong Education Bureau: Caramelisation learning activity`,url:`https://www.edb.gov.hk/attachment/en/curriculum-development/kla/technology-edu/resources/technology-and-living/Activity1-Caramelisation_eng.docx`}],reviewedOn:`2026-10-15`,say:`KAR-uh-muh-lyzd`,background:`Caramel came into English in the early eighteenth century from French, which took it from Spanish caramelo, and dictionaries trace it back through Portuguese to a Late Latin word for a small reed, calamellus; a medieval Latin name for sugarcane, cannamella, is thought to have shaped it along the way. The chemistry came later. Table sugar, sucrose, begins to caramelize at about 160 to 170 C (320 to 338 F), while fructose, a sugar of fruit and honey, browns at about 105 to 110 C (221 to 230 F). Time matters as well as heat: held long enough, sugar can caramelize below its melting point. In a Bananas Foster the butter and brown sugar melt into a pan caramel before the bananas go in.`,metAt:`Brennan's Thanksgiving Day 2026: the pan caramel of World Famous Bananas Foster, the candied hazelnuts of the Chocolate and Orange Tart and the candied pecans of the Sweet Potato Agnolotti`},{id:`methods-confit`,term:`Confit`,category:`methods`,aliases:[],ref:`c:fd_0029`,definition:`Cooked slowly and fully submerged in fat at low heat. For meat confit, seasoning and a slow cook in fat develop tenderness; the fat need not come from that animal. Garlic and other vegetables can cook gently in oil. Historical preservation is separate from the kitchen's current cooling and storage procedure.`,guest:`It is gently cooked in fat or oil until tender; the chef may crisp the outside afterward.`,kitchen:`For a duck leg, tenderness comes during the gentle fat cook; a later crisping stage is separate. Garlic can confit in oil.`,compare:`Confit favors gentle tenderizing; frying uses much hotter fat to create a crust.`,correction:``,sources:[{title:`ICE: Bold Holiday Flavors from Chef Anthony Ricco`,url:`https://www.ice.edu/blog/bold-holiday-flavors-chef-anthony-ricco-spice-market`},{title:`ICE: How to Amplify the Flavor of Plants`,url:`https://www.ice.edu/blog/adding-flavor-to-plant-based-meals`}],reviewedOn:`2026-10-15`},{id:`methods-cured`,term:`Cured`,category:`methods`,aliases:[],ref:`c:fd_0030`,definition:`Treated with a controlled salt cure, sometimes followed by drying or smoking. Curing changes taste, texture and keeping quality. Some cures use nitrite as well as salt. Cured ham may be ready to eat or still need cooking; appearance cannot settle that question. Follow the product instructions and kitchen procedure.`,guest:`It has been salt-cured, which changes its texture and concentrates its savory character.`,kitchen:`Identify the product and its instructions before deciding whether it belongs directly on a board or must be cooked.`,compare:`Curing, smoking and cooking are different processes; ready to eat describes the finished product.`,correction:``,sources:[{title:`USDA FSIS: Bacon and Food Safety`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-catfish/bacon-and-food-safety`},{title:`USDA FSIS: Hams and Food Safety`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-catfish/hams-and-food-safety`}],reviewedOn:`2026-10-20`},{id:`methods-fried`,term:`Fried`,category:`methods`,aliases:[],ref:`c:fd_0031`,definition:`Cooked in hot oil until the outside turns crisp and golden. Deep frying submerges food in hot fat; pan frying uses a shallower layer. Surface moisture escapes and browning develops. A batter or crumb coating is common but optional: uncoated potatoes can also become crisp. The recipe determines the fat temperature, coating and finished texture.`,guest:`It is cooked in hot fat for a crisp surface; I can describe the coating used on this dish.`,kitchen:`Distinguish pan frying from full immersion before describing the finish; verify any coating separately.`,compare:`Deep frying immerses food; pan frying uses less fat; sautéing uses a thin film with small or thin pieces.`,correction:``,sources:[{title:`Escoffier / Gisslen: Professional Cooking, chapter 6`,url:`https://resources.escoffier.edu/textbooks/gisslen/professional_cooking_06.pdf`}],reviewedOn:`2026-10-20`},{id:`methods-grilled`,term:`Grilled`,category:`methods`,aliases:[],ref:`c:fd_0032`,definition:`Cooked over direct heat on a grill, usually on a metal grate. Grilling places food on an open grid over a heat source, which may use charcoal, gas or electricity. The hot grate and radiant heat brown the surface. Smoke character depends on the equipment, fuel and preparation.`,guest:`It is cooked over direct heat on a grill, giving the surface a browned finish.`,kitchen:`Learn the house heat source before promising wood smoke. Grill marks alone do not identify fuel.`,compare:`Grilling, griddling and smoking are different processes, even when menus use casual language.`,correction:``,sources:[{title:`Escoffier: Essential Glossary of Cooking Terms`,url:`https://www.escoffier.edu/blog/culinary-arts/the-essential-glossary-of-cooking-terms-for-the-culinary-arts/`}],reviewedOn:`2026-10-15`},{id:`methods-pickled`,term:`Pickled`,category:`methods`,aliases:[],ref:`c:fd_0033`,definition:`Kept in a sour liquid, usually vinegar, so it turns tangy and sharp. Vegetables, fruit, eggs or fish sit in vinegar with salt and often sugar and spices. The acid seasons them all the way through, and raw vegetables keep their crunch. Quick pickles are ready in hours; fermented pickles get their sourness from bacteria over days.`,guest:`Pickled means kept in vinegar or brine, so it turns tangy and keeps its crunch. On our Thanksgiving shrimp sauce piquante, pickled peppers gave a sharp, bright bite against the warm tomato gravy.`,kitchen:`Ask whether sourness comes from added vinegar or fermentation before explaining a pickle.`,compare:`Quick pickles use added acid; fermented pickles develop acid in a salt brine.`,correction:``,sources:[{title:`National Center for Home Food Preservation: Pickled Products`,url:`https://nchfp.uga.edu/papers/UGA_Publications/uga_pickled_products.pdf`},{title:`Wikipedia: Pickling`,url:`https://en.wikipedia.org/wiki/Pickling`},{title:`History.com: Pickles Through History`,url:`https://www.history.com/articles/pickles-history-timeline`},{title:`Colonial Williamsburg: A Little Goes a Long Way`,url:`https://www.colonialwilliamsburg.org/discover/resource-hub/trend-tradition-magazine/trend-tradition-summer-2025/a-little-goes-a-long-way/`},{title:`Monticello: Jefferson Era Recipe, Pepper Vinegar`,url:`https://monticello.org/exhibits-events/blog/jefferson-era-recipe-pepper-vinegar`},{title:`64 Parishes: Tabasco Sauce`,url:`https://64parishes.org/entry/tabasco-sauce`},{title:`TABASCO Brand: Our History`,url:`https://www.tabasco.com/our-history/`},{title:`Wikipedia: Edmund McIlhenny`,url:`https://en.wikipedia.org/wiki/Edmund_McIlhenny`}],reviewedOn:`2026-10-15`,say:`PIK-uld`,background:`People kept food in brine and vinegar long before anyone wrote a recipe down. Pickling is generally traced to Mesopotamia around 2400 BCE, the date the New York Food Museum gives, though its true start is unknown. In the American South, peppers steeped in vinegar became part of the table. The Virginia House-Wife, the 1824 cookbook of Mary Randolph (1762 to 1828), set down a vinegar flavored with cayenne peppers, and Colonial Williamsburg and Monticello have both published versions of it. In Louisiana, Edmund McIlhenny (1815 to 1890) grew his first commercial crop of peppers on Avery Island in 1868 for a sauce of peppers, Avery Island salt and vinegar, and the next year he sent 658 bottles to grocers around the Gulf Coast, many of them in New Orleans.`,metAt:`Brennan's Thanksgiving Day 2026: the pickled peppers on the Shrimp Sauce Piquante`},{id:`methods-poached`,term:`Poached`,category:`methods`,aliases:[],ref:`c:fd_0034`,definition:`Cooked in hot liquid that never bubbles, so it stays soft and moist. Poaching gently cooks food in hot liquid with little movement. Water, stock, wine, milk or other suitable liquids can be used. The method gives little surface browning; the food, cooking time and kitchen specification determine the finished texture.`,guest:`Poached means cooked gently in liquid kept below a boil, so it stays tender and moist with almost no browning. A poached egg is the classic: the white sets soft around a yolk that stays runny. On our Thanksgiving menu the Veal Grillades came with a poached egg, its yolk running into the gravy.`,kitchen:`Watch for barely moving liquid rather than a rolling boil; identify the poaching liquid in the actual recipe.`,compare:`Poaching is gentler than simmering; boiling has stronger agitation.`,correction:``,sources:[{title:`Escoffier: Learning How to Cook`,url:`https://www.escoffier.edu/blog/value-of-culinary-education/learning-how-to-cook-a-guide-for-beginners/`},{title:`Merriam-Webster: Poach`,url:`https://www.merriam-webster.com/dictionary/poaching`},{title:`Wiktionary: Poach`,url:`https://en.wiktionary.org/wiki/poach`},{title:`Etymonline: Poach`,url:`https://www.etymonline.com/fr/word/poach`},{title:`Wikipedia: Eggs Sardou`,url:`https://en.wikipedia.org/wiki/Eggs_Sardou`},{title:`Wikipedia: Victorien Sardou`,url:`https://en.wikipedia.org/wiki/Victorien_Sardou`},{title:`Tulane University: Cooking in New Orleans, 1950 to 2000`,url:`https://exhibits.tulane.edu/exhibit/cookdat/1950-2000/`},{title:`UPI: The Brennans, a Restaurant Family`,url:`https://www.upi.com/Archives/1982/05/20/The-Brennans-a-restaurant-familyNEWLNIdeas-that-worked-One-that-didnt/5758390715200/`},{title:`Brennan’s: Traditions`,url:`https://brennansneworleans.com/traditions`},{title:`Barry Popik: Eggs Hussarde`,url:`https://barrypopik.com/blog/eggs_hussarde`}],reviewedOn:`2026-10-15`,say:`POHCHT`,background:`Poach comes from the Old French pocher, which dictionaries tie to poche, a pocket or bag: Merriam-Webster gives poché, literally bagged, and the usual account, offered as likely rather than proven, is that the set white forms a pouch around the yolk of a poached egg. The egg is where the cooking word began. In New Orleans the poached egg became a breakfast tradition of its own. Antoine’s Eggs Sardou, poached eggs on artichoke bottoms with hollandaise, is named for the French dramatist Victorien Sardou (1831 to 1908). Breakfast at Brennan’s had made its name by the mid 1950s on a menu that featured poached eggs, among them Eggs Hussarde, poached eggs with Canadian bacon, marchand de vin sauce and hollandaise, a dish older than the restaurant that Brennan’s made part of its breakfast from about 1950.`,metAt:`Brennan's Thanksgiving Day 2026: the poached egg on the Veal Grillades`},{id:`methods-preserved`,term:`Preserved`,category:`methods`,aliases:[],ref:`c:fd_0035`,definition:`Prepared by a process that extends keeping quality beyond fresh food. Preservation is a family of methods, including drying, freezing, fermentation, pickling, curing and canning. Different processes control spoilage differently. The word alone does not tell you how long food keeps or whether it needs refrigeration.`,guest:`The ingredient has been prepared to keep longer; its particular method shapes the flavor and texture.`,kitchen:`Name the actual process: dried, frozen, fermented, pickled, cured or canned. The word alone does not give a storage rule.`,compare:`Preserved names a purpose, while pickled or dried names a particular process.`,correction:``,sources:[{title:`National Center for Home Food Preservation: Historical Origins of Food Preservation`,url:`https://nchfp.uga.edu/resources/entry/historical-origins-of-food-preservation`}],reviewedOn:`2026-10-15`},{id:`methods-pureed`,term:`Puréed`,category:`methods`,aliases:[`Purée`],ref:`c:fd_0036`,definition:`Blended or passed smooth, with thickness suited to the dish. Food is blended or passed through a sieve to reduce pieces and fibers. The result can be a thick accompaniment or a pourable soup or sauce. Added liquid and the ingredient itself determine consistency; a mash generally retains more texture.`,guest:`Puréed means cooked and then blended or pressed through a fine sieve until smooth; the word is French, from a verb meaning to purify or strain. On Thanksgiving Day the potatoes under the beef tenderloin and our herbed potato side were both purées, silky rather than fluffy.`,kitchen:`Use the recipe's target: a plate accompaniment may mound, while a puréed soup pours.`,compare:`A mash can retain pieces; a purée is smoother. Thickness is a separate choice.`,correction:``,sources:[{title:`ICE: Chilled Asparagus & Fresh Herb Soup`,url:`https://www.ice.edu/blog/chilled-asparagus-fresh-herb-soup`},{title:`Escoffier: Essential Glossary of Cooking Terms`,url:`https://www.escoffier.edu/blog/culinary-arts/the-essential-glossary-of-cooking-terms-for-the-culinary-arts/`},{title:`Merriam-Webster: purée`,url:`https://www.merriam-webster.com/dictionary/pur%C3%A9e`},{title:`Dictionary.com: purée`,url:`https://www.dictionary.com/browse/puree`},{title:`Wikipedia: Purée`,url:`https://en.wikipedia.org/wiki/Puree`},{title:`America's Test Kitchen: French-Style Mashed Potatoes (Pommes Purée)`,url:`https://www.americastestkitchen.com/recipes/9246-french-style-mashed-potatoes-pommes-puree`}],reviewedOn:`2026-10-15`,say:`pyoo-RAYD`,background:`The word is French. Purée is the past participle of the verb purer, to purify or strain, from the Latin purus, pure; in Old French it meant something made pure or refined, which fits a food pressed through a sieve until only the smooth part is left. English took the noun early in the eighteenth century, and the verb, to purée, much later. In the classic French kitchen cooked food was forced through a tamis, a fine drum sieve, and a ricer or food mill does the same work; a blender gives a smooth result faster but can turn starchy potatoes gluey. A purée may be served as it is, thinned into a soup, or stirred into a sauce to thicken it.`,metAt:`Brennan's Thanksgiving Day 2026: the pommes purée of the Herb Roasted Beef Tenderloin and the Herbed Potato Purée side`},{id:`methods-roasted`,term:`Roasted`,category:`methods`,aliases:[],ref:`c:fd_0037`,definition:`Cooked by dry heat in an oven until browned outside and tender inside. Roasting exposes food to dry oven heat, allowing the surface to brown while the interior cooks. Basting or some liquid in the tray does not automatically make it a braise. In a braise, covered moist cooking is the main method.`,guest:`Roasted means cooked in the dry heat of the oven, so the outside browns and the flavor deepens while the inside stays juicy. On Thanksgiving Day that was the buttermilk brined turkey breast, the herb roasted beef tenderloin and its Brussels sprouts, and the apples with the pork.`,kitchen:`Ask what cooks the food: exposed dry oven heat or a covered moist environment.`,compare:`Braising relies on a covered moist environment; roasting exposes the surface to dry heat.`,correction:``,sources:[{title:`Escoffier / Gisslen: Professional Cooking, chapter 6`,url:`https://resources.escoffier.edu/textbooks/gisslen/professional_cooking_06.pdf`},{title:`Encyclopedia.com: Roasting`,url:`https://www.encyclopedia.com/sports-and-everyday-life/food-and-drink/food-and-cooking/roasting`},{title:`Wikipedia: Roasting`,url:`https://en.wikipedia.org/wiki/Roasting`},{title:`Online Etymology Dictionary: roast`,url:`https://www.etymonline.com/word/roast`},{title:`Dictionary.com: roast`,url:`https://www.dictionary.com/browse/roast`},{title:`Merriam-Webster: The Difference Between Baking and Roasting`,url:`https://www.merriam-webster.com/words-at-play/baking-vs-roasting`},{title:`Modern Farmer: What’s the Difference Between Baking and Roasting?`,url:`https://modernfarmer.com/2021/07/whats-the-difference-between-baking-and-roasting/`},{title:`Dictionary.com: Roast vs. Bake`,url:`https://www.dictionary.com/e/roast-vs-bake/`}],reviewedOn:`2026-10-15`,say:`ROHST-id`,background:`Roasting is among the oldest ways of cooking: from prehistory people held meat over an open fire, and for centuries a roast meant meat turned on a spit before the flames. Cooking in a closed oven was long the work of baking, while roasting meant cooking before or over a fire, and the line between the two words was clearer before modern kitchen appliances: until gas stoves spread in the late nineteenth and early twentieth centuries, roasting was done at home and baking often in communal or commercial ovens. The English word came from the Old French rostir, of Germanic origin. Today the two words overlap in ordinary kitchens, though roasting usually describes meats and vegetables browned in the dry heat of the oven, and baking breads, cakes and pastries.`,metAt:`Brennan's Thanksgiving Day 2026: Roasted Buttermilk-Brined Turkey Breast, Herb Roasted Beef Tenderloin with roasted Brussels sprouts, Bacon-Wrapped Pork Tenderloin with roasted apples, and the roasted sunflower seeds of the Endive Satsuma Salad`},{id:`methods-sauteed`,term:`Sautéed`,category:`methods`,aliases:[],ref:`c:fd_0038`,definition:`Cooked quickly in a little hot fat, turned or tossed as needed. Sautéing suits small or thin pieces and uses little fat. Small vegetables may be tossed; a delicate fillet is usually turned carefully. Constant movement is not a requirement. Enough room in the pan helps moisture escape so the surface can brown.`,guest:`It is quickly cooked in a hot pan with a little fat for a lightly browned finish.`,kitchen:`Use small or thin pieces and a little fat; turning or tossing helps expose surfaces evenly.`,compare:`Sautéing uses little fat; shallow frying uses more. A fillet can be sautéed without being tossed.`,correction:``,sources:[{title:`Escoffier: Essential Glossary of Cooking Terms`,url:`https://www.escoffier.edu/blog/culinary-arts/the-essential-glossary-of-cooking-terms-for-the-culinary-arts/`},{title:`Escoffier / Gisslen: Professional Cooking, chapter 6`,url:`https://resources.escoffier.edu/textbooks/gisslen/professional_cooking_06.pdf`}],reviewedOn:`2026-10-20`},{id:`methods-seared`,term:`Seared`,category:`methods`,aliases:[],ref:`c:fd_0039`,definition:`Browned hard on a very hot surface to give it a dark, flavorful crust. Intense heat browns a food's surface and develops a savory crust, often through the Maillard reaction. Searing may begin or finish another cooking method. Its timing varies, and the browned surface does not establish the center's doneness or seal in juices.`,guest:`It has a browned, savory crust from intense heat; the kitchen controls the center separately.`,kitchen:`Describe the crust and verify the center separately. A sear can begin or finish another cooking method.`,compare:`Searing builds surface flavor; it does not establish a particular doneness or seal in juices.`,correction:``,sources:[{title:`Bon Appétit Management Company at George Fox University: Sear`,url:`https://georgefox.cafebonappetit.com/cooking/sear`},{title:`Exploratorium: Caramels: A Story of Sugar`,url:`https://annex.exploratorium.edu/cooking/bread/caramels-story.html`}],reviewedOn:`2026-10-15`},{id:`methods-simmered`,term:`Simmered`,category:`methods`,aliases:[],ref:`c:fd_0040`,definition:`Cooked gently in liquid with small bubbles breaking now and then. The liquid sits just under boiling, about 85 to 96 C (185 to 205 F), with small bubbles breaking now and then. That is hot enough to soften tough cuts, beans and grains and pull flavor into a stock, yet calm enough not to shred meat or cloud a broth.`,guest:`It is gently cooked in a lightly bubbling liquid, allowing the flavors to come together.`,kitchen:`For stocks or tenderizing a tougher cut, keep the movement gentle and monitor the actual food.`,compare:`Poach: barely moving. Simmer: gentle bubbles. Boil: rolling agitation.`,correction:``,sources:[{title:`Escoffier: Learning How to Cook`,url:`https://www.escoffier.edu/blog/value-of-culinary-education/learning-how-to-cook-a-guide-for-beginners/`}],reviewedOn:`2026-10-15`},{id:`methods-smoked`,term:`Smoked`,category:`methods`,aliases:[],ref:`c:fd_0041`,definition:`Flavored, and often slowly cooked, by the fumes of smoldering wood. Smoke adds aroma and changes appearance. Hot smoking includes cooking; cold smoking does not provide a pathogen kill step. A smoke ring or silky texture does not prove readiness to eat. Follow the product instructions and kitchen procedure.`,guest:`Smoked means flavored by the fumes of smoldering hardwood, which gives meat a deep, savory aroma and a darker color. The smoke comes through the andouille in our seafood gumbo, and on the Thanksgiving Day menu it came through the bacon in the gratin and around the pork tenderloin; which wood each producer uses is a question for the kitchen.`,kitchen:`Ask whether the product is hot-smoked, cold-smoked or smoke-flavored, and how it is served.`,compare:`Hot smoking includes cooking; cold smoking does not provide a pathogen kill step. Curing is a separate process.`,correction:``,sources:[{title:`USDA FSIS: Smoking Meat and Poultry`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/smoking-meat-and-poultry`},{title:`Speck Alto Adige Consortium: Production`,url:`https://www.speck.it/en/production`},{title:`FDA: Cold smoking is not a pathogen kill step`,url:`https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/warning-letters/acme-smoked-fish-corp-613859-07122021`},{title:`Colonial Williamsburg Journal: Smokehouses`,url:`https://research.colonialwilliamsburg.org/Foundation/journal/Winter04-05/smoke.cfm`}],reviewedOn:`2026-10-20`,say:`SMOHKT`,background:`Smoking is one of the old ways of keeping meat, though salt did much of the keeping while smoke added aroma and color. In colonial Virginia the smokehouse was a fixture of farm and plantation: the earliest known use of the word, written smoak house, is a 1716 record from York County, and hogs killed in early winter were salted, then hung over a slow fire for one to two weeks. Hickory, apple and maple are the woods the USDA names for the most satisfactory smoke flavor. In Louisiana, andouille makers of the River Parishes smoke their sausage hard, often over pecan wood. Hot smoking cooks as it flavors; cold smoking does not.`,metAt:`Brennan's Thanksgiving Day 2026: the andouille in the Seafood Gumbo, and the bacon in the Rockefeller Gratin and around the Bacon-Wrapped Pork Tenderloin`},{id:`methods-sousvide`,term:`Sous Vide`,category:`methods`,aliases:[],ref:`c:fd_0042`,definition:`Cooked in a sealed pouch using carefully controlled time and temperature. Food in a sealed pouch cooks in a controlled water bath. The stable temperature limits overheating, but time still changes texture, so food should not be held indefinitely. A separate sear can add browning when the recipe calls for it.`,guest:`It is cooked at a carefully controlled temperature for an even texture, then finished as the dish requires.`,kitchen:`Follow the specified time as well as temperature; prolonged holding can soften texture too far.`,compare:`Temperature controls heating; time still affects tenderness and texture.`,correction:``,sources:[{title:`ChefSteps: How long can food remain in the water?`,url:`https://support.chefsteps.com/hc/en-us/articles/360009639214-How-long-can-I-leave-my-food-in-the-water-after-the-cook-is-finished`}],reviewedOn:`2026-10-15`},{id:`methods-wilted`,term:`Wilted`,category:`methods`,aliases:[],ref:`c:fd_0043`,definition:`Greens heated just until they slump, still bright and barely cooked. A short hit of heat from a hot pan, hot broth or a warm dressing bursts the leaf's cell membranes, so it goes limp and releases water. Stopped there, the greens stay vivid and fresh tasting. Spinach, chard and tender lettuces take seconds; cooked longer, they turn dull and stewed.`,guest:`Wilted greens are warmed just until the leaves soften, so they stay tender and bright rather than stewed.`,kitchen:`Watch leafy greens lose volume and soften; the goal can be tender leaves without a long braise.`,compare:`Wilted is a light softening; braised greens usually undergo a longer moist cook.`,correction:``,sources:[{title:`University of Wyoming Extension: Spinach in the Kitchen`,url:`https://uwyoextension.org/uwnutrition/newsletters/the-popeye-power-of-spinach/`},{title:`Blind Pig and the Acorn: Killed Lettuce, with the Dictionary of Smoky Mountain English entry`,url:`https://blindpigandtheacorn.com/killed-lettuce/`},{title:`Blue Ridge Country: Killed Lettuce, The Taste of Spring`,url:`https://blueridgecountry.com/flavors/killed-lettuce-the-taste-of-spring/`},{title:`Brennan's New Orleans: Breakfast and Lunch menu, the Pecan Gulf Fish with wilted collard greens`,url:`https://www.brennansneworleans.com/menus/breakfast-and-lunch/`}],reviewedOn:`2026-10-15`,say:`WIL-tid`,background:`A plant wilts when its cells lose the water pressure, called turgor, that holds a leaf firm, and a cook wilts greens on purpose with a short burst of heat from a hot pan, a hot broth or a hot dressing. Appalachian cooks made a spring dish of it, killed lettuce or killed salad, also spelled kilt, in which hot grease is poured over fresh garden lettuce so the leaves just slump. The Dictionary of Smoky Mountain English defines killed salad as a salad made by pouring boiling grease over lettuce or other greens, the same as wilted salad. The same quick heat suits spinach, which takes seconds, and the sturdier collard greens that Brennan's everyday menu of November 2026 set wilted under its Pecan Gulf Fish.`,metAt:`Brennan's Thanksgiving Day 2026: Classic Turtle Soup, its brown butter spinach; on the everyday menu, the wilted collard greens under the Pecan Gulf Fish`},{id:`methods-flambe`,term:`Flambé`,category:`methods`,aliases:[`Flambéed`,`Flamed`],definition:`To flame a dish: a spirit such as rum, brandy or cognac is added to the warm pan and lit, and it burns briefly over the food. What burns is the alcohol vapor above the pan, and the flame goes out by itself once the vapor is spent. Much of the alcohol stays behind: in the USDA’s retention figures a flamed dish kept about 75 percent of its alcohol. The word is French, the past participle of flamber, to flame or singe.`,guest:`Flambé means flamed: the rum goes into the warm pan and we light it, and it burns for a moment over the bananas while the caramel deepens. It is a show, and it is flavor too. The flame does not burn off all the alcohol, so if you are avoiding alcohol, please tell me.`,kitchen:`The spirit is measured into a small vessel first, never poured from the bottle near a flame, and added with the pan pulled off the heat; the far edge of the pan is then tilted to the flame to light it, away from the server and the guests, and the flame burns out before the plate is made. No alcohol ever goes into a pan that is already alight.`,compare:`Its nearest neighbor is brûlée, as in crème brûlée: both are named for fire, but a brûlée crust is sugar scorched until it browns, with no spirit at all, while a flambé is a spirit set alight in the pan. Alcohol and a live flame are the tell.`,correction:``,sources:[{title:`Merriam-Webster: flambé`,url:`https://www.merriam-webster.com/dictionary/flamb%C3%A9`},{title:`Dictionary.com: flambé`,url:`https://www.dictionary.com/browse/flambe`},{title:`Wikipedia: Flambé`,url:`https://en.wikipedia.org/wiki/Flamb%C3%A9`},{title:`Wikipedia: Cooking with alcohol`,url:`https://en.wikipedia.org/wiki/Cooking_with_alcohol`},{title:`Idaho State University: No Worries, the Alcohol Burns Off During Cooking, But Does It Really?`,url:`https://isu.edu/news/2019-fall/no-worries-the-alcohol-burns-off-during-cookingbut-does-it-really.html`},{title:`PubMed: Alcohol retention in food preparation`,url:`https://pubmed.ncbi.nlm.nih.gov/1556354/`},{title:`Wikipedia: Crêpes Suzette`,url:`https://en.wikipedia.org/wiki/Cr%C3%AApes_Suzette`},{title:`Tasting Table: The Disastrous Royal Origins Of Crêpes Suzette`,url:`https://www.tastingtable.com/1259273/disastrous-royal-origins-crepes-suzette`},{title:`Antoine’s: A Fiery Finale: Cafe Brulot in New Orleans’ old line restaurants`,url:`https://antoines.com/?p=69977`},{title:`New Orleans & Company: The Café Brulot Diabolique`,url:`https://www.neworleans.com/drink/cocktails/cafe-brulot-diabolique`},{title:`Tasting Table: Pots De Crème Vs Crème Brûlée: What’s The Difference?`,url:`https://www.tastingtable.com/1674715/pots-de-creme-vs-creme-brulee-difference`},{title:`Wikipedia: Antoine’s`,url:`https://en.wikipedia.org/wiki/Antoine%27s`}],reviewedOn:`2026-11-27`,say:`flahm-BAY`,background:`Flambé is French for flamed, the past participle of flamber, to flame or singe, and Merriam-Webster dates the word in English to 1914 as an adjective and to about 1946 as a verb. The usual story of the flamed dessert, that crêpes Suzette caught fire by accident in the 1890s at the Café de Paris in Monte Carlo, comes from the memoir of the waiter who claimed it, and it is disputed: Larousse Gastronomique contradicts it, and other accounts credit other Paris restaurants. New Orleans kept flamed classics of its own. Café brûlot, coffee with brandy, spices and citrus peel set alight at the table, is credited to Antoine’s in the late nineteenth century, and Bananas Foster, flamed with rum at the table, joined it at Brennan’s in 1951.`,metAt:`Brennan's Thanksgiving Day 2026: World Famous Bananas Foster, flambéed tableside`},{id:`methods-gueridon`,term:`Guéridon`,category:`methods`,aliases:[`Guéridon service`,`Gueridon`,`Tableside cart`],definition:`A small movable side table or cart drawn up beside the guest’s table, on which a server carves, dresses, finishes or flames a dish in the guest’s view. Guéridon service is the name for this way of serving: the dish is made or finished at the table rather than plated in the kitchen, and the cart often carries a small burner. In furniture the word is older: a guéridon is a small round pedestal table, first made in France in the seventeenth century.`,guest:`The cart we bring beside your table is called a guéridon, a French word for a small side table. Everything for your Bananas Foster is on it, the pan, the burner, the butter and sugar, the bananas and the rum, so you can watch your dessert made and flamed right beside you.`,kitchen:`The cart is set from the kitchen before it goes out, with the burner, the pan, the measured spirit and every ingredient, so the server never leaves the table in the middle of the dish. It is placed where nothing hangs overhead and away from drapes and paper, with a lid within reach to smother a flame.`,compare:`Its nearest neighbor is the dessert trolley, which wheels finished desserts to the table to be chosen: a guéridon is a working station on which the dish is cooked, carved or flamed. Whether the food is made on it, not merely carried, is the tell.`,correction:``,sources:[{title:`Wikipedia: Guéridon service`,url:`https://en.wikipedia.org/wiki/Gu%C3%A9ridon_service`},{title:`CooksInfo: Gueridon Service`,url:`https://www.cooksinfo.com/gueridon-service`},{title:`Office québécois de la langue française: guéridon de service`,url:`https://vitrinelinguistique.oqlf.gouv.qc.ca/fiche-gdt/fiche/17567293/gueridon-de-service`},{title:`Wikipedia: Guéridon`,url:`https://en.wikipedia.org/wiki/Gu%C3%A9ridon`},{title:`Britannica: Pedestal table`,url:`https://www.britannica.com/technology/gueridon`},{title:`Dictionary.com: gueridon`,url:`https://www.dictionary.com/browse/gueridon`},{title:`The Metropolitan Museum of Art: Pedestal in the form of a Moor, from Guéridons`,url:`https://www.metmuseum.org/art/collection/search/432780`},{title:`Merriam-Webster: gueridon`,url:`https://www.merriam-webster.com/dictionary/gueridon`},{title:`Bernardaud: Le service à la russe`,url:`https://www.bernardaud.com/en/us/news/le-service-a-la-russe`},{title:`Wikipedia: Service à la russe`,url:`https://en.wikipedia.org/wiki/Service_%C3%A0_la_russe`}],reviewedOn:`2026-11-27`,say:`gay-ree-DOHN`,background:`The guéridon began as furniture. It appeared in France as a small pedestal table in the seventeenth century, and its early supports were often carved as standing figures: a print in the Metropolitan Museum of Art, from a seventeenth century book of guéridon designs, shows one as a pedestal in the form of a Moor. The name is usually traced to Guéridon, a stock character of seventeenth century French farces and popular songs, though the origin is not settled. In restaurants the word passed to the side table or cart on which a waiter carves, dresses and flames dishes beside the guest. The practice grew out of service à la russe, the course by course service that reached Paris early in the nineteenth century, in which dishes were carved on a side table and handed round by the waiters, course by course.`,metAt:`Brennan's Thanksgiving Day 2026: World Famous Bananas Foster, made on the cart at the table`},{id:`methods-gratin`,term:`Gratin`,category:`methods`,aliases:[`Au gratin`],definition:`A dish baked or broiled until a browned crust forms on top, usually of breadcrumbs, cheese, butter or a mix of them. The word names the crust as much as the dish. It is usually made in a shallow dish, so more of what is underneath lies close to the crust. Potatoes, vegetables, pasta and seafood are all cooked this way.`,guest:`A gratin is anything baked until it wears a golden crust on top; the word comes from the French for to scrape, after the browned bits cooks scraped from the pan. On our Thanksgiving Day menu it was oysters with bacon and creamed spinach under breadcrumbs, baked until the top turned crisp.`,kitchen:`Topped with crumbs, cheese or butter and finished in a hot oven or under the broiler until the surface browns and the filling is hot through.`,compare:`Gratin dauphinois, the potato gratin of the Dauphiné, is by tradition made without cheese; au gratin in American usage often means with cheese, but the crust, not the cheese, is what the word names.`,correction:``,sources:[{title:`Wikipedia: Gratin`,url:`https://en.wikipedia.org/wiki/Gratin`},{title:`Merriam-Webster: au gratin`,url:`https://www.merriam-webster.com/dictionary/au%20gratin`},{title:`Wikipedia: Gratin dauphinois`,url:`https://en.wikipedia.org/wiki/Gratin_dauphinois`},{title:`Connexion France: The origins and meaning of gratin`,url:`https://www.connexionfrance.com/magazine/learning-french-the-origins-and-meaning-of-gratin/714682`},{title:`Mon séjour en montagne: Le gratin dauphinois, le plat emblématique du Dauphiné`,url:`https://www.mon-sejour-en-montagne.com/histoires-et-anecdotes/le-gratin-dauphinois-le-plat-emblematique-du-dauphine/`}],reviewedOn:`2026-11-27`,say:`GRAH-tn`,background:`Gratin comes from the French verb gratter, to scrape, which goes back to a Germanic word for scratching. It first meant the browned crust that stuck to the bottom and sides of the pot, the part cooks scraped away, and only later the dish baked to make that crust on purpose. Merriam Webster dates the English phrase au gratin, literally with the scrapings, to 1806. The potato gratin of the Dauphiné, in southeastern France, is first recorded on 12 July 1788, when a gratin was served at a dinner the province’s lieutenant general gave for the municipal officials of Gap, though the dish is surely older; by tradition it holds no cheese. In French, le gratin has also come to mean the upper crust of society, the choice top of the dish.`,metAt:`Brennan's Thanksgiving Day 2026: Rockefeller Gratin`},{id:`methods-crudo`,term:`Crudo`,category:`methods`,aliases:[`Pesce Crudo`,`Crudo di Mare`],definition:`Raw fish or shellfish, sliced or served whole, and dressed at the last moment with little more than olive oil, salt and citrus. The word is Italian for raw, and on a menu it is short for pesce crudo, raw fish. The seafood is never cooked, by heat or by a long soak in acid, so its own sweetness and texture lead. Because it is raw, a crudo carries the consumer advisory the house uses for raw food.`,guest:`Crudo is the Italian word for raw: the seafood comes to you raw, dressed just before it leaves the kitchen with citrus and a little seasoning. On Thanksgiving Day ours was sweet bay scallops with Meyer lemon, black truffle and crisp radish, cool and bright, a light way to begin.`,kitchen:`The seafood is held cold and dressed to order, never ahead, so the acid has no time to firm it. Every raw dish goes out with the house's raw food advisory, and the cut and the portion are the kitchen's to say at lineup.`,compare:`Ceviche is its nearest neighbor: in ceviche the fish sits in a good deal of citrus until its surface turns firm and opaque, while a crudo is dressed lightly at the last moment and keeps the texture of raw fish.`,correction:``,sources:[{title:`Food Network: What Is Crudo?`,url:`https://www.foodnetwork.com/how-to/packages/food-network-essentials/what-is-crudo`},{title:`The Takeout: What Is Crudo And Is It Any Different From Ceviche?`,url:`https://www.thetakeout.com/1979551/what-is-crudo-vs-ceviche/`},{title:`NPR: Chef Seeks Converts to Crudo, Italian Sashimi (2007)`,url:`https://www.npr.org/2007/07/10/11851428/chef-seeks-converts-to-crudo-italian-sashimi`},{title:`Culinary Lore: What is a Crudo?`,url:`https://culinarylore.com/dishes:what-is-a-crudo/`},{title:`Great British Chefs: Pesce crudo, Sicily's love for raw fish`,url:`https://greatbritishchefs.com/features/pesce-crudo-sicily`},{title:`The International Kitchen: Il crudo barese, the tradition of raw fish in Bari`,url:`https://theinternationalkitchen.com/blog/il-crudo-barase-or-the-tradition-of-raw-fish-in-bari`},{title:`Meer: Patrimoni di Puglia, il crudo di mare alla barese`,url:`https://www.meer.com/it/88062-patrimoni-di-puglia-il-crudo-di-mare-alla-barese`},{title:`Oregon Health Authority: Food Code fact sheet, shellfish and the consumer advisory`,url:`https://www.oregon.gov/oha/PH/HEALTHYENVIRONMENTS/FOODSAFETY/Documents/FactSheet26Shellfish.pdf`},{title:`Wikipedia: the founding chef of Esca, New York (opened 2000)`,url:`https://en.wikipedia.org/wiki/David_Pasternack`},{title:`Resy: Meet the duo behind Esca's second act`,url:`https://blog.resy.com/?p=11236`}],reviewedOn:`2026-11-27`,say:`KROO-doh`,background:`Crudo is Italian for raw, and pesce crudo, raw fish, belongs to the coasts of Italy. Sicily has long eaten raw fish, and Bari, on the Adriatic in Puglia, keeps a tradition of crudo di mare, a plate of raw octopus, cuttlefish, mussels, clams and sea urchin. As a word on American menus, crudo is newer: it reached a wide public after an Italian seafood restaurant opened in New York in 2000 with raw fish at the heart of its menu, and in 2007 NPR called it Italian sashimi. The American dish is usually thin slices of raw fish or shellfish dressed with olive oil, salt and citrus, sometimes a little vinegar, just before it goes out. On Thanksgiving Day the Brennan's menu used the word for its raw bay scallops.`,metAt:`Brennan's Thanksgiving Day 2026: Bay Scallop Crudo`},{id:`methods-meuniere`,term:`Meunière`,category:`methods`,aliases:[`À la meunière`,`Meunière sauce`],definition:`A French way with fish: the fillet or whole fish is dusted in flour, cooked in butter, and finished with brown butter, lemon and parsley. The name means in the style of the miller’s wife, and the flour is generally taken to be the point of it. Sole and trout are the classic fish. On the Thanksgiving Day menu it was Redfish Meunière, with brown butter, lemon and capers over a potato and leek écrasé.`,guest:`Meunière, said mun-YAIR, is a classic French way with fish: traditionally dusted in flour, cooked in butter, then finished with brown butter and lemon. The name means in the style of the miller’s wife, for the flour. On Thanksgiving Day ours was redfish, with brown butter, lemon and capers over crushed potatoes and leeks.`,kitchen:`The fish is floured and cooked in hot butter until golden, then the pan butter is taken to a nutty brown and sharpened with lemon at the end. Whether the house floured the redfish, and how the capers went in, was a question for lineup.`,compare:`Amandine is its nearest neighbor: the same floured fish in brown butter, with toasted sliced almonds added. New Orleans menus often join the two as meunière amandine, so the almonds are the tell.`,correction:``,sources:[{title:`Wikipedia: Meunière sauce`,url:`https://en.wikipedia.org/wiki/Meuni%C3%A8re_sauce`},{title:`Wikipedia: Sole meunière`,url:`https://en.wikipedia.org/wiki/Sole_meuni%C3%A8re`},{title:`Tasting Table: A La Meunière Is A Simple French Method For Flavorful Fish`,url:`https://tastingtable.com/1234804/a-la-meuniere-is-a-simple-french-method-for-flavorful-fish`},{title:`CooksInfo: À la Meunière`,url:`https://www.cooksinfo.com/a-la-meuniere`},{title:`Paste: Recreating Julia Child’s Lunch at La Couronne`,url:`https://pastemagazine.com/food/french-food/lunch-at-la-couronne`},{title:`Chowhound: The Fish Filled Meal That Helped Jumpstart Julia Child’s Love Of French Cooking`,url:`https://chowhound.com/1711777/french-fish-dish-julia-child-life-changing`},{title:`Wikipedia: La Couronne (restaurant)`,url:`https://en.wikipedia.org/wiki/La_Couronne_(restaurant)`},{title:`Galatoire’s: History`,url:`https://galatoires.com/history`},{title:`Wikipedia: Galatoire’s`,url:`https://en.wikipedia.org/wiki/Galatoire%27s`},{title:`Tulane University exhibit: 1900 to 1950`,url:`https://exhibits.tulane.edu/exhibit/cookdat/1900-1950/`},{title:`Saveur: Trout Meunière Amandine`,url:`https://www.saveur.com/article/Recipes/Trout-with-Brown-Butter-and-Almonds-Trout-Meuniere-Amandine/`}],reviewedOn:`2026-11-27`,say:`mun-YAIR`,background:`À la meunière is French for in the style of the miller’s wife, and the usual reading is that the flour on the fish is the miller’s mark, though no record settles where the name began. The style belongs to the French table, with sole and trout its classic fish. Julia Child (1912 to 2004) ate sole meunière at La Couronne in Rouen in November 1948, at her first lunch in France, and later called it the most exciting meal of her life. In New Orleans the style took a Gulf fish. A Tulane University exhibit tells how the founder of Galatoire’s, a cook from near Pau in southwestern France who bought the restaurant in 1905, turned Louisiana speckled trout into trout meunière, and Galatoire’s became known for trout meunière amandine, with toasted almonds in the brown butter.`,metAt:`Brennan's Thanksgiving Day 2026: Redfish Meunière`},{id:`methods-ecrase`,term:`Écrasé`,category:`methods`,aliases:[`Écrasée`,`Pommes écrasées`,`Crushed potatoes`,`Pommes de terre à la fourchette`],definition:`French for crushed: on a menu, a dish of cooked vegetables crushed with a fork or masher rather than puréed smooth, most often potatoes. It is a rustic, chunkier cousin of mashed potatoes, keeping some texture and often enriched with butter or olive oil. French cooks also call it pommes de terre à la fourchette, potatoes done with the fork. On the Thanksgiving Day menu a potato and leek écrasé sat under the Redfish Meunière.`,guest:`Écrasé, said ay-krah-ZAY, is French for crushed: potatoes crushed with a fork rather than whipped smooth, so they keep a little texture. On Thanksgiving Day ours was potato and leek, under the redfish meunière, and it soaked up the brown butter.`,kitchen:`The potatoes are cooked until tender and crushed while hot, by fork or masher, with the fat worked in lightly so they stay coarse rather than gluey. What went into the house écrasé besides potato and leek, and how the leeks were cooked, was the kitchen’s to say.`,compare:`Pommes purée is its nearest neighbor: a purée is pressed through a ricer or sieve and worked with butter until silky and smooth, while an écrasé is only crushed and keeps its lumps. Texture is the tell.`,correction:``,sources:[{title:`Dictionnaire de l’Académie française, 9e édition: écraser`,url:`https://dictionnaire-academie.fr/article/A9E0347`},{title:`Le Robert: écrasé`,url:`https://dictionnaire.lerobert.com/en/synonyms/ecrase`},{title:`Merriam-Webster: écrasé`,url:`https://merriam-webster.com/dictionary/ecrase`},{title:`Sublearn: écraser`,url:`https://sublearn.com/ko/learn/fr/vocabulary/ecraser`},{title:`Larousse: écraser`,url:`https://www.larousse.fr/dictionnaires/francais-anglais/%C3%A9craser/27568`},{title:`ProZ: pommes de terre à la fourchette`,url:`https://www.proz.com/kudoz/french_to_english/cooking_culinary/1257790-pommes_de_terre_%E0_la_fourchette.html`},{title:`Leite’s Culinaria: Fork Mashed Potatoes`,url:`https://leitesculinaria.com/59004/recipes-fork-mashed-potatoes.html`},{title:`Cookidoo: Ecrasé de pomme de terre à l’huile d’olive`,url:`https://cookidoo.co.uk/recipes/recipe/en-GB/r137249`},{title:`Bonial: Recette de pommes de terre écrasées à l’huile d’olive`,url:`https://www.bonial.fr/magazine/recette-de-pommes-de-terre-ecrasees-a-lhuile-dolive/`},{title:`National Geographic: How the potato went from banned to beloved`,url:`https://www.nationalgeographic.com/history/article/potato-history-france-western-europe`},{title:`Wikipedia: Antoine Augustin Parmentier`,url:`https://en.wikipedia.org/wiki/Antoine-Augustin_Parmentier`}],reviewedOn:`2026-11-27`,say:`ay-krah-ZAY`,background:`Écrasé is the past participle of the French verb écraser, to crush, which Merriam-Webster traces to Middle French ecraser. The Académie française gives, among the verb’s first senses, crushing potatoes to make a purée, and Le Robert records écrasé as a noun of the kitchen, a dish of a crushed food, as in un écrasé de pommes de terre. French cooks also speak of pommes de terre à la fourchette, potatoes crushed with a fork and often dressed with olive oil, and on a French menu an écrasé de pommes de terre names a coarser, rustic style than the smooth purée. The potato itself came late to French tables: the Paris Faculty of Medicine declared it fit to eat in 1772, helped by the campaign of Antoine Augustin Parmentier (1737 to 1813).`,metAt:`Brennan's Thanksgiving Day 2026: the potato and leek écrasé under the Redfish Meunière`},{id:`vegetables-arugula`,term:`Arugula`,category:`vegetables`,aliases:[],ref:`t:arugula`,definition:`A leafy mustard-family green, also called rocket, with a peppery, sometimes nutty bite. Young leaves are often milder; variety and growing conditions affect strength.`,guest:`Arugula brings a fresh, peppery bite to the salad.`,kitchen:`Choose lively leaves; wash and dry before dressing. Use raw or add near the end of cooking.`,compare:`Lettuce is usually milder; watercress is another peppery green, not the same plant.`,correction:``,sources:[{title:`University of Wisconsin Extension`,url:`https://hort.extension.wisc.edu/articles/arugula/`}],reviewedOn:`2026-10-15`},{id:`vegetables-beet`,term:`Beet`,category:`vegetables`,aliases:[],ref:`t:beet`,definition:`A sweet, earthy root vegetable with edible greens. Red, golden and striped varieties differ in color; color alone does not establish sweetness.`,guest:`Beets bring earthy sweetness; the preparation may be roasted, pickled or shaved raw.`,kitchen:`Choose firm roots. Wash well; cook until tender or shave thinly. Red beet juice can stain adjoining ingredients.`,compare:`Beet is grown mainly for its root; chard is grown for leaves and stalks.`,correction:``,sources:[{title:`University of Illinois Extension`,url:`https://extension.illinois.edu/gardening/preparing-beets`}],reviewedOn:`2026-10-15`},{id:`vegetables-broccolini`,term:`Broccolini`,category:`vegetables`,aliases:[],ref:`t:broccolini`,definition:`A long-stemmed green vegetable with small broccoli-like florets. Its tender stalks, leaves and florets are eaten together.`,guest:`Broccolini has slender stems and a gentle broccoli flavor.`,kitchen:`Wash, trim dry ends and judge the actual stems. Split thick stems if needed; roast, grill or sauté until the stem is tender.`,compare:`It is not simply an immature head of standard broccoli; broccoli rabe is a different, more bitter vegetable.`,correction:``,sources:[{title:`veggiesmadeeasy.com`,url:`https://veggiesmadeeasy.com/canada/products/broccolini-2/`}],reviewedOn:`2026-10-15`},{id:`vegetables-brusselssprouts`,term:`Brussels Sprouts`,category:`vegetables`,aliases:[],ref:`t:brussels-sprouts`,definition:`Small, compact leafy buds that grow along a stalk in the cabbage family. They have a cabbage-like flavor and can be steamed, sautéed or roasted.`,guest:`Brussels sprouts are tiny cabbages that grow in a spiral up a tall stalk, named for the region around Brussels in Belgium. On Thanksgiving Day they came roasted with the beef tenderloin, and roasting browns their edges and turns them nutty and sweet against the rich beef and the pepper sauce.`,kitchen:`Select firm heads of similar size. Remove damaged outer leaves and halve larger sprouts for more even cooking.`,compare:`They are not miniature harvested cabbages; each is a side bud on a larger plant.`,correction:``,sources:[{title:`University of Illinois Extension`,url:`https://extension.illinois.edu/gardening/preparing-brussels-sprouts`},{title:`Wikipedia: Brussels sprout`,url:`https://en.wikipedia.org/wiki/Brussels_sprout`},{title:`Library of Congress, Bibliomania: The Sprout Incident of FDR and Lady Churchill`,url:`https://blogs.loc.gov/bibliomania/2024/01/12/the-sprout-incident-of-fdr-and-lady-churchill/`},{title:`The Brussels Times: A Belgian history of the Brussels sprout`,url:`https://brusselstimes.com/835109/a-belgian-history-of-the-brussels-sprout`},{title:`Harvard T.H. Chan School of Public Health, The Nutrition Source: Brussels Sprouts`,url:`https://www.hsph.harvard.edu/nutritionsource/food-features/brussels-sprouts/`},{title:`FoodPrint, Real Food Encyclopedia: Brussels Sprouts`,url:`https://foodprint.org/?p=7333`},{title:`NPR: From Culinary Dud To Stud: How Dutch Plant Breeders Built Our Brussels Sprouts Boom`,url:`https://www.npr.org/sections/thesalt/2019/10/30/773457637/from-culinary-dud-to-stud-how-dutch-plant-breeders-built-our-brussels-sprouts-bo`},{title:`The Takeout: Why Brussels Sprouts Taste Different`,url:`https://thetakeout.com/1780497/why-brussels-sprouts-taste-different`},{title:`University of Arkansas Cooperative Extension, Plant of the Week: Brussels Sprouts`,url:`https://uaex.uada.edu/yard-garden/resource-library/plant-week/brussels-sprouts-5-17-13.aspx`}],reviewedOn:`2026-10-15`,say:`BRUS-elz SPROWTS`,background:`Brussels sprouts are a form of the wild cabbage, Brassica oleracea, bred to set small heads in a spiral up a tall stalk. They take their name from the land around Brussels, in what is now Belgium, where they may have been grown as early as the thirteenth century and were widely cultivated by the sixteenth; in French they are choux de Bruxelles, Brussels cabbages. No authoritative botanical history has been written, so the early dates stay uncertain. When they reached the United States is unclear too, but French settlers in Louisiana are known to have grown them. Their modern revival owes much to Dutch breeders, who in the 1990s found the compounds behind the old bitterness and crossed milder heirloom seed into modern varieties, so the sprout served today is sweeter than the one many guests remember.`,metAt:`Brennan's Thanksgiving Day 2026: the roasted Brussels sprouts of the Herb Roasted Beef Tenderloin`},{id:`vegetables-capers`,term:`Capers`,category:`vegetables`,aliases:[],ref:`c:fd_0278`,definition:`Unopened flower buds preserved in salt or brine. They add concentrated saltiness and a tangy bite. Caperberries are the later fruit.`,guest:`Capers are the small flower buds of a Mediterranean shrub, picked before they open and cured in salt or brine. On Thanksgiving Day, in the brown butter with the lemon, they added a bright, briny pop that cut through the richness of the redfish.`,kitchen:`Check whether packed in salt or brine. Rinse or soak as the recipe requires and taste before adding more salt.`,compare:`Caperberries are larger, seeded fruits, often served with a stalk; they are not just oversized capers.`,correction:``,sources:[{title:`Royal Horticultural Society`,url:`https://www.rhs.org.uk/plants/92942/capparis-spinosa/details`},{title:`Cook's Illustrated: Capers taste test`,url:`https://cooksillustrated.com/taste_tests/1971-capers`},{title:`WIPO Magazine: GI protection revives caper production on Pantelleria`,url:`https://www.wipo.int/en/web/wipo-magazine/articles/gi-protection-revives-caper-production-on-pantelleria-42042`},{title:`Saveur: Sole à la Grenobloise`,url:`https://www.saveur.com/article/recipes/sole-a-la-grenobloise`}],reviewedOn:`2026-10-15`,say:`KAY-perz`,background:`Capers are the unopened flower buds of the caper bush, Capparis spinosa, a sprawling shrub that grows wild around the Mediterranean. The buds are picked by hand before they open and sorted by size with sieves or screens; the smaller the bud, the more it is valued, and nonpareil is the name of the smallest grade. Sorting is not exact, so one brand's nonpareils can run more even than another's. They are cured in salt or in brine, and salt packed capers are rinsed before use. On the volcanic island of Pantelleria, off Sicily, the Cappero di Pantelleria has carried the European Union's protected geographical indication since 1996. In French cooking, fish finished in brown butter with capers and lemon is served à la grenobloise, close kin to the meunière.`,metAt:`Brennan's Thanksgiving Day 2026: Redfish Meunière`},{id:`vegetables-celeryroot`,term:`Celeriac`,category:`vegetables`,aliases:[`Celery Root`],ref:`t:celeriac`,definition:`Also called celery root: a knobbly celery variety grown for its swollen base. The pale interior tastes gently of celery, with a nutty quality.`,guest:`Celery root gives a mellow celery flavor and a smooth texture when puréed.`,kitchen:`Scrub, peel away the rough exterior and cut evenly. Use shaved in slaw, cooked in soup or puréed.`,compare:`It is not a potato, and ordinary stalk celery will not give the same body in a purée.`,correction:``,sources:[{title:`University of Illinois Extension`,url:`https://extension.illinois.edu/blogs/simply-nutritious-quick-and-delicious/2015-10-01-celery-and-celery-root`}],reviewedOn:`2026-10-15`},{id:`vegetables-chicory`,term:`Chicory`,category:`vegetables`,aliases:[],definition:`A group of cultivated bitter leafy vegetables that includes radicchio and Belgian endive. The name can also mean chicory root used in coffee.`,guest:`Chicory adds a crisp, pleasantly bitter note.`,kitchen:`Confirm which chicory the dish uses; raw leaves and braised heads have different textures.`,compare:`Frisée is curly endive, a close relative; chicory coffee uses roasted root.`,correction:``,sources:[{title:`Royal Horticultural Society`,url:`https://www.rhs.org.uk/vegetables/chicory/grow-your-own?type=v`}],reviewedOn:`2026-10-15`,relatedLexiconSlug:`chicories-and-bitter-greens`},{id:`vegetables-chives`,term:`Chives`,category:`vegetables`,aliases:[],ref:`t:chives`,definition:`Fine green allium leaves used as an herb, with a mild onion flavor. The flowers are edible too.`,guest:`Chives add a delicate, fresh onion note.`,kitchen:`Wash and dry; cut cleanly with a sharp knife or scissors. Sprinkle on shortly before serving.`,compare:`Garlic chives have flatter leaves and a more garlic-like flavor.`,correction:``,sources:[{title:`University of Wisconsin Extension`,url:`https://hort.extension.wisc.edu/articles/chives-allium-schoenoprasum/`}],reviewedOn:`2026-10-15`},{id:`vegetables-cippolini`,term:`Cipollini Onion`,category:`vegetables`,aliases:[`Cippolini`],ref:`t:cipollini-onion`,definition:`Small, flattened onions that can become sweet when cooked. Their broad, shallow shape suits whole roasting and glazing.`,guest:`Cipollini are small, flat onions with a lovely sweetness once cooked.`,kitchen:`Choose firm bulbs of similar size. Peel and trim while leaving enough base to hold the layers together.`,compare:`Pearl onions are small and rounded; cipollini are flatter and are not automatically interchangeable at the same cooking time.`,correction:``,sources:[{title:`johnnyseeds.com`,url:`https://www.johnnyseeds.com/on/demandware.static/-/Library-Sites-JSSSharedLibrary/default/dw6b02211a/assets/information/2024-johnnys-digital-master-catalog.pdf`}],reviewedOn:`2026-10-15`},{id:`vegetables-collardgreens`,term:`Collard Greens`,category:`vegetables`,aliases:[],ref:`t:collard-greens`,definition:`Large, sturdy leaves in the cabbage family. Mature leaves suit slow cooking; young leaves can be cooked more quickly.`,guest:`Collards are hearty greens; in a braise they become tender and savory.`,kitchen:`Wash thoroughly to remove grit and trim tough ribs. Confirm the stock and seasoning before describing the dish as vegetarian.`,compare:`Potlikker is the cooking liquid; collards themselves do not necessarily contain pork.`,correction:``,sources:[{title:`University of Illinois Extension`,url:`https://extension.illinois.edu/gardening/preparing-collards`}],reviewedOn:`2026-10-15`},{id:`vegetables-endive`,term:`Endive`,category:`vegetables`,aliases:[],definition:`Endive includes curly frisée and broad-leaved escarole, leafy vegetables with a pleasantly bitter flavor. Belgian endive is a different related chicory, forced into compact pale shoots; menus may shorten either name to endive.`,guest:`Endive is a crisp leaf of the chicory family with a gentle bitterness that wakes up the palate before a rich meal. In our Thanksgiving Day salad the sweet satsuma and the cherry vinaigrette rounded off that bitterness, and roasted sunflower seeds added crunch.`,kitchen:`Confirm which endive is being used. Separate and wash leafy heads for salad or cooking; Belgian shoots can be used as whole leaves or cooked in halves.`,compare:`Frisée is curly endive, escarole is broad-leaved endive, and Belgian endive is a forced chicory shoot. These names should not be used interchangeably.`,correction:``,sources:[{title:`Royal Horticultural Society`,url:`https://www.rhs.org.uk/vegetables/endive/grow-your-own`},{title:`blog-fruit-vegetable-ipm.extension.umn.edu`,url:`https://blog-fruit-vegetable-ipm.extension.umn.edu/2023/01/forcing-chicories-opportunity-for.html`},{title:`Wikipedia: Belgian endive`,url:`https://en.wikipedia.org/wiki/Belgian_endive`},{title:`The Brussels Times: Hidden Belgium, Witlof`,url:`https://www.brusselstimes.com/1894898/hidden-belgium-witlof`},{title:`Focus on Belgium: Chicory, a Belgian story`,url:`https://focusonbelgium.be/en/node/7864`},{title:`VRT NWS: Hoe Brussels is witloof?`,url:`https://www.vrt.be/vrtnws/nl/2023/01/12/jouw-vraag-hoe-brussels-is-witloof/`},{title:`Gault&Millau: Why Flanders is so proud of its endive`,url:`https://fr.gaultmillau.com/en/news/le-secret-sous-la-terre-pourquoi-la-flandre-est-si-fiere-de-son-endive`},{title:`Frontiers in Plant Science (2022): witloof chicory forcing`,url:`https://www.frontiersin.org/journals/plant-science/articles/10.3389/fpls.2022.843004/pdf`},{title:`RTBF: Le chicon serait-il né à Evere?`,url:`https://www.rtbf.be/article/le-chicon-serait-il-ne-a-evere-11442327`},{title:`VRT NWS: Le chicon, une histoire bien bruxelloise`,url:`https://www.vrt.be/vrtnws/fr/2023/07/30/le-chicon-une-histoire-bien-bruxelloise/`}],reviewedOn:`2026-10-15`,relatedLexiconSlug:`belgian-endive`,say:`EN-dyve or ahn-DEEV`,background:`Belgian endive is a chicory grown twice: once in the field for its root, then again in the dark, where the lifted root sends up a tight, pale head. The Flemish call it witloof, white leaf, and French speaking Belgians call it chicon. A popular story says a farmer near Brussels hid his chicory roots in a dark cellar during the Belgian revolution of 1830 and later found white shoots on them, but Belgian accounts treat that as legend. The method is usually credited to a head gardener of the Brussels Botanical Garden, who forced chicory roots in the dark, probably building on what local growers already knew; accounts date his work anywhere from about 1830 to the 1840s. The crop spread through Schaerbeek, Evere and Haren, around Brussels, mainly in the second half of the nineteenth century.`,metAt:`Brennan's Thanksgiving Day 2026: Endive Satsuma Salad`},{id:`vegetables-fennel`,term:`Fennel`,category:`vegetables`,aliases:[],definition:`An aromatic plant with an anise-like flavor. Herb fennel supplies feathery leaves, flowers and seeds; Florence fennel is grown for the swollen leaf bases commonly called its bulb.`,guest:`Fennel brings a gentle anise note; the bulb is crisp raw and tender when cooked.`,kitchen:`Name the part in the recipe: bulb for shaving or cooking, fronds as an herb, seeds as a spice. Stalks can flavor a stock or cooking bed when appropriate.`,compare:`Fennel is not anise or liquorice root. Herb fennel and bulb fennel have different main culinary uses, even though their aromas are related.`,correction:``,sources:[{title:`Royal Horticultural Society`,url:`https://www.rhs.org.uk/herbs/fennel/grow-your-own`},{title:`Royal Horticultural Society`,url:`https://www.rhs.org.uk/vegetables/florence-fennel/grow-your-own`}],reviewedOn:`2026-10-15`,relatedLexiconSlug:`fennel-bulb`},{id:`vegetables-frisee`,term:`Frisee`,category:`vegetables`,aliases:[],ref:`t:frisee`,definition:`Curly endive with fine, frilled leaves. The pale inner leaves are often milder than the green outer leaves.`,guest:`Frisée is a crisp, curly salad green with a pleasantly bitter edge.`,kitchen:`Wash and dry well. Use tender leaves raw; tougher outer leaves can be cooked or trimmed according to the dish.`,compare:`Different from torpedo-shaped Belgian endive. Light-exclusion blanching during growing is different from dipping food in boiling water.`,correction:``,sources:[{title:`Royal Horticultural Society`,url:`https://www.rhs.org.uk/vegetables/endive/grow-your-own?type=v`}],reviewedOn:`2026-10-15`},{id:`vegetables-haricotsverts`,term:`Haricots Verts`,category:`vegetables`,aliases:[],definition:`Slender French-style green beans, usually picked young for delicate, crisp pods. The French words literally mean green beans.`,guest:`Haricots verts, said ah-ree-koh VAIR, are French green beans: thinner and more tender than the everyday kind, picked young while the pod is slender. Cooked briefly, they stay bright green with a little snap. On Thanksgiving Day they were the green side for the table, a fresh contrast to the turkey and the stuffing.`,kitchen:`Choose firm pods; wash and trim stem ends. Cook to the intended tenderness, checking rather than relying only on a fixed time.`,compare:`They are beans, not sugar snap peas; the narrow pods usually need less time than thick mature green beans.`,correction:``,sources:[{title:`johnnyseeds.com`,url:`https://www.johnnyseeds.com/growers-library/vegetables/beans/beans-basic-types.html`},{title:`Frontiers in Plant Science: Phaseolus domestication review`,url:`https://frontiersin.org/articles/10.3389/fpls.2017.00722/full`},{title:`Genome Biology: Common bean domestication`,url:`https://link.springer.com/10.1186/s13059-017-1190-6`},{title:`PMC: The common bean in Europe`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC5420584`},{title:`Wiktionary: haricot`,url:`https://en.wiktionary.org/wiki/haricot`},{title:`American Heritage Dictionary: haricot`,url:`https://www.ahdictionary.com/word/search.html?q=haricot`},{title:`Dictionary.com: haricot`,url:`https://dictionary.com/browse/Haricot`},{title:`Mad About Macarons: Green Beans, Haricots Verts`,url:`https://www.madaboutmacarons.com/green-beans-haricots-verts/`},{title:`CooksInfo: French Fillet Beans`,url:`https://www.cooksinfo.com/french-fillet-beans`},{title:`Merriam-Webster: haricot vert`,url:`https://www.merriam-webster.com/dictionary/haricot%20vert`},{title:`Frontiers in Plant Science: Iconography of Beans and Related Legumes Following the Columbian Exchange`,url:`https://www.frontiersin.org/articles/10.3389/fpls.2022.851029/full`},{title:`Dictionnaire de l’Académie française, 9e édition: haricot`,url:`https://dictionnaire-academie.fr/article/A9H0194`},{title:`e-santé: Dans votre assiette, le haricot vert`,url:`https://www.e-sante.fr/dans-votre-assiette-le-haricot-vert/actualite/616028`}],reviewedOn:`2026-10-15`,relatedLexiconSlug:`green-bean`,say:`ah-ree-koh VAIR`,background:`Green beans are the young pods of the common bean, Phaseolus vulgaris, which was domesticated in the Americas at least twice, in Mesoamerica and in the Andes, from about 8,000 years ago. The bean crossed to Europe after Columbus; the first sure evidence there dates to the middle of the 1500s, and the first European picture of it appeared in the herbal of Leonhart Fuchs (1501 to 1566) in 1542. Where the French word haricot comes from is still argued: English dictionaries lean to the Nahuatl ayacotli, with the spelling shaped by an older French haricot, a stew of cut up meat, while French dictionaries derive the bean’s name from that stew itself. On a menu the name now means the slender filet type, and French sources list among the filet beans the fin de Bagnols and the triomphe de Farcy.`,metAt:`Brennan's Thanksgiving Day 2026: the Haricots Verts side`},{id:`vegetables-parsnips`,term:`Parsnip`,category:`vegetables`,aliases:[`Parsnips`],ref:`t:parsnip`,definition:`Pale roots related to carrots, with a sweet, earthy flavor. Cold growing conditions can increase sweetness, but frost is not a requirement for eating them.`,guest:`Parsnips bring a sweet, earthy root-vegetable flavor.`,kitchen:`Choose firm roots; scrub or peel and inspect a large root for a woody core. Roast, simmer or mash until tender.`,compare:`A parsnip is not a white carrot; it has its own more aromatic flavor.`,correction:``,sources:[{title:`University of Minnesota Extension`,url:`https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/growing-carrots-and-parsnips`}],reviewedOn:`2026-10-15`},{id:`vegetables-radicchio`,term:`Radicchio`,category:`vegetables`,aliases:[],ref:`t:radicchio`,definition:`A leafy chicory, often burgundy and white, valued for its bitterness. Varieties can form round or elongated heads.`,guest:`Radicchio gives a crisp, pleasantly bitter counterpoint.`,kitchen:`Dress raw leaves or grill wedges. Taste the batch and balance its bitterness with the rest of the dish.`,compare:`It can resemble red cabbage but belongs to the chicory group.`,correction:``,sources:[{title:`Royal Horticultural Society`,url:`https://www.rhs.org.uk/vegetables/chicory/grow-your-own?type=v`}],reviewedOn:`2026-10-15`},{id:`vegetables-ramps`,term:`Ramps`,category:`vegetables`,aliases:[],ref:`t:ramps`,definition:`A North American woodland allium with broad spring leaves and a strong onion-garlic aroma. Leaves and bulbs can be used in cooking.`,guest:`Ramps bring a seasonal onion-and-garlic flavor.`,kitchen:`Buy from a responsible, identified supplier. Leaves can season butter or sauces; bulbs and stems can be cooked or pickled.`,compare:`Ramps are not ordinary leeks or scallions. Their brief season and slow growth make sourcing important.`,correction:``,sources:[{title:`Penn State Extension`,url:`https://extension.psu.edu/ramps-allium-tricoccum`}],reviewedOn:`2026-10-15`},{id:`vegetables-rhubarb`,term:`Rhubarb`,category:`vegetables`,aliases:[],ref:`t:rhubarb`,definition:`A vegetable used for its tart leaf stalks, often in fruit-style dishes. Stalks may be green or red; the leaves are not eaten.`,guest:`Rhubarb adds a bright tartness, especially in a compote or dessert.`,kitchen:`Use the stalks only. Wash, trim and cook to the desired texture; balance sweetness to the actual recipe and batch.`,compare:`It looks like colored celery but is unrelated and tastes sharply tart.`,correction:``,sources:[{title:`University of Minnesota Extension`,url:`https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/growing-rhubarb`}],reviewedOn:`2026-10-15`},{id:`vegetables-salsify`,term:`Salsify`,category:`vegetables`,aliases:[],ref:`t:salsify`,definition:`A long pale root, sometimes called oyster plant for its delicate savory flavor. Black salsify is a related but different plant.`,guest:`Salsify is a tender root vegetable with a delicate, slightly oyster-like flavor.`,kitchen:`Scrub well; the skin can be removed after cooking or peeled beforehand as the recipe directs. Use steamed, sautéed or in soup.`,compare:`The nickname does not mean it contains oyster; check the full sauce and preparation separately.`,correction:``,sources:[{title:`Royal Horticultural Society`,url:`https://www.rhs.org.uk/vegetables/salsify/grow-your-own`}],reviewedOn:`2026-10-15`},{id:`vegetables-shallot`,term:`Shallot`,category:`vegetables`,aliases:[],ref:`t:shallot`,definition:`A type of onion, often smaller and milder than common bulb onions, used finely chopped in sauces and dressings or cooked whole.`,guest:`Shallot adds a gentle onion flavor to the sauce.`,kitchen:`Choose firm bulbs. Peel, cut evenly and cook a fine mince gently so it does not scorch.`,compare:`Shallots are a kind of onion; they are not garlic, despite some bulbs dividing into lobes.`,correction:``,sources:[{title:`Royal Horticultural Society`,url:`https://www.rhs.org.uk/vegetables/shallots/grow-your-own`}],reviewedOn:`2026-10-15`},{id:`vegetables-sugarsnappeas`,term:`Snap Pea`,category:`vegetables`,aliases:[`Sugar Snap Peas`],ref:`t:snap-pea`,definition:`Peas with plump, sweet, edible pods. Both the pod and the peas inside are eaten.`,guest:`Sugar snap peas give a sweet, crisp bite.`,kitchen:`Choose crisp pods, remove any tough strings and serve washed raw or cook briefly to the desired tenderness.`,compare:`Snow peas have flat pods and tiny peas; shelling peas are removed from a tougher pod.`,correction:``,sources:[{title:`University of Minnesota Extension`,url:`https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/growing-peas`}],reviewedOn:`2026-10-15`},{id:`vegetables-sunchokes`,term:`Sunchoke`,category:`vegetables`,aliases:[`Sunchokes`],ref:`t:sunchoke`,definition:`Also called Jerusalem artichokes: edible tubers of a North American sunflower. They have a nutty, gently sweet flavor.`,guest:`Sunchokes are sunflower tubers with a nutty flavor and a tender texture when cooked.`,kitchen:`Scrub the folds thoroughly. Thin skins may be left on; roast, simmer or purée as appropriate.`,compare:`They are not globe artichoke hearts. Do not promise a cooking technique eliminates digestive effects.`,correction:``,sources:[{title:`Royal Horticultural Society`,url:`https://www.rhs.org.uk/vegetables/jerusalem-artichokes/grow-your-own`}],reviewedOn:`2026-10-15`},{id:`vegetables-swisschard`,term:`Swiss Chard`,category:`vegetables`,aliases:[],ref:`t:swiss-chard`,definition:`A leafy vegetable related to beet, with broad leaves and edible stalks that may be white, red or yellow.`,guest:`Chard is a hearty green with a gently earthy flavor.`,kitchen:`Wash well. Cut stalks separately and give thicker pieces a head start before adding the leaves.`,compare:`It resembles spinach in use, but its thicker stalks usually need more cooking.`,correction:``,sources:[{title:`University of Illinois Extension`,url:`https://extension.illinois.edu/blogs/simply-nutritious-quick-and-delicious/2024-05-17-swiss-chard-bitter-better`}],reviewedOn:`2026-10-15`},{id:`vegetables-watercress`,term:`Watercress`,category:`vegetables`,aliases:[],ref:`t:watercress`,definition:`A small-leaved green with edible tender stems and a peppery flavor. Use cultivated food-grade supplies.`,guest:`Watercress brings a fresh, peppery lift.`,kitchen:`Choose fresh green leaves. Wash and dry; use in salad, sandwiches, soup or a quick sauté.`,compare:`It is not ornamental nasturtium, despite sharing part of a botanical name; do not use a short menu card as a foraging guide.`,correction:``,sources:[{title:`University of Illinois Extension`,url:`https://extension.illinois.edu/blogs/simply-nutritious-quick-and-delicious/2023-04-27-watercress-fresh-tasty-and-packed-vitamins`}],reviewedOn:`2026-10-15`},{id:`vegetables-sweetpotato`,term:`Sweet Potato`,category:`vegetables`,aliases:[`Sweet potatoes`,`Ipomoea batatas`,`Louisiana yam`],definition:`The sweet, starchy root of Ipomoea batatas, a vine of the morning glory family native to the tropical Americas. The orange fleshed kinds Louisiana grows are moist and sweet when cooked, where some older eastern kinds are drier and paler. In Louisiana they are sold as yams, though a true yam is a different plant altogether. On the Thanksgiving Day menu it filled the Sweet Potato Agnolotti and flavored the Sweet Potato Pot de Crème.`,guest:`Sweet potatoes are a Louisiana crop, and here people often call them yams, though botanically they are no yam at all. On Thanksgiving Day we used them twice: inside the agnolotti, with brown butter, candied pecans and goat cheese, and in a silky pot de crème, the holiday casserole turned into a custard.`,kitchen:`Where the house sweet potatoes came from, and what went into the agnolotti filling with them, was the kitchen’s to say; the sheet printed neither, so ask before calling them Louisiana grown.`,compare:`The true yam is its nearest neighbor in name only: a yam is a Dioscorea, of a different plant family altogether, while a sweet potato belongs to the morning glory family. An orange fleshed yam in a Louisiana market is a sweet potato.`,correction:``,sources:[{title:`LSU AgCenter: Sweet Potato, Louisiana’s Most Popular Vegetable`,url:`https://www.lsuagcenter.com/portals/communications/publications/agmag/archive/2012/spring/sweet-potato-louisianas-most-popular-vegetable`},{title:`LSU AgCenter: The Sky’s the Limit: Change in the Sweet Potato Industry`,url:`https://www.lsuagcenter.com/portals/communications/publications/agmag/archive/2009/spring/the-skys-the-limit-change-in-the-sweet-potato-industry`},{title:`LSU AgCenter: Sweet Potato Research Station profile`,url:`https://www.lsuagcenter.com/portals/our_offices/research_stations/sweetpotato/features/profile`},{title:`Wikipedia: Sweet potato`,url:`https://en.wikipedia.org/wiki/Sweet_potato`},{title:`PLOS ONE via PMC: Disentangling the Origins of Cultivated Sweet Potato`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC3664560/`},{title:`Smithsonian Magazine: How Marshmallow Topped Sweet Potato Casserole Became a Thanksgiving Classic`,url:`https://www.smithsonianmag.com/smart-news/happy-100-birthday-marshmallow-sweet-potato-180967245/`},{title:`Atlas Obscura: How Marshmallows Ended Up on Sweet Potato Casserole`,url:`https://atlasobscura.com/articles/marshmallows-sweet-potato-casserole-how-thanksgiving`},{title:`LSU AgCenter: Or you can call me Yam`,url:`https://www.lsuagcenter.com/portals/communications/publications/agmag/archive/2009/spring/or-you-can-call-me-yam`},{title:`Mental Floss: Why We Eat Sweet Potato Casserole With Marshmallows`,url:`https://www.mentalfloss.com/holidays/thanksgiving/why-we-eat-sweet-potato-casserole-with-marshmallows`}],reviewedOn:`2026-11-27`,say:`SWEET puh-TAY-toh`,background:`The sweet potato is native to the tropical Americas and was domesticated there, in Central or South America, thousands of years before Europeans arrived. Louisiana grows it as a field crop, and in the 1930s the state’s growers began selling their moist, orange fleshed roots as yams, to set them apart from the drier, paler sweet potatoes grown further east. The name stuck, though botanically a yam is another plant. Louisiana State University’s sweet potato breeding began in that decade, and in 1987 the LSU AgCenter released the Beauregard, an orange fleshed variety that went on to be grown far beyond the state. The Thanksgiving pairing with marshmallow is younger than the crop: the earliest known printed recipe for mashed sweet potatoes baked under marshmallows is in a 1917 booklet that the Angelus Marshmallow company commissioned to find new uses for its marshmallows.`,metAt:`Brennan's Thanksgiving Day 2026: Sweet Potato Agnolotti and Sweet Potato Pot de Crème`},{id:`vegetables-spinach`,term:`Spinach`,category:`vegetables`,aliases:[],definition:`A tender leafy green, eaten raw in salads or cooked. Heat collapses it fast: a heaped pan wilts to a few spoonfuls in a minute, so cooks squeeze it hard before it joins a cream or a gratin. Its flavor is mineral and faintly bitter, which is why butter, cream and garlic suit it.`,guest:`Our turtle soup carries brown butter spinach, spinach cooked with butter taken to a nutty brown, all through the bowl. On the Thanksgiving menu the Rockefeller Gratin baked creamed spinach with oysters and bacon under breadcrumbs.`,kitchen:`Wash it well, cook it in seconds and squeeze it dry, or it waters down the dish. Whether the creamed spinach carries stock or cheese is the kitchen's to say for a guest who asks.`,compare:`Swiss chard is used the same way, but its thick stalks need a head start; spinach's leaves and thin stems cook in the same moment.`,correction:``,sources:[{title:`Euphytica: Spinach (Spinacia oleracea L.), domestication and migration`,url:`https://link.springer.com/article/10.1007/s10681-020-02585-y`},{title:`National Geographic: Spinach, a vegetable in need of some love`,url:`https://www.nationalgeographic.com/culture/article/spinach-a-vegetable-in-need-of-some-love`},{title:`What's Cooking America: Oysters Rockefeller history`,url:`https://whatscookingamerica.net/seafood/oystersrockefeller.htm`},{title:`University of Wyoming Extension: Spinach in the Kitchen`,url:`https://uwyoextension.org/uwnutrition/newsletters/the-popeye-power-of-spinach/`},{title:`Wageningen University: spinach origin and spread`,url:`https://edepot.wur.nl/533038`},{title:`Wikipedia: Florentine (culinary term)`,url:`https://en.wikipedia.org/wiki/Florentine_(culinary_term)`},{title:`Wikipedia: Oysters Rockefeller`,url:`https://en.wikipedia.org/wiki/Oysters_Rockefeller`}],reviewedOn:`2026-11-27`,say:`SPIN-ich`,background:`Spinach is thought to have been domesticated in ancient Persia, and from there it traveled east to China by the seventh century and west toward Europe. The Moors brought it to Spain, where written record places it by the eleventh century, and from Spain it spread across the continent. French cooks call a dish set on a bed of spinach à la Florentine, a name tradition ties to Catherine de' Medici (1519 to 1589), the Florentine who became queen of France, though the story is legend rather than record. In New Orleans spinach is bound up with oysters: Antoine's, which dates Oysters Rockefeller to 1899, has long said its recipe holds no spinach, yet most cooks since have made it with spinach, as the Thanksgiving Rockefeller Gratin did with creamed spinach.`,metAt:`Brennan's Thanksgiving Day 2026: Classic Turtle Soup (brown butter spinach) and Rockefeller Gratin (creamed spinach)`},{id:`vegetables-meyerlemon`,term:`Meyer Lemon`,category:`vegetables`,aliases:[`Improved Meyer Lemon`],definition:`A lemon hybrid from China, rounder than a common lemon, with a thin, smooth skin that ripens deep yellow with an orange tint. Its juice is sweeter and less acidic than that of the Eureka and Lisbon lemons sold in most stores, and its peel is fragrant. The trees grown in the United States today are the Improved Meyer, a virus free selection released in 1975.`,guest:`A Meyer lemon is a sweeter, gentler lemon, thin skinned and deep yellow, brought to America from China in 1908. On Thanksgiving Day it brightened the raw scallops of the crudo without the sharp sourness of a common lemon, so their sweetness came through.`,kitchen:`Its juice and zest are milder than a common lemon's, so a dressing is tasted before more is added. Whether the crudo carries juice, zest or segments is a lineup question.`,compare:`The common Eureka or Lisbon lemon is sharper and more acidic, with a paler, thicker peel; the Meyer is sweeter, thin skinned and a deeper yellow, near orange when ripe.`,correction:``,sources:[{title:`UC Riverside Citrus Variety Collection: Improved Meyer lemon`,url:`https://citrusvariety.ucr.edu/crc3737`},{title:`UC Riverside College of Natural and Agricultural Sciences: How America's Beloved Meyer Lemon Caused a Mid-Century Citrus Panic`,url:`https://cnas.ucr.edu/media/2023/04/12/how-americas-beloved-meyer-lemon-caused-mid-century-citrus-panic`},{title:`Four Winds Growers: Improved Meyer Lemon`,url:`https://www.fourwindsgrowers.com/products/improved-meyer-lemon`},{title:`UF/IFAS Gardening Solutions: Meyer Lemon`,url:`https://gardeningsolutions.ifas.ufl.edu/home/plants/edible-plants/fruits/meyer-lemon`},{title:`USDA National Agricultural Library: Frank N. Meyer`,url:`https://www.nal.usda.gov/exhibits/speccoll/exhibits/show/frank-meyer`},{title:`Wikipedia: Meyer lemon`,url:`https://en.wikipedia.org/wiki/Meyer_lemon`},{title:`UC Riverside, International Organization of Citrus Virologists: Meyer lemon and the tristeza program`,url:`https://iocv.ucr.edu/media/1746/download`},{title:`FreshPlaza: Tender, juicy Meyer lemon growing in popularity`,url:`https://www.freshplaza.com/north-america/article/2091598/tender-juicy-meyer-lemon-growing-in-popularity/`}],reviewedOn:`2026-11-27`,say:`MY-er LEM-un`,background:`The Meyer lemon carries the name of Frank N. Meyer (1875 to 1918), a plant explorer for the United States Department of Agriculture who collected across China and Central Asia and sent home more than 2,500 introductions. In 1908 he brought this lemon from near Peking, today Beijing, and it was entered as plant introduction 23028. In the 1940s it was found to carry the tristeza virus without showing it, a danger to other citrus, so its planting was banned in some citrus areas and many trees were pulled out. In 1967 a University of California text judged it acceptable as a lemon for home use but not satisfactory as a commercial variety for the fresh fruit trade. A virus free selection found at a California nursery in the 1950s was certified and released by the University of California in 1975 as the Improved Meyer lemon, the tree sold ever since.`,metAt:`Brennan's Thanksgiving Day 2026: Bay Scallop Crudo`},{id:`vegetables-radish`,term:`Radish`,category:`vegetables`,aliases:[`Radishes`],definition:`The crisp, juicy root of Raphanus sativus, a member of the mustard family, eaten raw for its crunch and its peppery bite. The small red globe is the familiar kind; others grow long and white, as daikon does. The heat is not in the whole root: it forms when the radish is cut or chewed, and it fades as grated radish stands.`,guest:`Radish adds crunch and a gentle peppery bite. On the Thanksgiving Day crudo it was lovely against the soft, sweet scallop and the citrus, served raw so it stayed crisp and cool.`,kitchen:`Cut it close to service: grated radish begins to lose its heat within the hour. How it is cut on the crudo, and which radish it is, are lineup questions.`,compare:`Horseradish shares the name and the mustard oil heat, but it is a different plant, a far stronger root grated as a condiment; a radish is mild enough to eat whole.`,correction:``,sources:[{title:`EBSCO Research Starters: Radish`,url:`https://www.ebsco.com/research-starters/agriculture-and-agribusiness/radish`},{title:`CGIAR Crop Genebank Knowledge Base: Radish`,url:`https://cropgenebank.sgrp.cgiar.org/index.php/radish-mainmenu-812`},{title:`Smithsonian Magazine: Why Radish Carving Has Become a Popular Holiday Event in Oaxaca`,url:`https://www.smithsonianmag.com/travel/why-radish-carving-has-become-popular-holiday-event-oaxaca-180971096/`},{title:`NPR The Salt: Survived The Mayan Apocalypse? Here Come The Radish People (2012)`,url:`https://www.npr.org/blogs/thesalt/2012/12/22/167709706/survived-the-mayan-apocalypse-here-come-the-radish-people`},{title:`JIRCAS, Japan Agricultural Research Quarterly: pungency of radish`,url:`https://www.jircas.go.jp/sites/default/files/publication/jarq/24-4-273-279_0.pdf`},{title:`Wikipedia: Glucosinolate`,url:`https://en.wikipedia.org/wiki/Glucosinolate`},{title:`Pliny the Elder, Natural History, Book XIX, chapter 26: Radishes`,url:`https://peterburk.github.io/pliny/ChaptersHtml/19.%20Book%20XIX.%20The%20Nature%20And%20Cultivation%20Of%20Flax,%20And%20An%20Account%20Of%20Various%20Garden%20Plants./26.%20Chap.%2026.-Radishes..html`},{title:`Museum of Fine Arts, Boston, CAMEO: Radish oil`,url:`https://cameo.mfa.org/wiki/Radish_oil`},{title:`Wikipedia: Night of the Radishes`,url:`https://en.wikipedia.org/wiki/Night_of_the_Radishes`},{title:`Journal of Home Economics of Japan (1982): isothiocyanates in grated radish`,url:`https://www.jstage.jst.go.jp/article/jhej1951/33/10/33_10_513/_article/-char/en`}],reviewedOn:`2026-11-27`,say:`RAD-ish`,background:`Where the radish was first grown is not settled: some botanists place it in the eastern Mediterranean, others in China or Southeast Asia, and it may have been domesticated more than once. Pliny the Elder (about 23 to 79) wrote that Egypt prized it for the oil pressed from its seed. Spanish missionaries brought radishes to Oaxaca in the sixteenth century, and there they became part of Christmas: since 1897 the city has held the Night of the Radishes on December 23, when growers carve outsized radishes into figures and scenes that last only a few hours before they wilt. Its bite is chemistry. A radish keeps glucosinolates and the enzyme myrosinase apart in its cells, and cutting or chewing lets them meet and form pungent isothiocyanates, the same family of compounds that gives mustard its heat.`,metAt:`Brennan's Thanksgiving Day 2026: Bay Scallop Crudo`},{id:`vegetables-satsuma`,term:`Satsuma`,category:`vegetables`,aliases:[`Satsuma mandarin`,`Citrus unshiu`],definition:`A loose skinned mandarin, Citrus unshiu, sweet, mild and usually seedless, whose peel slips off by hand and whose segments part cleanly. It is one of the most cold hardy citrus a Gulf Coast grower can plant, which is why it suits south Louisiana, where it is the leading citrus crop. The fruit ripens in the fall, from late September into early December depending on the variety, and Owari is the variety most widely grown.`,guest:`A satsuma is a sweet, easy peeling mandarin, and it is the citrus of a south Louisiana fall: the fruit comes in just as the weather turns. On Thanksgiving Day its bright, gentle sweetness was set against the crisp, gently bitter endive and a cherry vinaigrette.`,kitchen:`The peel comes away by hand and the segments separate without a knife, so the fruit can be segmented close to service and stay juicy. How the salad's satsuma is cut, and whether it is Louisiana grown, are lineup questions.`,compare:`The navel orange, Louisiana's other citrus of the season, is its nearest neighbor: a navel is larger, with a tight, thick peel that wants a knife or a firm thumb, while a satsuma is smaller and its loose skin slips off in the hand.`,correction:``,sources:[{title:`UF/IFAS Extension: The Satsuma Mandarin (CH116)`,url:`https://ask.ifas.ufl.edu/publication/ch116`},{title:`Florida Memory: the Satsuma, introduced by George R. Hall in 1876 and again in 1878`,url:`https://floridamemory.com/items/show/181524?id=8`},{title:`LSU AgCenter: It's satsuma time in Louisiana`,url:`https://www.lsuagcenter.com/profiles/rbogren/articles/page1572623571287`},{title:`LSU AgCenter: Fragrant fall citrus`,url:`https://www.lsuagcenter.com/articles/page1699555253008`},{title:`LSU Digital Commons: Louisiana citrus study, satsumas and citrus acreage`,url:`https://repository.lsu.edu/plantcrop_pubs/389`},{title:`64 Parishes: Citrus Industry`,url:`https://64parishes.org/entry/citrus-industry`},{title:`WWNO: Satsumas`,url:`https://www.wwno.org/food/2009-10-03/satsumas`}],reviewedOn:`2026-11-27`,say:`sat-SOO-muh`,background:`The satsuma, Citrus unshiu, may have come from China, but it was first reported in Japan more than 700 years ago. The first recorded introduction to the United States was in Florida in 1876. Its English name is credited to the wife of an American minister to Japan, who sent trees home in 1878 from Satsuma, a former province that is now Kagoshima Prefecture. Between 1908 and 1911 about a million Owari satsuma trees were imported from Japan and planted along the lower Gulf Coast, from northern Florida to Texas, and they built a mandarin industry across the region. In Louisiana the satsuma, hardier in a freeze than most citrus, came to dominate the state's citrus plantings, and southern Plaquemines Parish, below New Orleans, is the center of the crop.`,metAt:`Brennan's Thanksgiving Day 2026: Endive Satsuma Salad`},{id:`vegetables-sunflowerseeds`,term:`Sunflower Seeds`,category:`vegetables`,aliases:[`Sunflower kernels`,`Roasted sunflower seeds`],definition:`The seeds of the common sunflower, Helianthus annuus, a plant native to North America. Seed grown to be eaten, called confection seed, is larger and striped, with a thick hull and less oil than the seed grown for pressing. For cooking the hull is cracked away and the kernel used, raw or roasted. Roasting turns the kernel golden and gives it a nutty, toasty flavor and a soft crunch.`,guest:`Roasted sunflower seeds are the shelled kernels, toasted until golden. On Thanksgiving Day they brought a nutty, savory crunch to the salad, against the crisp endive and the juicy satsuma.`,kitchen:`Kernels are toasted dry, in the oven or a pan, until golden and fragrant, then cooled before they go on so they stay crisp. Whether they are salted or seasoned is the kitchen's to say, and every seed question goes to the kitchen.`,compare:`Pumpkin seeds, or pepitas, are the nearest neighbor on a salad: flat, oval and green, larger and softer to the bite, where a sunflower kernel is small and slim and roasts from gray to golden.`,correction:``,sources:[{title:`Nature (2004): the domestication of the sunflower in eastern North America`,url:`https://www.nature.com/articles/nature02710.pdf`},{title:`PubMed Central: genetic evidence for a single domestication of cultivated sunflower`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC3161615`},{title:`Iowa State University Extension: Sunflowers, from Native American staple to modern garden favorite`,url:`https://yardandgarden.extension.iastate.edu/how-to/sunflowers-native-american-staple-modern-garden-favorite`},{title:`NPR, The Salt: How the Russians saved America's sunflower (2012)`,url:`https://www.npr.org/blogs/thesalt/2012/01/05/144695733/how-the-russians-saved-americas-sunflower`},{title:`The Conversation: Making sunlight liquid, a brief history of sunflowers`,url:`https://theconversation.com/making-sunlight-liquid-a-brief-history-of-sunflowers-99418`},{title:`Popular Science: How the sunflower transformed from a garden novelty to a mighty beast`,url:`https://www.popsci.com/sunflowers-brief-history/`},{title:`KU Center for Indigenous Health: Foods indigenous to the Western Hemisphere, Sunflowers`,url:`https://aihd.ku.edu/foods/sunflowers.html`}],reviewedOn:`2026-11-27`,say:`SUN-flou-er seedz`,background:`The common sunflower is one of the few crops first domesticated in what is now the United States. Genetic studies point to a single domestication in eastern North America, by its native peoples, long before Europeans arrived. Seed sent to Europe was grown mostly as a curiosity and a garden flower, and it was Russia that made the sunflower a field crop. Sunflower oil was not on the list of oily foods the Russian Orthodox Church restricted in Lent, which helped it spread, and by the nineteenth century it was grown across the Russian plains. Russian immigrants are thought to have carried its seed back to North America, and by the 1880s seed companies in the United States were offering a variety sold as Mammoth Russian.`,metAt:`Brennan's Thanksgiving Day 2026: Endive Satsuma Salad`},{id:`vegetables-cranberry`,term:`Cranberry`,category:`vegetables`,aliases:[`Cranberries`,`Cranberry sauce`],definition:`The tart red berry of the American cranberry, Vaccinium macrocarpon, a plant of the bogs and wetlands of North America. Each berry holds small pockets of air, so it floats, and growers gather most of the crop by flooding the beds, knocking the berries loose and skimming them from the surface. Raw the fruit is sharply sour; cooked with sugar it becomes the bright sauce of the holiday table. On the Thanksgiving Day menu it came as a side of cranberry sauce and in the turkey’s jus.`,guest:`Cranberries are native to North America, gathered here by Native peoples long before the colonists came, and they are harvested in the fall, just in time for Thanksgiving. Cranberry sauce brings a tart, bright note against the richness of the turkey, and on Thanksgiving Day it came both as a side for the table and in the turkey’s own jus.`,kitchen:`Cranberries are cooked with sugar until the berries burst and soften into a sauce. The house recipe, and whether the sauce was left whole or made smooth, was a question for lineup.`,compare:`A cranberry relish is the nearest neighbor: a relish is usually ground raw with sugar, so it stays coarse and sharp, while a sauce is cooked until the berries burst and turn soft and glossy.`,correction:``,sources:[{title:`Cape Cod Cranberry Growers’ Association: History of Cranberries`,url:`https://cranberries.org/history`},{title:`Cape Cod Cranberry Growers’ Association: How Cranberries Grow: Fall`,url:`https://www.cranberries.org/fall`},{title:`University of Kansas, Foods Indigenous to the Western Hemisphere: Cranberry`,url:`https://aihd.ku.edu/foods/cranberry.html`},{title:`National Geographic: Cranberries were a Native American superfood`,url:`https://www.nationalgeographic.com/science/article/131127-cranberries-thanksgiving-native-americans-indians-food-history`},{title:`McGill Office for Science and Society: Cranberries, a superfood?`,url:`https://mcgill.ca/oss/article/did-you-know-history/cranberries-superfood`},{title:`Colonial Williamsburg Journal: Cranberries`,url:`https://podcasts.history.org/Foundation/journal/Holiday06/cran.cfm`},{title:`Wikipedia: Cranberry`,url:`https://en.wikipedia.org/wiki/Cranberry`},{title:`Smithsonian Magazine: A Brief History of Cranberries`,url:`https://www.smithsonianmag.com/smart-news/brief-history-cranberries-180957399/`},{title:`Smithsonian Magazine: This Man Made the First Canned Cranberry Sauce`,url:`https://www.smithsonianmag.com/arts-culture/this-man-made-the-first-canned-cranberry-sauce-180947862/`},{title:`Wikipedia: Marcus Urann`,url:`https://en.wikipedia.org/wiki/Marcus_Urann`},{title:`NPR: When turkey met cranberries, a dinner date from the 1700s`,url:`https://www.npr.org/2022/11/18/1135751773/susan-stamberg-cranberry-relish-thanksgiving`},{title:`American Heritage: The first American cookbook`,url:`https://americanheritage.com/node/54335`},{title:`Wisconsin Extension: Cranberries early childhood activity guide`,url:`https://health.extension.wisc.edu/hotm/cranberries-early-childhood-activity-guide`},{title:`Wikipedia: Ocean Spray (cooperative)`,url:`https://en.wikipedia.org/wiki/Ocean_Spray_(cooperative)`},{title:`Bangor Daily News: Canned cranberry sauce invented by Mainer`,url:`https://www.bangordailynews.com/2025/12/22/state/state-culture/canned-cranberry-sauce-invented-by-mainer/`}],reviewedOn:`2026-11-27`,say:`KRAN-ber-ee`,background:`Native peoples gathered the cranberry long before Europeans arrived: pounded with dried deer meat and fat into pemmican, it made a food that kept for months on long journeys, and the berries also served as a dye. The English name is usually traced to craneberry, for the likeness of the flower to the head and bill of a crane. Cultivation began in Dennis, Massachusetts, in 1816 by most accounts, when a grower saw that his wild vines grew better where sand blew over them. American Cookery, printed in 1796 and held to be the first cookbook written by an American, already recommended cranberry sauce with roast turkey, though it gave no recipe. In 1912 a Massachusetts grower began canning cranberry sauce to stretch the short selling season, and in 1930 he and two other growers formed the cooperative that became Ocean Spray.`,metAt:`Brennan's Thanksgiving Day 2026: Cranberry Sauce, and the cranberry and rosemary jus of the Roasted Buttermilk-Brined Turkey Breast`},{id:`vegetables-mustardgreens`,term:`Mustard Greens`,category:`vegetables`,aliases:[`Southern mustard`,`Curled mustard`],definition:`The leaves of the brown mustard plant, Brassica juncea. Raw they have a sharp, peppery bite; cooking mellows them and brings out a little sweetness. The curly-leaved kind, sold as Southern or curled mustard, is cooked across the South much as collards are, often slowly with smoked meat, and the cooking liquid is the potlikker. On the Thanksgiving Day menu they came with the bacon-wrapped pork tenderloin.`,guest:`Mustard greens are the leaves of the mustard plant, a Southern green with a peppery bite that softens as they cook. On Thanksgiving Day they came with the bacon-wrapped pork tenderloin, a little bitter and peppery against the sweet cane syrup glaze.`,kitchen:`Wash the leaves well, since they hold grit, and strip out the tough stems. How ours were cooked, and with what, was a question for lineup, and it matters before calling them vegetarian.`,compare:`Collard greens are the nearest neighbor and are cooked the same Southern way, but collards are broad, flat, sturdy leaves with a mild cabbage taste, while mustard greens are thinner, often frilled, and peppery.`,correction:``,sources:[{title:`UF/IFAS Extension: Mustard Greens in the Florida Vegetable Garden`,url:`https://edis.ifas.ufl.edu/publication/HS1402`},{title:`University of Arkansas Cooperative Extension: Home Gardening Series, Mustard Greens`,url:`https://www.uaex.uada.edu/publications/PDF/FSA-6072.pdf`},{title:`Santa Fe College, Florida's Heritage Foods: Mustard`,url:`https://sfcollege.edu/floridaheritagefoods/biblical-collection/mustard.html`},{title:`NC State Extension Gardener Plant Toolbox: Brassica juncea`,url:`https://plants.ces.ncsu.edu/plants/brassica-juncea`},{title:`64 Parishes: Gumbo`,url:`https://64parishes.org/entry/gumbo`},{title:`64 Parishes: Spring Tonic`,url:`https://64parishes.org/spring-tonic`},{title:`Atlas Obscura: Gumbo z'herbes`,url:`https://atlasobscura.com/foods/gumbo-zherbes-lent-louisiana`},{title:`Britannica: brown mustard`,url:`https://www.britannica.com/plant/brown-mustard`},{title:`Nature Genetics (2021): the origin and domestication of Brassica juncea`,url:`https://link.springer.com/10.1038/s41588-021-00922-y`},{title:`Christian Science Monitor: Gumbo Z'Herbes`,url:`https://m.csmonitor.com/The-Culture/Food/Stir-It-Up/2016/0101/Gumbo-Z-Herbes`}],reviewedOn:`2026-11-27`,say:`MUS-terd GREENZ`,background:`Brown mustard is a plant of Asia, long grown from the Himalaya to China both as a leaf vegetable and for its seed. Where it first arose is still argued: extension botanists point to Central Asia, with later spread to India and China, while a 2021 genetic study points to West Asia. In the American South it became a staple cooking green, prepared much as collards are. In Louisiana they are among the greens of gumbo z'herbes, the green gumbo of Lent, also called gumbo maigre, which Creole cooks make with an odd number of greens, often seven, nine or eleven; the old saying holds that each green brings a new friend in the year ahead.`,metAt:`Brennan's Thanksgiving Day 2026: Bacon-Wrapped Pork Tenderloin`},{id:`vegetables-pommespuree`,term:`Pommes Purée`,category:`vegetables`,aliases:[`Purée de pommes de terre`,`French mashed potatoes`,`Potato purée`],definition:`The French potato purée, smoother, denser and richer than an everyday American mash. The cooked potatoes are pressed through a ricer or food mill, or in the old way through a fine drum sieve called a tamis, and butter, with milk or cream, is worked in gradually until the purée turns silky and glossy. Pressing rather than beating matters, because overworked potato turns gluey. On the Thanksgiving Day menu it came under the herb roasted beef tenderloin, and an herbed potato purée was offered as a side for the table.`,guest:`Pommes purée, said pom pyoo-RAY, is the French way with mashed potatoes: pressed through a fine sieve and worked with butter until silky and smooth rather than fluffy. On Thanksgiving Day it came under the beef tenderloin, and our herbed potato purée was there as a side for the whole table.`,kitchen:`The potatoes are cooked until fully tender, riced or sieved while hot, and enriched with butter and warm milk or cream, stirred rather than whipped. Which potatoes and how much butter the kitchen used, and how the herbed side differed from the purée under the beef, was a question for lineup.`,compare:`Mashed potatoes are the nearest neighbor: a mash is crushed with a masher and stays fluffy and a little rough, while pommes purée is pressed through a ricer or sieve and enriched until it is smooth, dense and glossy.`,correction:``,sources:[{title:`America's Test Kitchen: French-Style Mashed Potatoes (Pommes Purée)`,url:`https://www.americastestkitchen.com/recipes/9246-french-style-mashed-potatoes-pommes-puree`},{title:`America's Test Kitchen: Luxurious French Mashed Potatoes`,url:`https://www.americastestkitchen.com/articles/6448-luxurious-french-mashed-potatoes`},{title:`MICHELIN Guide: My Signature Dish: Joël Robuchon's Purée de Pomme`,url:`https://guide.michelin.com/mo/en/article/people/my-signature-dish-joel-robuchon-s-puree-de-pomme`},{title:`Fine Dining Lovers: Joël Robuchon made the mashed potatoes, here is the recipe`,url:`https://www.finedininglovers.com/article/joel-robuchon-made-worlds-best-mashed-potatoes-heres-recipe`},{title:`NPR: Joël Robuchon, A Giant In French Cooking, Dies`,url:`https://www.npr.org/2018/08/06/635950485/jo-l-robuchon-a-giant-in-french-cooking-dies`},{title:`National Geographic: How the potato went from banned to beloved`,url:`https://www.nationalgeographic.com/history/article/potato-history-france-western-europe`},{title:`Wikipedia: Antoine Augustin Parmentier`,url:`https://en.wikipedia.org/wiki/Antoine-Augustin_Parmentier`},{title:`Connexion France: France banned potatoes due to health concerns`,url:`https://www.connexionfrance.com/article/Mag/French-Facts/France-banned-potatoes-due-to-health-concerns`},{title:`Wine Spectator: Joël Robuchon, Legendary French Chef, Dies at 73`,url:`https://www.winespectator.com/webfeature/show/id/Legendary-French-Chef-Joel-Robuchon-Dies-at-73`}],reviewedOn:`2026-11-27`,say:`pom pyoo-RAY`,background:`Potatoes came late to French tables. The Paris Faculty of Medicine declared them fit to eat in 1772, helped by the campaign of the pharmacist and agronomist Antoine Augustin Parmentier (1737 to 1813), who promoted them with dinners of potato dishes and is said to have given potato flowers to the king and queen to wear. French menus still honor him: a dish named Parmentier, such as hachis Parmentier, is made with potato. The purée's modern fame owes much to Joël Robuchon (1945 to 2018), who opened his Paris restaurant Jamin in 1981 and made a purée of potatoes, butter, milk and salt his signature dish; it went on to be served at his restaurants around the world.`,metAt:`Brennan's Thanksgiving Day 2026: Herb Roasted Beef Tenderloin, and the Herbed Potato Purée side`},{id:`vegetables-creoletomato`,term:`Creole Tomato`,category:`vegetables`,aliases:[],definition:`A tomato grown in southeast Louisiana, traditionally in the rich alluvial soil of the river parishes below New Orleans, and left to ripen on the vine before it is picked. The name is a regional marketing term, not a variety: farmers in St. Bernard and Plaquemines Parishes first sold their tomatoes as Creole, and today the name is used for almost any red, medium to large tomato grown in Louisiana. It is a summer crop, so in late fall what goes into a dish that carries the name is the kitchen’s to say.`,guest:`A Creole tomato is a Louisiana grown tomato, a name that began on the farms in the river soil just below New Orleans, where they are left to ripen on the vine. The name speaks to where it was grown, not to one variety. On our Thanksgiving menu the shrimp sauce piquante came in a Creole tomato gravy.`,kitchen:`In summer the kitchen can buy them local and vine ripe; out of season, ask the chef what tomatoes went into a dish that carries the Creole name before telling a guest they were local.`,compare:`The LSU Creole, a heat tolerant variety the university bred for Louisiana gardens, is its nearest namesake: that is one named cultivar, while a Creole tomato at the market is any Louisiana grown tomato sold under the regional name. Ask where it was grown, not what variety it is.`,correction:``,sources:[{title:`LSU AgCenter: Will the Real Creole Tomato Please Stand Up?`,url:`https://www.lsuagcenter.com/profiles/lbenedict/articles/page1469026887857`},{title:`LSU AgCenter: Creole (L134)`,url:`https://www.lsuagcenter.com/profiles/lblack/articles/page1734968050087`},{title:`64 Parishes: That’s a Mighty Fine Tomato`,url:`https://64parishes.org/thats-a-mighty-fine-tomato`},{title:`Herald Guide: What Sets the Creole Tomato Above the Rest?`,url:`https://www.heraldguide.com/lifestyles/what-sets-the-creole-tomato-above-the-rest/`},{title:`LSU AgCenter: Recovered LSU Varieties, Tomatoes`,url:`https://www.lsuagcenter.com/portals/our_offices/research_stations/northeast%20research%20station/features/seed-preservation-program/recovered-lsu-varieties/tomatoes`}],reviewedOn:`2026-11-27`,say:`KREE-ohl tuh-MAY-toh`,background:`Creole began as a name farmers gave their crop, not a seed they planted. Growers in St. Bernard and Plaquemines Parishes, on the alluvial land along the Mississippi below New Orleans, sold their vine ripened tomatoes as Creole while growing several varieties under the name. The state left the word unregulated, so it came to cover almost any red, medium to large tomato grown in the state. Around 1970 the LSU tomato breeding program released a heat tolerant variety of its own and named it Creole, with medium, deep red fruit; the river parish growers never took it up, and the university did not keep up its seed stock. A university trial in 2015 found its yields poor. The market name and the variety are two different things, and the name is about place.`,metAt:`Brennan's Thanksgiving Day 2026: the Creole tomato gravy of the Shrimp Sauce Piquante`},{id:`vegetables-leek`,term:`Leek`,category:`vegetables`,aliases:[`Leeks`,`Poireau`,`Allium ampeloprasum`],definition:`A member of the onion family, Allium ampeloprasum, grown for its long white shank rather than a bulb. Growers hill soil around the stalk as it grows to keep it pale, and since leeks grow in sandy soil, grit tends to hide between the layers. The white and light green parts are the tender ones, with a taste like a mild, sweet onion that cooking softens further. On the Thanksgiving Day menu leeks were crushed with potato in the écrasé under the Redfish Meunière.`,guest:`A leek is a gentle cousin of the onion, long and white with a mild, sweet flavor that turns soft and silky when cooked. Potato and leek are an old French pairing, the pair behind leek and potato soup. On Thanksgiving Day they were crushed together under the redfish meunière.`,kitchen:`Leeks are trimmed of roots and coarse dark tops, which can go to stock, then split lengthwise and rinsed with the layers fanned, or sliced and soaked so the grit sinks. How the house cooked the leeks for the écrasé was a question for lineup.`,compare:`The onion is its nearest neighbor: an onion swells into a bulb with a sharper bite, while a leek grows a long blanched shank and tastes milder and sweeter. The long white stalk is the tell.`,correction:``,sources:[{title:`Britannica: Leek`,url:`https://www.britannica.com/plant/leek`},{title:`Wikipedia: Leek`,url:`https://en.wikipedia.org/wiki/Leek`},{title:`Washington State Magazine: All about the leeks`,url:`https://magazine.wsu.edu/web-extra/all-about-the-leeks/`},{title:`Chelsea Green: The Search for A Welsh Leek`,url:`https://www.chelseagreen.com/?p=1652376`},{title:`University of Wisconsin Extension: Leeks`,url:`https://hort.extension.wisc.edu/articles/leeks/`},{title:`Ohio State University: Leeks`,url:`https://mesc.osu.edu/leeks`},{title:`Nebraska Extension: Leeks, The Gourmet’s Onion`,url:`https://lancaster.unl.edu/leeks-gourmets-onion/`},{title:`Food Network: How to Clean Leeks`,url:`https://www.foodnetwork.com/how-to/articles/how-to-clean-leeks-a-step-by-step-guide`},{title:`America's Test Kitchen: Squeaky Clean Leeks`,url:`https://www.americastestkitchen.com/how_tos/9898-squeaky-clean-leeks`},{title:`Wikipedia: Vichyssoise`,url:`https://en.wikipedia.org/wiki/Vichyssoise`},{title:`Wikipedia: Louis Diat`,url:`https://en.wikipedia.org/wiki/Louis_Diat`},{title:`Saveur: Cool Potato`,url:`https://www.saveur.com/article/Kitchen/Cool-Potato`},{title:`Pliny the Elder, Natural History, Book XIX, chapter 33: The Leek (Bostock and Riley translation)`,url:`https://peterburk.github.io/pliny/ChaptersHtml/19. Book XIX. The Nature And Cultivation Of Flax, And An Account Of Various Garden Plants./33. Chap. 33.-The Leek..html`},{title:`Mashed: This Roman Emperor Loved Leeks For An Unexpected Reason`,url:`https://www.mashed.com/735777/this-roman-emperor-loved-leeks-for-an-unexpected-reason`},{title:`Amgueddfa Cymru, Museum Wales: National emblems (FAQ)`,url:`https://museum.wales/articles/1182/National-emblems-FAQ`},{title:`Historic UK: The Leek, National Emblem of the Welsh`,url:`https://www.historic-uk.com/HistoryUK/HistoryofWales/The-Leek-National-emblem-of-the-Welsh/`},{title:`New World Encyclopedia: Leek`,url:`https://www.newworldencyclopedia.org/entry/Leek`}],reviewedOn:`2026-11-27`,say:`LEEK`,background:`Leeks are an old food. Dried remains, carvings and wall drawings show them in the Egyptian diet from at least the second millennium BC. Rome prized them: Pliny the Elder, who died in 79, wrote that the emperor Nero (37 to 68) ate leeks with oil on set days each month for the sake of his voice. The leek is a national emblem of Wales, beside the daffodil, and was traditionally worn on Saint David’s Day; the story of Welsh soldiers wearing leeks into battle is told in several versions, none of them settled. In France leek and potato soup, potage Parmentier, is a staple of the home kitchen, and Louis Diat (1885 to 1957), the French born head chef of the Ritz Carlton in New York, is credited with serving it chilled with cream as vichyssoise, usually dated to 1917.`,metAt:`Brennan's Thanksgiving Day 2026: the potato and leek écrasé under the Redfish Meunière`},{id:`southern-blackeyedpeas`,term:`Black-eyed Pea`,category:`southern`,aliases:[`Black Eyed Peas`],ref:`t:black-eyed-pea`,definition:`A type of cowpea, usually cream-colored with a dark eye at the seed scar. They are legumes used fresh or dried in Southern cooking.`,guest:`Black-eyed peas have a mild, earthy flavor and become tender and creamy when cooked.`,kitchen:`Check whether fresh, dried or canned, then follow the recipe and cook until tender. Fixed cooking times do not fit every batch.`,compare:`They are not green garden peas. They can be used in Hoppin’ John, but not every Hoppin’ John uses black-eyed peas.`,correction:``,sources:[{title:`secure.caes.uga.edu`,url:`https://secure.caes.uga.edu/extension/publications/files/pdf/C%20485_2.PDF`},{title:`ansonmills.com`,url:`https://ansonmills.com/recipes/454`}],reviewedOn:`2026-10-15`},{id:`southern-chickenfried`,term:`Chicken-Fried`,category:`southern`,aliases:[],ref:`c:fd_0002`,definition:`A coating-and-frying style named after fried chicken. The item being fried may be beef or another food; the term alone does not identify the protein.`,guest:`Chicken-fried describes the crisp, seasoned coating and frying style; it does not mean the dish must contain chicken.`,kitchen:`Identify the protein, coating and gravy separately. Flour, egg, milk and the frying arrangement depend on the recipe.`,compare:`Chicken-fried names a coating and cooking style; the dish can contain beef or another ingredient instead of chicken.`,correction:``,sources:[{title:`Beef. It’s What’s for Dinner.`,url:`https://www.beefitswhatsfordinner.com/recipes/recipe/55863/classic-country-fried-steaks-gravy`}],reviewedOn:`2026-10-15`},{id:`southern-chowchow`,term:`Chow-Chow`,category:`southern`,aliases:[],definition:`A chopped, pickled vegetable relish. Recipes vary: cabbage, green tomatoes, onion and peppers may appear, with a sweet, tangy or spicy balance.`,guest:`Chow-chow is a tangy, crunchy vegetable relish that brightens rich food.`,kitchen:`Use a small amount with beans, greens, pork or sandwiches. Check the actual vegetables and heat level; a house version need not match a bottled one.`,compare:`Unlike coleslaw, chow-chow is a pickled relish used as a condiment. Do not assign one universal recipe or a single unverified origin story.`,correction:``,sources:[{title:`store.lovelesscafe.com`,url:`https://store.lovelesscafe.com/products/mild-chow-chow`}],reviewedOn:`2026-10-15`},{id:`southern-coleslaw`,term:`Coleslaw`,category:`southern`,aliases:[],ref:`c:fd_0004`,definition:`A salad of shredded cabbage, sometimes with other vegetables, dressed in a creamy or vinegar-based dressing.`,guest:`Coleslaw is a crunchy shredded-cabbage salad that brings a fresh contrast to richer food.`,kitchen:`Name the actual dressing. A creamy version may contain egg or dairy; a vinegar appearance is not an allergy guarantee.`,compare:`Coleslaw is usually served as a salad or side; chow-chow is a pickled relish.`,correction:``,sources:[{title:`University of Illinois Extension`,url:`https://extension.illinois.edu/diabetes/recipes/coleslaw`},{title:`University of Illinois Extension`,url:`https://extension.illinois.edu/sites/default/files/blogs_print_recipe_template_1.pdf`},{title:`store.lovelesscafe.com`,url:`https://store.lovelesscafe.com/products/mild-chow-chow`}],reviewedOn:`2026-10-15`},{id:`southern-hash`,term:`Hash`,category:`southern`,aliases:[],ref:`c:fd_0005`,definition:`A dish of chopped ingredients cooked together. Breakfast hash often includes meat, potato and onion; South Carolina barbecue hash can instead be a thick meat stew served with rice.`,guest:`Hash is a dish of chopped ingredients cooked together; our version brings the ingredients into one savory dish.`,kitchen:`Confirm whether the menu means crisp breakfast hash or the regional barbecue dish. South Carolina recipes may use pork, beef or organ meats.`,compare:`Breakfast hash is often pan-crisped; South Carolina barbecue hash is commonly a thick meat stew served over rice.`,correction:``,sources:[{title:`southernfoodways.org`,url:`https://www.southernfoodways.org/wp-content/uploads/SouthCarolinaBBQ__Midway.pdf`},{title:`southernfoodways.org`,url:`https://www.southernfoodways.org/wp-content/uploads/SouthCarolinaBBQ_Browns.pdf`}],reviewedOn:`2026-10-15`},{id:`southern-hoecakesjohnnycakes`,term:`Hoe cakes/Johnny cakes`,category:`southern`,aliases:[],definition:`Regional names for cornmeal cakes, often cooked on a griddle. Recipes and naming differ; some include wheat flour, egg, milk or leavening.`,guest:`These are cornmeal griddle cakes, with a toasted corn flavor.`,kitchen:`Confirm this recipe before describing sweetness or dietary suitability. Cook evenly and serve as a bread accompaniment or with a topping.`,compare:`They are not automatically gluten-free and are not necessarily identical in every region. The story that all hoecakes were baked on farm hoes should not be stated as fact.`,correction:``,sources:[{title:`George Washington’s Mount Vernon`,url:`https://www.mountvernon.org/inn/recipes/article/hoecakes/`},{title:`magazine.mountvernon.org`,url:`https://magazine.mountvernon.org/2021/Winter/kitchen-confidential.html`}],reviewedOn:`2026-10-15`},{id:`southern-hominy`,term:`Hominy`,category:`southern`,aliases:[],ref:`c:fd_0007`,definition:`Dried corn treated with an alkaline solution and then washed, producing softened kernels with a distinctive corn flavor.`,guest:`Hominy is corn prepared into plump, tender kernels with a pleasantly chewy bite.`,kitchen:`Distinguish dried hominy from ready-cooked canned hominy. Follow the product’s cooking instructions; the dish’s stock and toppings determine its complete ingredients.`,compare:`Hominy names the kernels. Hominy grits are ground; not all grits are made from hominy.`,correction:``,sources:[{title:`ansonmills.com`,url:`https://ansonmills.com/recipes/466`},{title:`ansonmills.com`,url:`https://ansonmills.com/grain_notes/13`}],reviewedOn:`2026-10-15`},{id:`southern-hoppinjohn`,term:`Hoppin’ John`,category:`southern`,aliases:[],definition:`A Southern dish of field peas and rice, associated especially with the Carolina Lowcountry. Versions may use black-eyed peas or red field peas and often include pork seasoning.`,guest:`Hoppin’ John is a comforting dish of peas and rice; I will describe the peas and seasoning used in our version.`,kitchen:`Know the actual pea, rice and stock. Peas should be tender and rice should retain its intended texture; do not call it vegetarian without checking the seasoning.`,compare:`Black-eyed peas are an ingredient, not the whole dish. Sea Island red peas also have a documented place in this tradition.`,correction:``,sources:[{title:`ansonmills.com`,url:`https://ansonmills.com/recipes/454`},{title:`ansonmills.com`,url:`https://ansonmills.com/products/140`}],reviewedOn:`2026-10-15`},{id:`southern-muscadineandscuppernong`,term:`Muscadine Grape`,category:`southern`,aliases:[`Muscadine (and scuppernong)`],ref:`t:muscadine-grape`,definition:`Muscadines are grapes native to the southeastern United States, usually with thick skins and distinctive aromatic pulp. Scuppernong is a named bronze muscadine cultivar, though the word is also used loosely for bronze muscadines.`,guest:`Muscadine brings a fragrant Southern grape flavor; Scuppernong is one bronze variety.`,kitchen:`Check skins and seeds when preparing a sauce, jelly or dessert. Use the product name on the supplier’s label when naming the grape.`,compare:`Scuppernong is not a separate fruit and not the correct cultivar name for every bronze muscadine.`,correction:``,sources:[{title:`University of Georgia Extension`,url:`https://extension.uga.edu/content/dam/extension-county-offices/houston-county/21_SeptemberOctober.pdf`}],reviewedOn:`2026-10-15`},{id:`southern-sorghum`,term:`Sorghum`,category:`southern`,aliases:[],definition:`A syrup made by pressing juice from sweet-sorghum stalks and concentrating it. Its flavor can be earthy, malty and deeply sweet.`,guest:`Sorghum is a rich syrup made from the juice of sweet-sorghum stalks.`,kitchen:`Use as a sweetener or finishing syrup and balance its strong flavor. Distinguish the syrup from dry sorghum grain or flour on a recipe sheet.`,compare:`Sometimes called sorghum molasses, it is not the same product as molasses left from sugar refining.`,correction:``,sources:[{title:`fcs.mgcafe.uky.edu`,url:`https://fcs.mgcafe.uky.edu/commodity/sorghum`},{title:`publications.ca.uky.edu`,url:`https://publications.ca.uky.edu/files/agr122.pdf`}],reviewedOn:`2026-10-15`},{id:`southern-redeyegravy`,term:`Red eye gravy`,category:`southern`,aliases:[],definition:`A thin, savory pan gravy commonly made from country-ham drippings and brewed coffee. Recipes may add water or a little sugar.`,guest:`Red-eye gravy is a savory ham-pan sauce with coffee, traditionally served with ham, biscuits or grits.`,kitchen:`Taste for salt before adding more: country ham is already cured. Confirm the house recipe; it is not automatically a thickened cream gravy.`,compare:`Different from white sausage gravy. Coffee belongs to a documented preparation, but colorful stories about the name should be labelled folklore.`,correction:``,sources:[{title:`pbsnc.org`,url:`https://www.pbsnc.org/blogs/lifestyle/allan-and-sharon-benton-country-ham-red-eye-gravy/`}],reviewedOn:`2026-10-15`},{id:`southern-gumbo`,term:`Gumbo`,category:`southern`,aliases:[`Seafood gumbo`],definition:`A Louisiana stew ladled over rice, built on a stock and the holy trinity and thickened with roux, okra, filé or a mix of them. It is made with seafood, with chicken and andouille, or with greens, as in gumbo z’herbes. A seafood gumbo uses a stock from the shells, and the shrimp, crab and oysters go in at the end so they stay tender. Okra gumbos and filé gumbos were traditionally distinct, and using both in one pot is uncommon.`,guest:`Gumbo is the dish that tells Louisiana’s story in one bowl: a roux from French cooking, a name that most likely comes from a West African word for okra and filé from the Choctaw. Ours is shrimp, crab and oysters with smoky andouille, ladled over Louisiana popcorn rice.`,kitchen:`Started on a dark roux and the trinity, simmered in seafood stock with the andouille, and the seafood added last. The Thanksgiving menu printed it as Seafood Filé Gumbo; whether the pot also carries okra is a question for the kitchen.`,compare:`Jambalaya cooks the rice in the pot with the meat and seafood; gumbo is a soup ladled over rice cooked on its own.`,correction:``,sources:[{title:`64 Parishes: Gumbo`,url:`https://64parishes.org/entry/gumbo`},{title:`64 Parishes: Choctaw Gumbo`,url:`https://64parishes.org/choctaw-gumbo`},{title:`64 Parishes: Okra`,url:`https://64parishes.org/entry/okra`},{title:`Louisiana State Legislature: RS 49:170.12, State cuisine`,url:`https://legis.la.gov/legis/law.aspx?d=285562`},{title:`64 Parishes: Filé`,url:`https://64parishes.org/entry/file`},{title:`Southern Foodways Alliance: Southern Gumbo Trail`,url:`https://www.southernfoodways.org/oral-history/southern-gumbo-trail`}],reviewedOn:`2026-11-27`,say:`GUM-boh`,background:`Gumbo’s name most likely comes from a Central Bantu word for okra, ki ngombo, though some scholars point instead to kombo, the Choctaw word for ground sassafras. The dish joins all three: the French roux, West African okra and Choctaw filé. The earliest known record in Louisiana is a 1764 New Orleans interrogation in which an enslaved woman named Comba says she gave others un gombeau, though whether the word meant the dish or okra is still debated. By the Louisiana Purchase of 1803 gumbo was firmly in the local diet, and that year the French prefect, Pierre Clément de Laussat (1756 to 1835), ate it at a New Orleans gala. In 2004 the Legislature made gumbo the official state cuisine of Louisiana.`,metAt:`Brennan's Thanksgiving Day 2026: Seafood Gumbo, printed on the menu as Seafood Filé Gumbo`},{id:`southern-file`,term:`Filé`,category:`southern`,aliases:[`Filé powder`,`Gumbo filé`],definition:`Dried, ground leaves of the sassafras tree, used to season and thicken gumbo. It goes in at the very end, after the pot comes off the heat, because boiling turns it stringy and ropey. It is one of gumbo’s three traditional thickeners, with roux and okra, and cooks traditionally use filé or okra in a pot, not both.`,guest:`Filé is ground sassafras leaf, a seasoning Louisiana learned from the Choctaw, stirred into gumbo at the end to thicken it and add an earthy note. On Thanksgiving Day it was the filé in the name of our Seafood Filé Gumbo; the everyday menu does not print filé, so whether tonight’s gumbo carries it is a question I can check for you.`,kitchen:`Added after the pot comes off the heat, just before serving; boiled in the pot it turns ropey.`,compare:`Okra also thickens gumbo, but it cooks in the pot from the start; filé goes in at the end, and cooks traditionally choose one or the other.`,correction:``,sources:[{title:`64 Parishes: Filé`,url:`https://64parishes.org/entry/file`},{title:`64 Parishes: Choctaw Gumbo`,url:`https://64parishes.org/choctaw-gumbo`},{title:`Britannica: Filé`,url:`https://www.britannica.com/topic/file-spice`},{title:`Slow Food Foundation, Ark of Taste: Handmade Filé`,url:`https://www.fondazioneslowfood.com/en/ark-of-taste-slow-food/handmade-file-2/`}],reviewedOn:`2026-11-27`,say:`FEE-lay`,background:`Filé comes from the Choctaw, who gathered the leaves of the sassafras tree, dried them and ground them with a mortar and pestle. The Choctaw word for the plant and its powder is kombo, and some scholars think the name gumbo comes from it. Choctaw vendors sold filé to the Creoles of New Orleans in the early days of the French Market, and a drawing of about 1870, Indian Gumbo Sellers, French Market, shows them there. Slow Food’s Ark of Taste lists handmade filé from the Cajun country of southwest Louisiana, where a few small producers harvest, dry and cure the leaves by hand and pound them with a pestle in a cypress mortar.`,metAt:`Brennan's Thanksgiving Day 2026: Seafood Gumbo, printed on the menu as Seafood Filé Gumbo`},{id:`southern-grillades`,term:`Grillades`,category:`southern`,aliases:[`Grillades and grits`],definition:`Thin pieces of veal or beef, usually from the round, pounded flat, browned and then simmered slowly in a gravy until tender. The dish is served over grits and belongs to the New Orleans Creole breakfast and brunch table. The name is the French grillade, from griller, to grill, but grillades are not grilled: they are braised in their gravy.`,guest:`Grillades are a New Orleans Creole classic: thin slices of veal pounded tender, browned and then simmered slowly in a rich gravy, and served over grits. Despite the name they are not grilled. They began as a breakfast and brunch dish, and on our Thanksgiving menu they came to dinner over cheddar grits.`,kitchen:`The meat is pounded thin, seasoned, seared and then braised low in its gravy until a fork cuts it. The cut, the gravy and whether the meat is veal or beef are the chef’s to confirm at lineup.`,compare:`Its nearest neighbor is the breaded grillade, which the Picayune’s Creole Cook Book gives beside grillades with gravy: the same pounded meat, but crumbed, where grillades with gravy are browned and then simmered soft. The gravy and the fork tender bite are the tell.`,correction:``,sources:[{title:`Wikipedia: Grillades`,url:`https://en.wikipedia.org/wiki/Grillades`},{title:`Barry Popik: Grillades`,url:`https://barrypopik.com/blog/grillades`},{title:`ckbk: The Picayune’s Creole Cook Book, Grillades With Gravy`,url:`https://app.ckbk.com/recipe/thep19270c06s001ss003r013/grillades-with-gravy`},{title:`ckbk: The Picayune’s Creole Cook Book, Grillades Breaded`,url:`https://app.ckbk.com/recipe/thep19270c06s001ss003r014/grillades-breaded`},{title:`New Orleans Magazine: Kings and Queens`,url:`https://www.myneworleans.com/kings-and-queens/`},{title:`Wikipedia: Picayune Creole Cookbook`,url:`https://en.wikipedia.org/wiki/Picayune_Creole_Cookbook`},{title:`New Orleans Magazine: Cook Me Something, Mister`,url:`https://www.myneworleans.com/cook-me-something-mister/`}],reviewedOn:`2026-11-27`,say:`gree-YAHDS`,background:`Grillade is French for a piece of grilled meat, from griller, to grill, yet in New Orleans the word came to mean meat braised in gravy. The printed record begins in the 1890s. The Daily Picayune ran a recipe for Grillades a la Creole on September 7, 1898, and a breakfast menu in the Times-Democrat listed grillades and grits on April 2, 1900. The Picayune’s Creole Cook Book, first published in New Orleans in 1900, gave grillades with gravy, a round steak beaten well, cut into squares and cooked with tomatoes and onion, beside a breaded version. The dish settled into the city’s breakfast and brunch tradition and into Carnival, where grillades and grits became a dish of the late breakfasts held after the krewes’ balls.`,metAt:`Brennan's Thanksgiving Day 2026: Veal Grillades`},{id:`southern-debris`,term:`Debris`,category:`southern`,aliases:[`Débris`,`Roast beef debris`],definition:`In New Orleans, the tender shreds and scraps of roast that fall away into the pan juices as the meat roasts and is carved, cooked down into a thick, meaty gravy. It is best known spooned onto a roast beef po’ boy, where it soaks the French bread. The word is the French débris, remains or scraps, and New Orleans keeps a French sound for it, DAY bree.`,guest:`Debris, said DAY bree, is a New Orleans word for the tender shreds of roast that fall into the gravy as the meat cooks and is carved, so the gravy turns thick with meat. It is what goes on a roast beef po’ boy dressed with debris. On our Thanksgiving menu it was spooned over the Veal Grillades; which roast it came from was the kitchen’s to say.`,kitchen:`Debris is what the roast gives up: the bits that fall during roasting and carving stay in the juices and are cooked down until the gravy is thick with meat. Which roast it comes from, and whether it is beef or veal, is the chef’s to confirm before a server describes it.`,compare:`Jus is its nearest neighbor: jus is the thin roasting juice served beside the meat, while debris is that juice thick with shredded meat, heavy enough to be a filling of its own. Meat in the gravy is the tell.`,correction:``,sources:[{title:`Merriam-Webster: Debris`,url:`https://www.merriam-webster.com/dictionary/debris`},{title:`Dictionary.com: Debris`,url:`https://www.dictionary.com/browse/debris`},{title:`Wikipedia: Po’ boy`,url:`https://en.wikipedia.org/wiki/Po%27_boy`},{title:`64 Parishes: Po-Boy Sandwich`,url:`https://64parishes.org/entry/po-boy-sandwich`},{title:`Washington Times: The Messy History of the Po-Boy`,url:`https://www.washingtontimes.com/news/2016/oct/8/the-messy-history-of-the-po-boy/`},{title:`Barry Popik: Debris (sandwich)`,url:`https://barrypopik.com/blog/deris_sandwich`},{title:`Tasting Table: Debris Is the Louisiana Term That Takes Sandwiches to the Next Level`,url:`https://www.tastingtable.com/1511453/what-is-debris-louisiana-sandwiches`},{title:`Explore Louisiana: Mother’s Restaurant`,url:`https://www.explorelouisiana.com/la-dining/mothers-restaurant`},{title:`The Daily Meal: Mother’s Restaurant`,url:`https://www.thedailymeal.com/mother-s-restaurant-new-orleans-la`},{title:`New Orleans Historical: Po-Boy Sandwich`,url:`https://neworleanshistorical.org/items/show/480`}],reviewedOn:`2026-11-27`,say:`DAY-bree`,background:`Débris is French for remains or rubble, from the Middle French debriser, to break up, and English took the word in the early 1700s. New Orleans gave it a kitchen meaning and kept the French sound. The meaning grew up around the city’s roast beef po’ boy. The po’ boy itself is usually traced to the Martin brothers’ restaurant during the 1929 streetcar strike, a story historians have since questioned. Mother’s Restaurant, opened on Poydras Street in 1938, calls debris its own original, and the story told of it is that a customer asked the first owner for the bits of beef that fell into the gravy as the roast was carved. A 1979 newspaper account adds a pun on that customer’s surname.`,metAt:`Brennan's Thanksgiving Day 2026: the debris on the Veal Grillades`},{id:`southern-turtlesoup`,term:`Turtle Soup`,category:`southern`,aliases:[`Creole Turtle Soup`],definition:`A rich soup of turtle meat chopped fine and simmered in stock, a classic of New Orleans Creole cooking. Brennan's published recipe finishes it with chopped hard-boiled egg, fresh spinach, lemon and sherry. The egg adds richness and the sherry a dry, nutty lift. Mock turtle soup, its English cousin, carries no turtle at all: it was made from calf's head.`,guest:`Our Turtle Soup is a New Orleans Creole classic: turtle meat simmered into a rich, savory soup, with brown butter spinach and grated egg through it and a splash of aged Sherry to finish. If you have never had turtle, think of a deep, finely chopped stew.`,kitchen:`The everyday menu prints 100% turtle meat, brown butter spinach, grated egg and aged Sherry. It carries alcohol, egg and butter; ask the kitchen what thickens it before answering any question about flour or gluten.`,compare:`Mock turtle soup is the English imitation, made from calf's head with no turtle in it; a Creole turtle soup is made from turtle meat, and ours prints all turtle.`,correction:``,sources:[{title:`Brennan's New Orleans: Turtle Soup recipe`,url:`https://www.brennansneworleans.com/recipes/turtle-soup/`},{title:`JSTOR Daily: Turtle Soup, From Class to Mass to Aghast`,url:`https://daily.jstor.org/turtle-soup-from-class-to-mass-to-aghast`},{title:`ckbk: The Picayune's Creole Cook Book, Mock Eggs for Turtle Soup`,url:`https://app.ckbk.com/recipe/thep19270c03s001r029/mock-eggs-for-turtle-soup`},{title:`NPR: Our taste for turtle soup nearly wiped out terrapins`,url:`https://www.npr.org/sections/thesalt/2019/07/18/742326830/our-taste-for-turtle-soup-nearly-wiped-out-terrapins-then-prohibition-saved-them`},{title:`The Public Domain Review: Hannah Glasse, The Art of Cookery (1751 edition)`,url:`https://publicdomainreview.org/collection/the-art-of-cookery/`},{title:`ckbk: The Art of Cookery, To dress a turtle the West Indian way`,url:`https://app.ckbk.com/recipe/arto18880c22s001r001/to-dress-a-turtle-the-west-indian-way`},{title:`Wikipedia: Turtle soup`,url:`https://en.wikipedia.org/wiki/Turtle_soup`},{title:`ckbk: The Picayune's Creole Cook Book, Green Turtle Soup`,url:`https://app.ckbk.com/recipe/thep19270c03s001r026/green-turtle-soup`}],reviewedOn:`2026-11-27`,say:`TUR-tul SOOP`,background:`Turtle soup was a dish of the elite in eighteenth century England, made from green turtles brought in by ship, and its cost gave rise to mock turtle soup, made from calf's head for those who could not afford the real thing. Hannah Glasse (1708 to 1770) printed a recipe for dressing a turtle the West India way in her Art of Cookery. In America cooks made it from native turtles such as the snapping turtle and the terrapin, and New Orleans took it into its Creole cooking. The Picayune's Creole Cook Book of 1901 prints a green turtle soup, a second turtle soup and a recipe for mock eggs for turtle soup. Brennan's own published recipe carries the egg forward, chopped hard-boiled, with sherry, fresh spinach and lemon.`,metAt:`Brennan's Thanksgiving Day 2026: Classic Turtle Soup`},{id:`southern-creoleandcajun`,term:`Creole and Cajun`,category:`southern`,aliases:[`Creole cooking`,`Cajun cooking`],definition:`The two Louisiana cooking traditions. Creole is the cooking of New Orleans, its households and restaurants, French at the root and shaped by Spanish, West African and Native American cooks, with butter, cream, tomato and sauces. Cajun is the country cooking of the Acadians, French speaking exiles from Canada who made new homes on the bayous and prairies west of the city, a cooking of one pot, rice, pork, shellfish and game. The two share techniques such as the roux and the trinity of onion, celery and bell pepper.`,guest:`Creole is New Orleans city cooking, French at heart, with butter, cream and tomato; Cajun is the country cooking of the Acadians to the west, built around one pot and rice. Brennan's is a Creole house, and our turtle soup and gumbo are Creole soups.`,kitchen:`A dish's label is the menu's: call it Creole or Cajun only as the menu or the chef does, and leave how hot a dish runs to the kitchen.`,compare:`Creole is the city and Cajun the country: Creole cooking reaches for butter, cream and tomato, Cajun for pork, shellfish and game cooked in one pot over rice.`,correction:``,sources:[{title:`National Park Service, Jean Lafitte National Historical Park: From Acadian to Cajun`,url:`https://www.nps.gov/jela/historyculture/from-acadian-to-cajun.htm`},{title:`64 Parishes: Creoles`,url:`https://64parishes.org/entry/creoles`},{title:`64 Parishes: Cookbooks`,url:`https://64parishes.org/entry/cookbooks`},{title:`The Historic New Orleans Collection: Lafcadio Hearn and La Cuisine Creole`,url:`https://www.hnoc.org/node/237`},{title:`MPR News (NPR): Louisiana chef Paul Prudhomme, who popularized Cajun food, dies`,url:`https://www.mprnews.org/story/2015/10/08/npr-prudhomme`},{title:`Acadian Memorial: Acadian Immigration into South Louisiana, 1764 to 1785`,url:`https://acadianmemorial.org/acadian-immigration-into-south-louisiana-1764-1785/`},{title:`64 Parishes: Acadians in Colonial Louisiana, Adaptation`,url:`https://64parishes.org/entry/acadians-colonial-louisiana-adaptation`},{title:`64 Parishes: Paul Prudhomme`,url:`https://64parishes.org/entry/paul-prudhomme`}],reviewedOn:`2026-11-27`,say:`KREE-ohl and KAY-jun`,background:`Creole comes through French créole and Spanish criollo from a Portuguese word for someone born in the colonies, and in Louisiana it came to name people born there, of any color. Two cookbooks of 1885 carried the city's cooking to a wider audience: La Cuisine Creole, credited to Lafcadio Hearn (1850 to 1904), and The Creole Cookery Book of the Christian Woman's Exchange, a New Orleans women's charity, both published for the World's Industrial and Cotton Centennial Exposition. The Cajuns descend from the Acadians, whom the British began removing from their homeland in 1755; from 1764 exiles reached Louisiana and settled the bayous and prairies west of the city, where many raised cattle. Their cooking reached the whole country after Paul Prudhomme (1940 to 2015), born near Opelousas, opened K-Paul's Louisiana Kitchen in the French Quarter in 1979.`,metAt:`Brennan's Thanksgiving Day 2026: Classic Turtle Soup, Seafood Gumbo and Shrimp Sauce Piquante`},{id:`southern-oystersrockefeller`,term:`Oysters Rockefeller`,category:`southern`,aliases:[`Rockefeller`],definition:`Oysters on the half shell covered with a rich green sauce and baked until hot, a dish created at Antoine’s in the French Quarter. The original recipe is a family secret, and Antoine’s chefs have said it holds no spinach. Most versions made since use spinach for the green. The Brennan’s Thanksgiving Day gratin of 2026 took the idea into creamed spinach, bacon and breadcrumbs.`,guest:`Oysters Rockefeller was born in the French Quarter at Antoine’s, in 1899 by most accounts, and named for John D. Rockefeller, the richest American of his day, for the richness of its green sauce. The recipe has long been kept a family secret. Our Thanksgiving Day gratin took the idea into oysters baked with bacon and creamed spinach under a crisp breadcrumb top.`,kitchen:`The classic is baked or broiled on the half shell until the topping browns and the dish comes out hot. Whether the Thanksgiving gratin was built in the shell or in one dish, and how many oysters went into a portion, was the kitchen’s to say.`,compare:`A raw oyster on the half shell comes to the table cold and as it is; oysters Rockefeller is baked under a green topping and served hot, so the oyster is cooked.`,correction:``,sources:[{title:`64 Parishes: Antoine’s Restaurant`,url:`https://64parishes.org/entry/antoines-restaurant`},{title:`Wikipedia: Oysters Rockefeller`,url:`https://en.wikipedia.org/wiki/Oysters_Rockefeller`},{title:`Food Republic: How Oysters Rockefeller Were Created In 1899`,url:`https://www.foodrepublic.com/2075014/oysters-rockefeller-origins-1899/`},{title:`Britannica: John D. Rockefeller`,url:`https://www.britannica.com/biography/John-D-Rockefeller`},{title:`Wikipedia: Antoine’s`,url:`https://en.wikipedia.org/wiki/Antoine%27s`},{title:`Tasting Table: Oysters Rockefeller Was Named For The Richest Man In The World`,url:`https://www.tastingtable.com/1132785/oysters-rockefeller-was-named-for-the-richest-man-in-the-world`}],reviewedOn:`2026-11-27`,say:`OY-sterz ROCK-uh-fell-er`,background:`Antoine’s opened in New Orleans in 1840 and is counted among the oldest family run restaurants in the United States. In 1899, by most accounts, the founder’s son, who had trained in France, found the snails he imported from France hard to come by and put local Gulf oysters under a rich green sauce in their place. He named the dish for John D. Rockefeller (1839 to 1937), the wealthiest American of the day, for the richness of the sauce; some accounts add that its green recalled paper money. The recipe stayed a family secret, and Antoine’s chefs have long said it holds no spinach, though most cooks since have used it. A few sources give the year as 1889.`,metAt:`Brennan's Thanksgiving Day 2026: Rockefeller Gratin`},{id:`southern-pecan`,term:`Pecan`,category:`southern`,aliases:[`Pecans`,`Carya illinoinensis`],definition:`The nut of Carya illinoinensis, a hickory whose native range centers on the lower Mississippi valley and reaches into Mexico, so Louisiana lies within it and the tree grows wild there. The kernel is rich, buttery and sweet, high in oil, and it toasts quickly. Native Louisiana pecans are smaller than the improved varieties, with a high oil content and full flavor. In Louisiana the harvest begins in October and runs toward Christmas, so the new crop arrives with the holidays.`,guest:`Pecans are native to this part of the country and grow wild in Louisiana; the new crop comes in each fall, just in time for the holidays. On Thanksgiving Day they came candied, sweet and crunchy, on the sweet potato agnolotti with brown butter and goat cheese.`,kitchen:`Toasted gently, because their oil scorches fast, and candied pecans are cooled until crisp before they go on the plate. Every nut question goes to the kitchen and the service note.`,compare:`The walnut is its nearest neighbor, a cousin in the same family: a pecan is longer and smoother, sweeter and more buttery, while a walnut is rounder and wrinkled, with a more bitter, tannic skin.`,correction:``,sources:[{title:`Dictionary.com: pecan`,url:`https://www.dictionary.com/browse/pecan`},{title:`Clemson Cooperative Extension HGIC: Pecan Tidbits`,url:`https://hgic.clemson.edu/pecan-tidbits/`},{title:`National Park Service: Pecan Tree`,url:`https://www.nps.gov/places/pecan-tree.htm`},{title:`Zocalo Public Square: The slave gardener who turned the pecan into a cash crop`,url:`https://live-zocalopublicsquare.ws.asu.edu/?p=89973`},{title:`Pecan South: The beginning of modern pecan culture, Centennial`,url:`https://www.pecansouthmagazine.com/magazine/article/the-beginning-of-modern-pecan-culture-centennial/`},{title:`LSU AgCenter: Dry early fall affecting pecan quality for some producers`,url:`https://www.lsuagcenter.com/articles/page1732649390158`},{title:`LSU AgCenter: Uncovering Louisiana's hidden pecan gems`,url:`https://www.lsuagcenter.com/articles/page1748959422645`},{title:`LSU AgCenter: Louisiana pecan industry still catching up from 2011 drought`,url:`https://apps.lsuagcenter.com/news_archive/2014/November/headline_news/Louisiana-pecan-industry-still-catching-up-from-2011-drought-.htm`},{title:`64 Parishes: Pralines`,url:`https://64parishes.org/entry/pralines`},{title:`New Orleans Historical: Praline or Pecan Candy`,url:`https://neworleanshistorical.org/items/show/259`},{title:`Wikipedia: Praline (nut confection)`,url:`https://en.wikipedia.org/wiki/Praline_(nut_confection)`},{title:`USDA Forest Service, Silvics of North America: Pecan`,url:`https://research.fs.usda.gov/silvics/pecan`},{title:`USDA Forest Service, Agriculture Handbook 654: Carya illinoensis`,url:`https://www.srs.fs.usda.gov/pubs/misc/ag_654/volume_2/carya/illinoesis.htm`}],reviewedOn:`2026-11-27`,say:`pih-KAHN`,background:`The word pecan came into English through the French of the Mississippi valley, pacane, from an Algonquian word for a nut, often glossed as a nut that needs a stone to crack. The tree is native to the Mississippi valley and south into Mexico, and its nuts were gathered long before Europeans arrived. A pecan does not grow true from seed. In the winter of 1846 an enslaved gardener at Oak Alley Plantation in St. James Parish, Louisiana, grafted cuttings of a fine wild tree onto other trees, and his grafts became the Centennial, named after its nuts were shown at the Centennial Exhibition in Philadelphia in 1876, the first pecan variety known to have been propagated by grafting. In nineteenth century New Orleans, cooks put pecans in place of the almonds of the French praline and added cream, and the pecan praline became a New Orleans candy.`,metAt:`Brennan's Thanksgiving Day 2026: Sweet Potato Agnolotti, with candied pecans`},{id:`southern-dressing`,term:`Dressing`,category:`southern`,aliases:[`Cornbread dressing`],definition:`A savory mixture of bread with broth, aromatics and seasoning, baked in its own pan beside the bird rather than inside it. In the South it is most often made with crumbled cornbread, and cooks add their own touches, such as sausage, oysters or pecans. Stuffing is the name for the same kind of mixture cooked inside the bird, though in everyday speech the words cross, and the South and Midwest tend to say dressing. On the Thanksgiving Day menu cornbread dressing came with the turkey.`,guest:`Dressing is the Southern way with stuffing: crumbled cornbread with broth, aromatics and seasoning, baked in its own pan rather than inside the bird. Ours came with the Thanksgiving turkey, and for the table there was also Titus’ BBQ Shrimp Stuffing, a New Orleans turn on the same idea.`,kitchen:`Baked apart from the bird, the dressing browns on top and cooks through on its own; food safety guidance asks that any stuffing reach 165 °F at its center. What went into the house cornbread dressing was a question for lineup, so never guess at sausage or oysters.`,compare:`Stuffing is its nearest neighbor: stuffing is cooked inside the bird and dressing is baked in its own pan, but in the South dressing is often the word for both, so ask how it was cooked, not what it was called.`,correction:``,sources:[{title:`Dictionary.com: Stuffing or Dressing?`,url:`https://www.dictionary.com/e/stuffing-or-dressing/`},{title:`New England Today: Dressing vs. Stuffing`,url:`https://newengland.com/food/dressing-vs-stuffing/`},{title:`Betty Crocker: Dressing vs. Stuffing`,url:`https://bettycrocker.com/how-to/ingredients-and-preparation/dressing-vs-stuffing`},{title:`Culinary Lore: Dressing Versus Stuffing`,url:`https://culinarylore.com/food-history:stuffing-versus-dressing/`},{title:`Wikipedia: Cornbread`,url:`https://en.wikipedia.org/wiki/Cornbread`},{title:`Museum of the New South: Cornbread`,url:`https://www.museumofthenewsouth.org/southern-tables/cornbread`},{title:`VICE: A People’s History of Cornbread Stuffing`,url:`https://www.vice.com/en/article/a-peoples-history-of-cornbread-stuffing`},{title:`Orlando Sentinel: Black history on a plate: cornbread dressing`,url:`https://www.pressreader.com/usa/orlando-sentinel/20191121/282273847205555`},{title:`USDA: Keep Food Safety in Mind This Thanksgiving`,url:`https://www.usda.gov/article/keep-food-safety-mind-thanksgiving`},{title:`Gunston Hall: Kush`,url:`https://gunstonhall.org/?p=2247`},{title:`Mental Floss: What’s the Difference Between Stuffing and Dressing?`,url:`https://www.mentalfloss.com/article/516862/whats-difference-between-stuffing-and-dressing`}],reviewedOn:`2026-11-27`,say:`DRESS-ing`,background:`Cornbread, the base of the Southern dressing, is a quick bread of cornmeal with its origins in Native American cooking. In the South, enslaved cooks given cornmeal as a ration made kush, cornbread mashed with onions and served with gravy, a dish some food historians count as a forerunner of baked cornbread dressing, with roots reaching back to the grain dishes of West Africa. The names now split by region: the Northeast tends to say stuffing, the South and Midwest dressing. A popular story holds that the Victorians preferred dressing because stuffing sounded crude, but the record does not prove it, and where the split began is hard to say.`,metAt:`Brennan's Thanksgiving Day 2026: cornbread dressing with the Roasted Buttermilk-Brined Turkey Breast, and Titus’ BBQ Shrimp Stuffing`},{id:`southern-canesyrup`,term:`Cane Syrup`,category:`southern`,aliases:[`Louisiana cane syrup`,`Pure cane syrup`],definition:`A syrup made by pressing the juice from sugarcane stalks and boiling it down, traditionally in open kettles, until it turns thick and amber. Nothing is taken out along the way, so it keeps the flavor of the whole cane juice: sweet, mild and caramel-like, much as maple syrup keeps the taste of the sap. It is lighter in color and gentler in taste than molasses, which is what is left after sugar has been crystallized out of boiled cane juice. On the Thanksgiving Day menu it glazed the bacon-wrapped pork tenderloin.`,guest:`Cane syrup is Louisiana sugarcane juice boiled down until it is thick, the way maple sap becomes maple syrup, so it tastes of the cane itself: sweet, mellow and a little like caramel. On Thanksgiving Day it glazed our bacon-wrapped pork tenderloin, a local sweetness against the smoky bacon.`,kitchen:`Cane syrup and molasses are not interchangeable on a recipe sheet: molasses is darker and has more bite. How and when the glaze went on the pork, and what else went into it, was a question for lineup.`,compare:`Molasses is the nearest neighbor: molasses is what remains once sugar is refined out of boiled cane juice, so it is darker and sharper, while cane syrup is the whole juice simply boiled down, lighter and milder. Sorghum syrup looks alike but is pressed from sorghum stalks, not sugarcane.`,correction:``,sources:[{title:`Steen's Syrup: About`,url:`https://steenssyrup.com/about`},{title:`Wikipedia: Steen's cane syrup`,url:`https://en.wikipedia.org/wiki/Steen%27s_cane_syrup`},{title:`Slow Food Foundation, Ark of Taste: Traditional Cane Syrup`,url:`https://www.fondazioneslowfood.com/en/ark-of-taste-slow-food/traditional-cane-syrup/`},{title:`Milk Street: A guide to cane sugar sweeteners`,url:`https://prod.177milkstreet.com/stories/02-2022-cane-sugar-sweeteners-guide`},{title:`LSU AgCenter: History of sugarcane in Louisiana`,url:`https://www.lsuagcenter.com/topics/crops/sugarcane/history`},{title:`New Orleans Historical: The Boré Plantation: Sugar Production and its Impact on Slavery in the 19th Century`,url:`https://neworleanshistorical.org/items/show/1656`},{title:`Britannica: Jean Étienne de Boré`,url:`https://www.britannica.com/biography/Jean-Etienne-de-Bore`}],reviewedOn:`2026-11-27`,say:`KAYN SIR-up`,background:`Sugarcane became the great crop of south Louisiana after 1795, when enslaved workers on a plantation just upriver of New Orleans, on land that is now Audubon Park, made the first granulated sugar known in the colony, and the sugar boom followed. Cane syrup is the plainer product of the same plant: the pressed juice boiled down whole rather than refined. The Steen mill in Abbeville traces its story to 1910, when an early freeze struck the family's cane crop and they saved it by grinding the stalks and cooking the juice down into syrup in open kettles. By 1930 the family had built a larger mill on the banks of Bayou Vermilion. Slow Food's Ark of Taste lists traditional Louisiana cane syrup among the heritage foods it works to keep alive.`,metAt:`Brennan's Thanksgiving Day 2026: the cane syrup glaze of the Bacon-Wrapped Pork Tenderloin`},{id:`southern-bbqshrimp`,term:`BBQ Shrimp`,category:`southern`,aliases:[`Barbecue shrimp`,`New Orleans barbecue shrimp`],definition:`A New Orleans dish of large shrimp, traditionally cooked with their heads and shells on, in a pan sauce of butter, black pepper and Worcestershire, often with garlic, lemon and hot sauce. It never goes near a grill or a smoker: the barbecue in the name points to the reddish brown color of the sauce and its peppery bite. Guests peel the shrimp at the table, which makes it a messy, hands on dish.`,guest:`New Orleans BBQ shrimp is never barbecued: it is shrimp cooked in a rich pan sauce of butter, black pepper and Worcestershire, a dish credited to Pascal’s Manale, Uptown, in the 1950s. Our Thanksgiving side, Titus’ BBQ Shrimp Stuffing, took that New Orleans style into a holiday stuffing for the table.`,kitchen:`Cooked fast in a hot pan so the shrimp stay tender, with the heads left on in the traditional version because they flavor the sauce. What the Thanksgiving stuffing was built on was the kitchen’s to say, so describe the style, not the recipe.`,compare:`Shrimp off a grill or a barbecue pit is its namesake and its opposite: those take their flavor from fire and smoke, while New Orleans BBQ shrimp never touches a grill and takes everything from its butter and pepper sauce. No fire is the tell.`,correction:``,sources:[{title:`NPR: Hacking Iconic New Orleans Barbecue Shrimp Far from the Gulf`,url:`https://www.npr.org/sections/thesalt/2015/07/19/423605844/hacking-iconic-new-orleans-barbecue-shrimp-far-from-the-gulf`},{title:`The Daily Meal: New Orleans Style Barbecue Shrimp Never Actually Touches a Grill`,url:`https://www.thedailymeal.com/1553498/new-orleans-barbecue-shrimp`},{title:`Rouses Markets: The History of Barbecue Shrimp`,url:`https://www.rouses.com/?p=1146`},{title:`Biz New Orleans: Keepers of the Flame`,url:`https://bizneworleans.com/keepers-of-the-flame/`},{title:`Only In Your State: The BBQ Shrimp from Pascal’s Manale`,url:`https://www.onlyinyourstate.com/food/louisiana/shrimp-pascals-nola`},{title:`Press Herald: New Orleans barbecue shrimp`,url:`https://www.pressherald.com/?p=6461606`},{title:`New Orleans & Company: New Orleans Barbecue Shrimp`,url:`https://www.neworleans.com/restaurants/traditional-new-orleans-foods/bbq-shrimp/`},{title:`New Orleans Magazine: Pascal’s Manale`,url:`https://www.myneworleans.com/pascals-manale/`},{title:`Via Nola Vie: Pascal’s Manale`,url:`https://vianolavie.org/?p=7976`}],reviewedOn:`2026-11-27`,say:`BAR-bih-kyoo shrimp`,background:`Barbecue shrimp is credited to Pascal’s Manale, an Uptown New Orleans restaurant that opened as Manale’s in 1913 and was renamed Pascal’s Manale by the founder’s nephew, who took it over after his uncle died in 1937 and kept his uncle’s name beside his own. The dish arrived in the 1950s; accounts give 1953, 1954 or simply the middle of the decade. The story usually told is that a regular came back from a business trip to Chicago describing a shrimp dish he had eaten there, and the kitchen worked out its own version from his account, though no record confirms it. Other New Orleans kitchens took the dish up, each with its own sauce of butter, pepper and Worcestershire, and the traditional version keeps the shrimp heads on for flavor. There is no grill, no coals and no smoke in any of them.`,metAt:`Brennan's Thanksgiving Day 2026: Titus’ BBQ Shrimp Stuffing`},{id:`mushrooms-abalone`,term:`Abalone Mushroom`,category:`mushrooms`,aliases:[`Abalone`,`Abalone Oyster Mushroom`],ref:`c:fd_0138`,definition:`An oyster-family mushroom sold under a name that evokes abalone’s firm, springy texture. Trade names vary, so the supplier’s identification matters.`,guest:`Abalone mushroom is a mushroom, with a firm, springy bite.`,kitchen:`Confirm the supplied variety. Trim tough bases, clean and cook; describe the sauce separately.`,compare:`The ingredient is not the shellfish abalone. The name alone does not establish the complete dish’s allergens.`,correction:``,sources:[{title:`Mushroom Council`,url:`https://www.mushroomcouncil.com/mushroom-101/varieties/oyster/`},{title:`doa.gov.lk`,url:`https://doa.gov.lk/hordi-crop-mushroom/`}],reviewedOn:`2026-10-15`},{id:`mushrooms-beech`,term:`Beech Mushroom`,category:`mushrooms`,aliases:[`Beech`,`Shimeji`,`Buna-Shimeji`,`Clamshell Mushroom`],ref:`c:fd_0139`,definition:`Small white or brown mushrooms sold in clusters, often called bunashimeji. Cooking mellows their bitterness and gives a nutty flavor with a firm bite.`,guest:`Beech mushrooms are small, clustered mushrooms with a delicate, nutty flavor when cooked.`,kitchen:`Trim the joined growing base, separate into small clusters and cook before serving.`,compare:`Beech mushrooms are different from long, thin enoki; the word shimeji can also refer to other mushrooms.`,correction:``,sources:[{title:`Mushroom Council`,url:`https://www.mushroomcouncil.com/mushroom-101/varieties/beech/`}],reviewedOn:`2026-10-15`},{id:`mushrooms-blacktrumpet`,term:`Black Trumpet`,category:`mushrooms`,aliases:[`Horn of Plenty`,`Black Chanterelle`,`Trompette de la Mort`],ref:`c:fd_0140`,definition:`A dark, hollow, funnel-shaped mushroom, usually sold wild-harvested or dried. It has a concentrated earthy flavor and a thin, delicate texture.`,guest:`Black trumpets bring a deep mushroom flavor in delicate, dark pieces.`,kitchen:`Inspect the folds and hollow centers for grit, clean carefully and cook. Dried mushrooms need appropriate rehydration and cooking.`,compare:`Black trumpet is thin and dark; king trumpet is pale, thick-stemmed and much meatier.`,correction:``,sources:[{title:`mdc.mo.gov`,url:`https://mdc.mo.gov/magazines/conservationist/2010-10/fall-wild-mushrooms`},{title:`mdc.mo.gov`,url:`https://mdc.mo.gov/discover-nature/field-guide/chanterelles`}],reviewedOn:`2026-10-15`},{id:`mushrooms-chanterelle`,term:`Chanterelle`,category:`mushrooms`,aliases:[`Girolle`,`Golden Chanterelle`],ref:`c:fd_0141`,definition:`A group of mushrooms often recognised in culinary purchases by golden color, wavy caps and a fruity aroma. The underside has folds or ridges rather than ordinary blade-like gills.`,guest:`Chanterelles have a delicate fruity aroma and a gently earthy flavor.`,kitchen:`Clean folds carefully and cook without overwhelming their aroma. Confirm freshness and supplier identification.`,compare:`Different from the thick-stemmed king trumpet. These brief features are culinary recognition cues, not a safe wild-identification guide.`,correction:``,sources:[{title:`mdc.mo.gov`,url:`https://mdc.mo.gov/discover-nature/field-guide/chanterelles`}],reviewedOn:`2026-10-15`},{id:`mushrooms-henofthewoods`,term:`Hen of the Woods`,category:`mushrooms`,aliases:[`Maitake`,`Sheep's Head`,`Ram's Head`],ref:`c:fd_0142`,definition:`A mushroom that forms layered, ruffled clusters. It has a savory, woodsy flavor; its frilled edges can brown and crisp.`,guest:`Maitake is a ruffled mushroom with a rich, woodsy flavor.`,kitchen:`Separate into manageable clusters, trim any tough base and cook to the intended texture.`,compare:`Hen of the woods is not chicken of the woods, which is a different mushroom.`,correction:``,sources:[{title:`Mushroom Council`,url:`https://www.mushroomcouncil.com/mushroom-101/varieties/maitake/`}],reviewedOn:`2026-10-15`},{id:`mushrooms-kingtrumpet`,term:`King Trumpet`,category:`mushrooms`,aliases:[`King Oyster Mushroom`,`Eryngii`,`French Horn Mushroom`],ref:`c:fd_0143`,definition:`A large oyster-family mushroom with a thick edible white stem and a smaller brown cap. Its firm, meaty texture suits searing or roasting.`,guest:`King trumpet mushrooms have a firm, meaty bite and a delicate nutty flavor.`,kitchen:`Slice lengthwise for broad pieces or across the stem for rounds; both cap and stem can be used.`,compare:`Unlike black trumpet, it is pale and substantial. Mushroom rounds described as scallops are still mushrooms.`,correction:``,sources:[{title:`Mushroom Council`,url:`https://www.mushroomcouncil.com/mushroom-101/varieties/king-trumpet/`}],reviewedOn:`2026-10-15`},{id:`mushrooms-morels`,term:`Morel`,category:`mushrooms`,aliases:[`Morels`],ref:`c:fd_0144`,definition:`A mushroom with a honeycomb-like cap, prized for its earthy flavor. Both wild-harvested and cultivated morels enter food service.`,guest:`Morels have an earthy, nutty character and a honeycomb texture that carries sauce.`,kitchen:`Buy from a reliable food supplier, clean the pockets and cook thoroughly. Raw or insufficiently cooked morels have caused serious illness; marinade is not a substitute for cooking.`,compare:`A morel is not a truffle. A purchased-ingredient description must never be used to identify wild mushrooms.`,correction:``,sources:[{title:`Centers for Disease Control and Prevention`,url:`https://www.cdc.gov/mmwr/volumes/73/wr/mm7310a1.htm`}],reviewedOn:`2026-10-15`},{id:`mushrooms-oyster`,term:`Oyster Mushroom`,category:`mushrooms`,aliases:[`Oyster`,`Pearl Oyster Mushroom`,`Hiratake`],ref:`c:fd_0145`,definition:`A mushroom with a broad, fan-like cap, often growing in overlapping clusters. Its cooked texture is tender with a mild savory flavor.`,guest:`Oyster mushrooms are delicate, fan-shaped mushrooms with a gentle savory flavor.`,kitchen:`Trim a tough joined base if present; separate and cook the caps and tender stems.`,compare:`The name refers to the mushroom’s shape, not an oyster ingredient. Confirm the full recipe before answering an allergy question.`,correction:``,sources:[{title:`Mushroom Council`,url:`https://www.mushroomcouncil.com/mushroom-101/varieties/oyster/`}],reviewedOn:`2026-10-15`},{id:`mushrooms-shiitake`,term:`Shiitake`,category:`mushrooms`,aliases:[],ref:`c:fd_0146`,definition:`A brown-capped mushroom with a deep savory, woodsy flavor. Its stem is often firmer than the cap.`,guest:`Shiitake adds a rich, savory mushroom flavor.`,kitchen:`Remove tough stems for stock if appropriate; cook the caps thoroughly. Raw or undercooked shiitake can cause a distinctive skin reaction in some people.`,compare:`Dried shiitake is concentrated and needs preparation; it is not interchangeable with fresh by volume.`,correction:``,sources:[{title:`Mushroom Council`,url:`https://www.mushroomcouncil.com/mushroom-101/varieties/shiitake/`},{title:`ANSES`,url:`https://www.anses.fr/en/system/files/PRES2021CP03EN.pdf`}],reviewedOn:`2026-10-15`},{id:`mushrooms-truffles`,term:`Truffle`,category:`mushrooms`,aliases:[`Truffles`],ref:`c:fd_0147`,definition:`An aromatic underground fungus associated with tree roots. Different edible species have different seasons and aromas; they occur beyond France and Italy.`,guest:`Truffle is an underground fungus prized for its earthy, savory aroma. On the Thanksgiving Day crudo it added a deep, earthy note against the sweet raw scallops and the bright Meyer lemon; whether it was fresh or preserved was the kitchen’s to say.`,kitchen:`Identify fresh truffle, preserved truffle and truffle-flavored oil separately. Handle and heat according to the particular truffle and recipe.`,compare:`Truffle oil does not necessarily contain pieces of truffle. The chocolate confection called a truffle is a different food.`,correction:``,sources:[{title:`extension.oregonstate.edu`,url:`https://extension.oregonstate.edu/catalog/em-9369-oregon-native-edible-truffles`},{title:`Wikipedia: Tuber melanosporum`,url:`https://en.wikipedia.org/wiki/Tuber_melanosporum`},{title:`France.fr: Truffle`,url:`https://www.france.fr/en/article/truffle/`},{title:`Cornell Mushroom Blog: So you want to be a truffle farmer, part 2`,url:`https://blog.mycology.cornell.edu/2008/04/08/so-you-want-to-be-a-truffle-farmer-part-2`},{title:`Smithsonian Magazine: Brillat-Savarin on truffles, a book excerpt`,url:`https://www.smithsonianmag.com/travel/dangers-erotic-truffles-physiology-taste-transcendental-gastronomy-book-excerpt-cultural-travel-180961646/`}],reviewedOn:`2026-10-15`,say:`TRUF-ul`,background:`The black truffle of the Périgord, Tuber melanosporum, is a winter truffle that grows underground on the roots of oaks and other trees in southern France, Spain and Italy; despite its name, most of the French crop comes from the south east. It is gathered from about November to March and found by scent, with trained dogs or pigs. Its cultivation began early in the nineteenth century in the Vaucluse, when a grower sowed acorns gathered under oaks that bore truffles and found truffles under the young trees, and in 1847 a grower at Carpentras planted oaks from such acorns over some seven hectares. A winter truffle of lesser aroma, Tuber brumale, grows in the same soils and is often confused with it. Jean Anthelme Brillat-Savarin (1755 to 1826) called the truffle the diamond of the art of cookery in The Physiology of Taste.`,metAt:`Brennan's Thanksgiving Day 2026: Bay Scallop Crudo`},{id:`meats-escargot`,term:`Escargot`,category:`meats`,aliases:[],ref:`c:fd_0050`,definition:`Edible land snails, often served with garlic and herb butter. The snail is a land mollusk, a cousin of the clam, bought cleaned and precooked, usually tinned. It tastes of very little on its own, mild and earthy, so it carries the sauce: in the Burgundy classic, butter beaten with garlic, parsley and shallot.`,guest:`Escargot means edible land snail; the familiar Burgundy preparation pairs it with garlic and herb butter.`,kitchen:`Learn whether the kitchen serves shells, a dish with wells or a different preparation before describing the presentation.`,compare:`Escargot is an ingredient; à la bourguignonne describes a preparation.`,correction:``,sources:[{title:`L'Escargot Montorgueil: Restaurant menu and specialty`,url:`https://www.escargotmontorgueil.com/`}],reviewedOn:`2026-10-15`},{id:`meats-guinea`,term:`Guinea Hen`,category:`meats`,aliases:[`Guinea`,`Guinea Fowl`,`Pintade`],ref:`c:fd_0051`,definition:`African farmyard fowl, leaner and a little darker than chicken. Guinea fowl came to European farms from West Africa and is a restless, active bird, naturally lean. More exercise means darker, firmer meat and more flavor than chicken, with only a light game note. Little fat means it dries out fast, so kitchens often braise the legs.`,guest:`It is a farm-raised bird with a lean texture and a flavor a little deeper than chicken.`,kitchen:`Check whether the bird is roasted whole or the cuts are cooked separately; lean meat needs careful timing.`,compare:`Pintade is guinea fowl; it is distinct from both chicken and pheasant.`,correction:``,sources:[{title:`D'Artagnan: Guinea Hen`,url:`https://www.dartagnan.com/guinea-hen-whole/product/FGHWH002.html`}],reviewedOn:`2026-10-15`},{id:`meats-porkbelly`,term:`Pork Belly`,category:`meats`,aliases:[],ref:`c:fd_0094`,definition:`Rich underside cut with alternating layers of lean meat and fat. The boneless underside of the pig, in alternating layers of fat and lean. Slow cooking melts the fat and softens the meat, then high heat crisps the surface or the skin. Rich like short rib but softer and sweeter, so portions are small and come with something sharp.`,guest:`It is the rich belly cut, with layers of lean meat and fat; the preparation determines the finish.`,kitchen:`For a menu description, identify both the cut and process: fresh braised belly, cured belly or another confirmed preparation.`,compare:`Belly is a cut; bacon and pancetta are products made from belly.`,correction:``,sources:[{title:`BC Cook Articulation Committee: Pork: Meat Cutting and Processing for Food Service`,url:`https://opentextbc.ca/meatcutting/chapter/pork/`},{title:`USDA FSIS: Bacon and Food Safety`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-catfish/bacon-and-food-safety`},{title:`Levoni: Smoked Pancetta Cubes`,url:`https://www.levoni.it/en-us/products/sliced-deli-meats/incucina-range/smoked-pancetta-cubes`}],reviewedOn:`2026-10-15`},{id:`meats-quail`,term:`Quail`,category:`meats`,aliases:[],ref:`c:fd_0052`,definition:`Small game bird, often farm-raised, with delicate, flavorful meat. Quail are sold in different sizes and in whole or semi-boneless forms. Farmed birds often have a gentle flavor, but age and breed matter. Check the supplied bird and recipe rather than assuming one weight, cooking time or bone arrangement.`,guest:`It is a small game bird, often farm-raised, with delicate meat and a flavor richer than chicken.`,kitchen:`Whole and semi-boneless birds both exist. Check the supplied form and explain remaining bones before service.`,compare:`Quail is not squab. Semi-boneless does not mean every bone has been removed.`,correction:``,sources:[{title:`D'Artagnan: Quail`,url:`https://www.dartagnan.com/buy/quail/`}],reviewedOn:`2026-10-15`},{id:`meats-squab`,term:`Squab`,category:`meats`,aliases:[],ref:`c:fd_0053`,definition:`Young domestic pigeon with tender, rich, naturally dark meat. Squab are raised in lofts and taken at about four weeks, before they fly, so the muscle is tender. Pigeon breast is all dark meat, full of the iron-rich protein that makes beef red, which gives a deep, slightly livery flavor. It is milder than wild game.`,guest:`Squab is a young domestic pigeon with tender, rich dark meat.`,kitchen:`Learn the kitchen's actual cooking and service specification; the bird's naturally dark meat is not a doneness test.`,compare:`Squab is a young pigeon; quail is a different small bird.`,correction:``,sources:[{title:`D'Artagnan: What Is Squab?`,url:`https://www.dartagnan.com/what-is-a-squab.html`},{title:`USDA FSIS: Smoking Meat and Poultry`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/smoking-meat-and-poultry`}],reviewedOn:`2026-10-15`},{id:`meats-sweetbreads`,term:`Sweetbreads`,category:`meats`,aliases:[],ref:`c:fd_0054`,definition:`Thymus or pancreas used as mild, delicate organ meat. Sweetbreads are the thymus or pancreas of young animals. Preparation may include soaking, blanching, trimming and pressing before a separate cooking stage. A crisp exterior comes from the final preparation, not from the ingredient's identity.`,guest:`They are mild organ meats, usually veal thymus, known for a soft, creamy texture.`,kitchen:`Confirm the animal and preparation; chefs may blanch and trim before a separate sauté, grill or fry.`,compare:`Sweetbreads are glands; liver is another organ with a different flavor and texture.`,correction:``,sources:[{title:`D'Artagnan: What Are Sweetbreads?`,url:`https://www.dartagnan.com/what-are-sweetbreads.html`}],reviewedOn:`2026-10-15`},{id:`meats-snappingturtle`,term:`Snapping Turtle`,category:`meats`,aliases:[`Snapper`,`Alligator Snapping Turtle`,`Common Snapping Turtle`],definition:`A large freshwater turtle of North America, long cooked into American turtle soup. Two kinds share the name: the common snapping turtle, found from southern Canada to the Gulf of Mexico, and the alligator snapping turtle, the largest freshwater turtle in the United States, with three rows of large, pronounced ridges down its shell. The alligator snapper alone carries a worm-like lure on its tongue, which it wriggles to draw fish into reach.`,guest:`The turtle in our soup is Louisiana freshwater turtle, not sea turtle. It is cooked down and chopped fine, so it eats like a rich, savory stew, and it is never the turtles you may have seen in our courtyard.`,kitchen:`Which snapper the kitchen buys, and from whom, is the chef's to say. Never name a species, a farm or a supplier until lineup confirms it.`,compare:`The alligator snapper has three rows of large, pronounced ridges down its shell and a lure on its tongue; the common snapper's shell is lower and smoother, and it has no lure.`,correction:``,sources:[{title:`U.S. Fish and Wildlife Service: Alligator snapping turtle`,url:`https://www.fws.gov/species/alligator-snapping-turtle-macrochelys-temminckii`},{title:`Connecticut DEEP: Common Snapping Turtle fact sheet`,url:`https://portal.ct.gov/deep/wildlife/fact-sheets/common-snapping-turtle`},{title:`LSU Louisiana Fisheries: Alligator snapping turtle harvest regulation, 2004`,url:`https://www.lsu.edu/departments/seagrantfish/news/2004/turtleharvest.htm`},{title:`U.S. Geological Survey: Alligator snapping turtle`,url:`https://www.usgs.gov/centers/wetland-and-aquatic-research-center/science/alligator-snapping-turtle-macrochelys`},{title:`Indiana DNR: Alligator snapping turtle`,url:`https://www.in.gov/dnr/fish-and-wildlife/wildlife-resources/animals/alligator-snapping-turtle`},{title:`Smithsonian National Zoo: Alligator snapping turtle`,url:`https://www.nationalzoo.si.edu/node/10000`},{title:`Missouri Department of Conservation: North American Snapping Turtle`,url:`https://mdc.mo.gov/discover-nature/field-guide/snapping-turtle`},{title:`Wikipedia: Turtle soup`,url:`https://en.wikipedia.org/wiki/Turtle_soup`}],reviewedOn:`2026-11-27`,say:`SNAP-ing TUR-tul`,background:`Louisiana long traded wild snapping turtles. By 1998 it was the only state that still allowed the commercial harvest of the wild alligator snapping turtle, and the United States Geological Survey calls it the last state to end the practice. Worry over the harvest brought a regulation from the Louisiana Department of Wildlife and Fisheries, which took effect late in 2004, barring the commercial harvest of the wild alligator snapper and limiting personal take to one a day for each boat or vehicle. The common snapping turtle ranges far more widely, from southern Canada to the Gulf of Mexico, and people in many parts of the United States eat it in soups and stews.`,metAt:`Brennan's Thanksgiving Day 2026: Classic Turtle Soup`},{id:`meats-turkey`,term:`Turkey`,category:`meats`,aliases:[`Roast turkey`],definition:`A large bird native to North America, Meleagris gallopavo, and the center of the American Thanksgiving table. Its breast and wings are white meat and its legs and thighs are dark meat: color in muscle comes mainly from myoglobin, a protein that stores oxygen, and a farm turkey seldom flies, so its breast stays pale while its working legs turn dark. White meat is lean and dries out when overcooked, while dark meat is richer and takes well to slow cooking. Food safety guidance calls for the bird, and any stuffing, to reach 165 °F.`,guest:`Turkey is the bird at the heart of the American Thanksgiving table, and it is native to this continent. On Thanksgiving Day we served it two ways: the lean white breast brined in buttermilk and roasted, and the richer dark leg braised slowly until tender, so white meat and dark meat lovers each had their favorite.`,kitchen:`Breast and leg cook best apart: the breast comes out once it reaches a safe 165 °F so it stays moist, while the leg is given a long, gentle, covered cook. How long the kitchen brined, roasted and braised was a question for lineup.`,compare:`Chicken is the nearest neighbor: both are poultry with white breast meat and dark leg meat, but a turkey is a far larger bird, so its breast and legs are more often cooked apart, as they were on the Thanksgiving plate.`,correction:``,sources:[{title:`Smithsonian Magazine: Your Thanksgiving Turkey Is a Quintessentially American Bird: An Immigrant`,url:`https://www.smithsonianmag.com/science-nature/thanksgiving-turkey-quintessentially-american-bird-immigrant-180957382/`},{title:`Smithsonian Insider: Smithsonian anthropologist talks turkey, squash, potatoes, cranberries and corn`,url:`https://insider.si.edu/2011/11/smithsonian-anthropologist-bruce-smith-talks-turkeyand-squash-potatoes-cranberries-and-corn`},{title:`Smithsonian Magazine: 10 turkey facts to gobble up this Thanksgiving`,url:`https://www.smithsonianmag.com/blogs/national-zoo-conservation-biology-institute/2026/11/13/10-turkey-facts-to-gobble-up-this-thanksgiving/`},{title:`National Park Service, Lincoln Home: Lincoln and Thanksgiving`,url:`https://www.nps.gov/liho/learn/historyculture/lincoln-and-thanksgiving.htm`},{title:`National Archives Education Updates: Lincoln’s Thanksgiving Proclamation`,url:`https://education.blogs.archives.gov/2020/11/22/lincolns-thanksgiving-proclamation`},{title:`NPR: Why A Turkey Is Called A Turkey`,url:`https://www.npr.org/2008/11/27/97541602/why-a-turkey-is-called-a-turkey`},{title:`Scientific American: Talkin’ Turkey: The Linguistic Link Between the Bird and the Country`,url:`https://www.scientificamerican.com/blog/food-matters/talkin-turkey-the-linguistic-link-between-the-bird-and-the-country/`},{title:`USDA FSIS: Turkey from Farm to Table`,url:`https://rhea.tennessee.edu/wp-content/uploads/sites/145/2020/12/Turkey_from_Farm_to_Table.pdf`},{title:`USDA: Keep Food Safety in Mind This Thanksgiving`,url:`https://www.usda.gov/article/keep-food-safety-mind-thanksgiving`},{title:`PNAS (PMC): Ancient mitochondrial DNA analysis reveals complexity of indigenous North American turkey domestication`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC2840336`},{title:`Audubon: Native Americans Domesticated Turkeys Long Before the Pilgrims Arrived`,url:`https://www.audubon.org/news/native-americans-domesticated-turkeys-long-pilgrims-arrived`},{title:`Merriam-Webster: How the Turkey Got Its Name`,url:`https://www.merriam-webster.com/words-at-play/where-did-your-thanksgiving-turkey-come-from`}],reviewedOn:`2026-11-27`,say:`TUR-kee`,background:`The wild turkey is native to North America. It was domesticated in Mexico more than two thousand years ago; a separate domestication in the American Southwest left no line among today’s farm turkeys, which descend from the Mexican bird. Spanish ships carried it to Europe around 1500, and within about a century it had spread across the continent; European colonists later brought domestic turkeys back across the Atlantic to the eastern colonies. Its English name is usually explained as a carry over from the guinea fowl, an African bird that reached Europe through Turkish traders and was also called a turkey, though other explanations have been offered. In 1863 Abraham Lincoln (1809 to 1865) proclaimed a national Thanksgiving for the last Thursday in November, after a long campaign by a writer who had appealed to him by letter that September.`,metAt:`Brennan's Thanksgiving Day 2026: Roasted Buttermilk-Brined Turkey Breast, with its braised leg`},{id:`cured-andouille`,term:`Andouille`,category:`cured`,aliases:[],ref:`c:fd_0064`,definition:`Coarse, heavily smoked Louisiana pork sausage with garlic and cayenne. Chunks of pork shoulder, not a fine grind, are seasoned with garlic, black pepper and cayenne, cased and smoked hard, often over pecan wood. It comes out firm, dark and smoky enough to season a whole pot. Think kielbasa, but coarser and hotter.`,guest:`Andouille is a coarse, smoked pork sausage from the River Parishes just upriver of New Orleans, made more to season a pot than to eat on its own. In our gumbo it gives a savory, smoky backbone under the shrimp, crab and oysters, and it does mean the gumbo carries pork.`,kitchen:`Confirm the producer and preparation; coarse smoked sausage can contribute flavor as well as visible pieces.`,compare:`Andouille is a sausage; tasso is a spiced smoked piece of meat.`,correction:``,sources:[{title:`Jacob's World Famous Andouille: FAQs & Facts`,url:`https://www.jacobsandouille.com/faqs-facts`},{title:`D'Artagnan: Cooking with Tasso`,url:`https://www.dartagnan.com/tasso-ham-recipes-and-uses.html`},{title:`St. Charles Parish: Parish History`,url:`https://stcharlesparish.gov/residents/economic-development-and-tourism/parish-history`},{title:`St. John the Baptist Parish: History`,url:`https://sjbparish.gov/Visitors/History`},{title:`L'Observateur: the first Andouille Festival in LaPlace, 1972`,url:`https://lobservateur.com/?p=34964`}],reviewedOn:`2026-10-15`,say:`ahn-DOO-ee`,background:`Andouille is a French name and a French sausage, but the Louisiana kind took its shape on the German Coast, the stretch of the Mississippi above New Orleans that German speaking settlers farmed from the early 1720s and that now lies in St. Charles and St. John the Baptist Parishes. German sausage making met the cooking of the French and Black residents there, and the result is lean, chunky pork, cased and smoked hard, often over pecan wood. In LaPlace, Jacob’s traces its andouille to 1928, when a couple from German and French families began selling it from their front yard in Milesville, now part of the town. In 1972 a Louisiana governor named LaPlace the Andouille Capital of the World, the year the town held its first andouille festival.`,metAt:`Brennan's Thanksgiving Day 2026: Seafood Gumbo`},{id:`cured-chorizo`,term:`Chorizo`,category:`cured`,aliases:[],ref:`c:fd_0065`,definition:`Seasoned sausage in fresh and cured forms, with regional differences. Spanish chorizo includes dry-cured slicing sausages and fresh cooking forms, usually seasoned with paprika. Mexican versions commonly use fresh meat and chiles. Paprika is not always smoked, and neither country guarantees a particular heat level.`,guest:`It is a seasoned sausage; the Spanish style is paprika-led, and the exact product determines its smoke, heat and texture.`,kitchen:`Check fresh/cooking versus cured/slicing product before planning service; ask about heat and smoke instead of inferring them.`,compare:`Fresh sausage needs cooking; a dry-cured product may be ready to slice. Country alone is insufficient.`,correction:``,sources:[{title:`Spanish Chorizo Consortium: Chorizo forms`,url:`https://chorizoespanol.es/en/home-english/`}],reviewedOn:`2026-10-15`},{id:`cured-coppa`,term:`Coppa`,category:`cured`,aliases:[`Capocollo`,`Capicola`],ref:`c:fd_0066`,definition:`Italian dry-cured pork neck muscle, marbled and sliced paper thin. The muscle running from the neck into the shoulder is salted, rubbed with pepper and spices, cased and hung to dry for months. Several small muscles meet here, so ribbons of fat run through the lean, making it richer and more seasoned than prosciutto and softer than salami.`,guest:`It is cured pork from the neck area, thinly sliced, with marbling and seasoning.`,kitchen:`Notice an intact muscle pattern and seams of fat, rather than the chopped pattern of a salami.`,compare:`Coppa cures an intact neck cut; salami is made from chopped or ground meat.`,correction:``,sources:[{title:`Consorzio di Tutela: Coppa di Parma production specification`,url:`https://www.coppadiparmaigp.com/disciplinare-di-produzione-igp-coppa-parma/`}],reviewedOn:`2026-10-15`},{id:`cured-countryham`,term:`Country Ham`,category:`cured`,aliases:[],ref:`c:fd_0067`,definition:`American pork leg, dry-salted, often smoked, then aged for months. A whole pork leg is packed in dry salt, often with sugar, usually smoked over hickory, then hung through a summer or longer. It loses water and concentrates, so it eats firm, intensely salty and savory. City ham is brined instead, so it stays moist and mild.`,guest:`It is dry-cured ham with a concentrated, salty flavor; the kitchen chooses a preparation suited to the particular ham.`,kitchen:`Read the supplier's directions before choosing shaved service or a cooking method; seasoning is already concentrated.`,compare:`Country ham is dry-cured; city-style ham commonly uses a wet cure.`,correction:``,sources:[{title:`USDA FSIS: Hams and Food Safety`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-catfish/hams-and-food-safety`}],reviewedOn:`2026-10-15`},{id:`cured-guanciale`,term:`Guanciale`,category:`cured`,aliases:[],ref:`c:fd_0068`,definition:`Italian cured pork jowl, rich in fat and often used in pasta. The jowl is rubbed with salt, black pepper and sometimes herbs, then hung to dry for weeks. It is mostly fat with streaks of lean, and that fat is firmer and more flavorful than belly fat. In a pan it renders into crisp pieces and a savory fat that becomes the sauce.`,guest:`It is cured pork jowl, often rendered into pasta for its rich fat and savory flavor.`,kitchen:`Render pieces according to the recipe and use the flavorful fat deliberately; check whether the supplied product is smoked.`,compare:`Guanciale comes from jowl; pancetta comes from belly. Smoke depends on the product.`,correction:``,sources:[{title:`Levoni: Smoked Guanciale`,url:`https://www.levoni.it/en-us/products/the-specialities/smoked-guanciale`},{title:`Levoni: Smoked Pancetta Cubes`,url:`https://www.levoni.it/en-us/products/sliced-deli-meats/incucina-range/smoked-pancetta-cubes`}],reviewedOn:`2026-10-15`},{id:`cured-lardo`,term:`Lardo`,category:`cured`,aliases:[],ref:`c:fd_0069`,definition:`Italian cured pork back fat, aged with salt and herbs, shaved thin. Thick slabs of fat from the pig's back are layered with sea salt, rosemary, garlic and spices and cured for months, traditionally in marble tubs in Colonnata, Tuscany. The cure firms and perfumes it, so a thin slice turns translucent and melts on anything warm.`,guest:`It is cured pork back fat, sliced thin for a silky texture and aromatic seasoning.`,kitchen:`Slice thinly when the recipe calls for a softening layer over warm food; keep its identity as cured back fat clear.`,compare:`Lardo is cured solid fat; lard is rendered cooking fat.`,correction:``,sources:[{title:`Regione Toscana: PDO and PGI products`,url:`https://prodtrad.regione.toscana.it/spaw2/uploads/files/DOP%20IGP%20ITALIANO%202016%20WEB.pdf`}],reviewedOn:`2026-10-15`},{id:`cured-lomo`,term:`Lomo`,category:`cured`,aliases:[`Lomo Embuchado`,`Lomo Curado`],ref:`c:fd_0070`,definition:`Spanish cured whole pork loin, often seasoned with paprika and garlic. The whole pork loin is seasoned, cased and dried as an intact cut. Paprika and garlic are common, though versions without paprika exist. Texture, marbling and seasoning depend on the pig and producer; the cut is loin, not tenderloin.`,guest:`Here it means Spanish cured pork loin, sliced thin, with seasonings that vary by producer.`,kitchen:`Study the intact loin grain and distinguish it from both minced sausage and the smaller tenderloin.`,compare:`Lomo is loin; solomillo is tenderloin in Spanish.`,correction:``,sources:[{title:`Cinco Jotas: Cured Pork Loin`,url:`https://www.cincojotas.us/shop-online/cinco-jotas-acorn-fed-100x100-iberico-loin.html?___store=us&dir=asc&order=name`},{title:`Cinco Jotas: Traditional and natural loin recipes`,url:`https://www.cincojotas.com/en/product/4237/cinco-jotas-loin-traditional-recipe`}],reviewedOn:`2026-10-15`},{id:`cured-pancetta`,term:`Pancetta`,category:`cured`,aliases:[],ref:`c:fd_0071`,definition:`Italian cured pork belly, flat or rolled, usually unsmoked. Pork belly is cured with salt and seasoning, then sold in flat or rolled forms. The familiar style is unsmoked, but pancetta affumicata is smoked. Format, seasoning and intended cooking vary, so identify the actual product.`,guest:`It is Italian cured pork belly, usually unsmoked, used for savory richness.`,kitchen:`Check flat versus rolled format and the producer's cooking directions before deciding to dice, render or slice.`,compare:`Pancetta is belly; guanciale is jowl. Pancetta affumicata is a smoked version.`,correction:``,sources:[{title:`Levoni: Smoked Pancetta Cubes`,url:`https://www.levoni.it/en-us/products/sliced-deli-meats/incucina-range/smoked-pancetta-cubes`},{title:`USDA FSIS: Bacon and Food Safety`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-catfish/bacon-and-food-safety`}],reviewedOn:`2026-10-15`},{id:`cured-pastrami`,term:`Pastrami`,category:`cured`,aliases:[],ref:`c:fd_0072`,definition:`Cured, spice-coated smoked beef, cooked tender for deli service. Deli pastrami commonly starts with brisket or navel, a salt cure, a spice coating and smoke. Moist cooking then develops tenderness. Some makers steam; Katz's boils its smoked meat, then holds it on a steam table before slicing.`,guest:`It is cured and spice-coated beef with smoke flavor, cooked until tender for deli-style service.`,kitchen:`Identify the cut and house process; do not teach a drying step as the final source of tenderness.`,compare:`Corned beef shares a cure; pastrami adds its characteristic spice coating and smoke.`,correction:``,sources:[{title:`Katz's Delicatessen: Our Pastrami Process`,url:`https://katzsdelicatessen.com/pastrami`}],reviewedOn:`2026-10-15`},{id:`cured-pate`,term:`Pâté`,category:`cured`,aliases:[],ref:`c:fd_0073`,definition:`Seasoned meat preparation, smooth or coarse, often made with liver. Meat and fat are ground or blended with seasoning; liver is common but not required. Country styles may bake in a terrine, while some liver versions are cooked in a pan before blending. The recipe determines the texture and cooking method.`,guest:`It is a seasoned meat preparation, smooth or coarse, often made with liver and served with bread.`,kitchen:`Ask what meat and liver are used, and whether the texture is coarse or smooth; verify the kitchen's cooking procedure.`,compare:`Pâté is processed into a mixture; rillettes retain shreds of cooked meat.`,correction:``,sources:[{title:`D'Artagnan: Pâté and Terrine`,url:`https://www.dartagnan.com/pate-vs-terrine.html`},{title:`Antonio Carluccio Foundation: Chicken Liver Pâté`,url:`https://antoniocarlucciofoundation.org/recipe/chicken-liver-pate/`}],reviewedOn:`2026-10-15`},{id:`cured-prosciutto`,term:`Prosciutto`,category:`cured`,aliases:[`Prosciutto Crudo`,`Prosciutto di Parma`,`Parma Ham`,`San Daniele`],ref:`c:fd_0074`,definition:`Italian ham: dry-cured as crudo, or cooked as cotto. Prosciutto crudo is dry-cured pork leg; cotto is cooked ham. Named products have their own rules: Parma matures at least fourteen months before branding. Maturation and the producer shape the texture; Italian ham is not always sweeter or softer than Spanish ham.`,guest:`The crudo style here is Italian dry-cured ham, served in delicate slices.`,kitchen:`Identify the named style. For the familiar crudo board, thin slices let the texture and aroma show.`,compare:`Crudo is dry-cured; cotto is cooked. Parma is a particular protected crudo, not a synonym for every prosciutto.`,correction:``,sources:[{title:`Consorzio del Prosciutto di Parma: Production stages`,url:`https://www.prosciuttodiparma.com/le-fasi-della-lavorazione-del-prosciutto-di-parma/`},{title:`Levoni: Prosciutto Cotto`,url:`https://www.levoni.it/it/salumi/salumi-affettati/linea-classica/prosciutto-cotto-alta-qualita`}],reviewedOn:`2026-10-20`},{id:`cured-rillette`,term:`Rillettes`,category:`cured`,aliases:[`Rillette`],ref:`c:fd_0075`,definition:`Cooked meat or fish, shredded and mixed with fat into a rich spread. Traditional meat rillettes cook gently until tender, then are shredded and mixed with fat. Fish versions may combine cooked fish and butter. The defining texture is soft shreds rather than a smooth paste; the recipe determines the fat and method.`,guest:`It is cooked meat or fish made into a rich, textured spread, with visible shreds.`,kitchen:`Look for distinct soft shreds rather than a smooth paste; prepare the recipe's specified fat mixture.`,compare:`Rillettes retain shreds; pâté is ground or blended. Rillons retain larger pieces.`,correction:``,sources:[{title:`D'Artagnan: Rillettes vs. Rillons`,url:`https://www.dartagnan.com/rillettes-vs-rillons-recipes-and-uses.html`}],reviewedOn:`2026-10-15`},{id:`cured-speck`,term:`Speck`,category:`cured`,aliases:[`Speck Alto Adige`],ref:`c:fd_0076`,definition:`Boned pork leg cured with juniper, lightly cold smoked, then aged. Alto Adige sits on the Austrian border, and its ham borrows from both sides: dry cured like prosciutto, then cold smoked over beechwood. The leg is rubbed with salt, juniper, bay and pepper and aged about five months. Boned, flat and smoked, it eats firmer than prosciutto.`,guest:`This Alto Adige ham combines curing and aging with a gentle smoky aroma.`,kitchen:`Use the specific regional name before explaining the style; do not translate every German-language speck as identical ham.`,compare:`Parma crudo is unsmoked dry-cured ham; Alto Adige speck adds light cold smoke.`,correction:``,sources:[{title:`Speck Alto Adige Consortium: Production`,url:`https://www.speck.it/en/production`}],reviewedOn:`2026-10-15`},{id:`cured-tasso`,term:`Tasso`,category:`cured`,aliases:[`Tasso Ham`],ref:`c:fd_0077`,definition:`Cajun pork shoulder, cured, crusted in cayenne and garlic, smoked. Despite the common name tasso ham, this Cajun specialty is usually pork shoulder. It is cured, seasoned and smoked, contributing salt, smoke and spice. Kitchens use it in sauces, soups, beans, greens and grits, in pieces suited to the dish.`,guest:`It is spiced, smoked pork, commonly shoulder, used to give the dish a savory, peppery depth.`,kitchen:`Taste the dish before adding further seasoning; tasso contributes salt, smoke and spice as well as pork flavor.`,compare:`Tasso is a piece of meat; andouille is a sausage in a casing.`,correction:``,sources:[{title:`D'Artagnan: Cooking with Tasso`,url:`https://www.dartagnan.com/tasso-ham-recipes-and-uses.html`}],reviewedOn:`2026-10-15`},{id:`cured-bacon`,term:`Bacon`,category:`cured`,aliases:[],definition:`Cured pork belly, usually smoked, sold as a slab or sliced into strips. In the United States the word alone means the belly; bacon from another cut or animal must say so, as pork shoulder bacon or turkey bacon do. The cure is salt, usually with nitrite and often sugar and spice, rubbed on dry or pumped in, and the belly is then smoked or heat processed. Bacon sold with no other description is raw and must be cooked.`,guest:`Bacon is pork belly cured with salt and usually smoked, which gives it its smoky, salty flavor. On our Thanksgiving Day menu it went into the Rockefeller Gratin and was wrapped around the pork tenderloin, where its fat protects the lean meat in the oven.`,kitchen:`Rendered until its fat runs and the meat crisps, or wrapped around a lean cut so its fat protects the meat in the oven. Which bacon the kitchen buys, and how it was smoked, is a question for the chef.`,compare:`Pancetta is cured belly too, but usually unsmoked; salt pork is fattier and is not smoked, so it is not bacon.`,correction:``,sources:[{title:`USDA FSIS: Bacon and Food Safety`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-fish/bacon-and-food-safety`},{title:`Merriam-Webster: bacon`,url:`https://www.merriam-webster.com/dictionary/bacon`},{title:`Wiktionary: bacon`,url:`https://en.wiktionary.org/wiki/bacon`},{title:`Colonial Williamsburg: Smokehouses`,url:`https://research.colonialwilliamsburg.org/Foundation/journal/Winter04-05/smoke.cfm`},{title:`Dictionary.com: bacon`,url:`https://www.dictionary.com/browse/bacon`},{title:`Tasting Table: Salt Pork Vs Bacon`,url:`https://www.tastingtable.com/1665337/difference-between-salt-pork-vs-bacon`}],reviewedOn:`2026-11-27`,say:`BAY-kun`,background:`The word reached English in the Middle Ages through Old French, which took it from a Germanic word for the back, and at first it meant a side of pork or a ham rather than the strips of today. In colonial America the farms that kept pigs kept smokehouses too. Hogs were butchered in early winter, when the meat would not spoil before it was cured, then salted and hung over a slow fire so the bellies became bacon and the legs ham. Traditional smoking of bacon took many days. Mass production moved much of it to convection ovens, which the USDA notes can finish a batch in as little as six hours. Federal labeling keeps the plain name for cured belly.`,metAt:`Brennan's Thanksgiving Day 2026: Rockefeller Gratin and Bacon-Wrapped Pork Tenderloin`},{id:`cuts-ribeyecapakacalotte`,term:`Ribeye Cap`,category:`cuts`,aliases:[`(Ribeye) Cap (aka Calotte)`,`Calotte`,`Spinalis`,`Rib Cap`],ref:`c:fd_0086`,definition:`Heavily marbled crescent of beef that wraps the outside of a rib steak. A ribeye is the round eye plus a thin crescent curving over it. That crescent, the spinalis, has the most marbling on the steak and a loose, open grain, so it eats softer and richer than the eye. One animal yields very little, hence the price.`,guest:`It is the richly marbled outer muscle of the ribeye, prized for tenderness and beefy flavor.`,kitchen:`Identify the marbled cap muscle separately from exterior fat; it may be sold flat or portioned from a roll.`,compare:`Calotte is ribeye cap; coulotte is the cap of the top sirloin.`,correction:``,sources:[{title:`Beef. It's What's For Dinner: Ribeye Cap Steak`,url:`https://www.beefitswhatsfordinner.com/cuts/cut/2855/ribeye-cap-steak`}],reviewedOn:`2026-10-15`},{id:`cuts-cheek`,term:`Cheek`,category:`cuts`,aliases:[`Beef Cheek`,`Veal Cheek`,`Pork Cheek`],ref:`c:fd_0087`,definition:`Hard-working chewing muscle of the face, braised until spoon-soft. Cheek has substantial connective tissue that softens with slow, moist cooking. Beef, veal and pork cheeks differ in size, so one number of hours cannot define readiness. Assess tenderness and follow the recipe's cooking controls.`,guest:`It is a working muscle slowly cooked until tender, with a rich, silky texture.`,kitchen:`Connect a long gentle cook with a silky result; do not describe raw cheek as a quick-cooking tender steak.`,compare:`Tenderloin starts tender; cheek usually needs time for connective tissue to soften. The cut and size guide the method.`,correction:``,sources:[{title:`Meat & Livestock Australia: Beef Cheek`,url:`https://www.aussiebeefandlamb.me/meat-cuts/cuts-by-protein/beef/cheek`}],reviewedOn:`2026-10-20`},{id:`cuts-hangersteak`,term:`Hanger Steak`,category:`cuts`,aliases:[`Onglet`,`Butcher's Steak`,`Hanging Tender`],ref:`c:fd_0088`,definition:`One thick cut of beef from the diaphragm, loose-grained and deeply mineral. It hangs between the last rib and the loin, the thick central pillar of the diaphragm, one per animal. Bearing no weight, it stays fairly soft, but a coarse grain and rich blood supply give it a mineral flavor bolder than strip or filet. It is sliced across the grain.`,guest:`It is a flavorful, coarse-grained beef steak with a more pronounced bite than filet mignon.`,kitchen:`Locate the central membrane and grain direction during preparation; the cut suits quick dry-heat cooking.`,compare:`Hanger and skirt both come from the plate area but are different cuts.`,correction:``,sources:[{title:`Beef. It's What's For Dinner: Hanger Steak`,url:`https://www.beefitswhatsfordinner.com/cuts/cut/2826/hanger-steak`}],reviewedOn:`2026-10-15`},{id:`cuts-hamhock`,term:`Ham Hock`,category:`cuts`,aliases:[`Pork Hock`,`Pork Knuckle`],ref:`c:fd_0089`,definition:`Bony lower leg joint of a pig, usually smoked and simmered to flavor a pot. The hock is where the leg meets the foot: mostly skin, tendon and bone with a little meat, usually cured and smoked like ham. Simmered for hours, the skin and tendon melt into gelatin that gives body to beans, greens and soups, and the smoke and salt season the pot.`,guest:`It is the lower-leg hock, often cured or smoked and slowly cooked to enrich a dish.`,kitchen:`Check whether the kitchen uses fresh or cured/smoked hock before promising a smoky bean or greens dish.`,compare:`The hock is the lower-leg section above the foot; a trotter is the foot.`,correction:``,sources:[{title:`BC Cook Articulation Committee: Pork: Meat Cutting and Processing for Food Service`,url:`https://opentextbc.ca/meatcutting/chapter/pork/`},{title:`USDA FSIS: Hams and Food Safety`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/meat-catfish/hams-and-food-safety`}],reviewedOn:`2026-10-15`},{id:`cuts-ribeye`,term:`Ribeye`,category:`cuts`,aliases:[`Scotch Fillet`,`Cowboy Steak`,`Tomahawk`],ref:`c:fd_0090`,definition:`Upper rib beef steak, the most marbled of the classic steakhouse cuts. It comes from high on the back over the ribs, a muscle that does little work, so it is soft and threaded with fat that melts and bastes the meat from inside. It is fattier and bolder than a strip and far richer than a filet. Roasted whole, the same cut is prime rib.`,guest:`It is a rib-section steak with generous marbling and a rich beef flavor.`,kitchen:`Name the rib cut, marbling and any bone; verify the guest's requested finish.`,compare:`Ribeye emphasizes marbling; tenderloin emphasizes a fine, tender texture.`,correction:``,sources:[{title:`Beef. It's What's For Dinner: Ribeye Roll`,url:`https://www.beefitswhatsfordinner.com/cuts/cut/2783/ribeye-roll`},{title:`Beef. It's What's For Dinner: Loin Primal`,url:`https://www.beefitswhatsfordinner.com/cuts/cut/44453/loin-primal`}],reviewedOn:`2026-10-15`},{id:`cuts-shoulder`,term:`Shoulder`,category:`cuts`,aliases:[`Chuck`,`Pork Butt`,`Boston Butt`,`Picnic`],ref:`c:fd_0091`,definition:`Working region with muscles suited to different cooking methods. Shoulder has several working muscles with differing amounts of connective tissue and fat. Large pork shoulder cuts commonly suit braising, smoking or slow roasting. Selected beef shoulder muscles, including petite tender, can instead be cooked as tender steaks.`,guest:`For a slow-cooked shoulder dish, the long cooking makes the working muscle tender and rich.`,kitchen:`Use slow methods for a large pork shoulder; identify the precise beef shoulder subcut before choosing a technique.`,compare:`Shoulder is a region: braising cuts and tender steak muscles can both come from it.`,correction:``,sources:[{title:`National Pork Board: Pork Shoulder`,url:`https://new.pork.org/cuts/pork-shoulder/`},{title:`Beef. It's What's For Dinner: Shoulder Petite Tender`,url:`https://www.beefitswhatsfordinner.com/cuts/cut/2501/shoulder-petite-tender`}],reviewedOn:`2026-10-15`},{id:`cuts-shortrib`,term:`Short Rib`,category:`cuts`,aliases:[`Beef Short Ribs`,`Flanken`,`Jacob's Ladder`],ref:`c:fd_0092`,definition:`Rich beef cuts sold in thick or thin cross-cut pieces, often bone-in. Short ribs come from chuck, rib or plate sections, not the brisket itself. Thick pieces are commonly braised until their connective tissue softens; thin cross-cut strips can be grilled. The cut size and recipe determine the cooking method.`,guest:`It is a richly flavored rib cut; in this braised preparation, slow cooking makes it tender.`,kitchen:`Identify both where the cut came from and how it is cut; thick pieces and thin cross-cut strips need different plans.`,compare:`Short rib is not brisket. Short ribs can be taken from chuck, rib or plate sections.`,correction:``,sources:[{title:`Beef. It's What's For Dinner: Rib Short Ribs`,url:`https://www.beefitswhatsfordinner.com/cuts/cut/2878/rib-short-ribs`},{title:`Beef. It's What's For Dinner: Short Plate Primal`,url:`https://www.beefitswhatsfordinner.com/cuts/cut/2850/short-plate-primal`}],reviewedOn:`2026-10-15`},{id:`cuts-tenderloin`,term:`Tenderloin`,category:`cuts`,aliases:[`Filet Mignon`,`Beef Filet`,`Fillet`],ref:`c:fd_0093`,definition:`Small tapered muscle under the spine, the softest, mildest steak cut. A long, narrow muscle under the backbone that does almost no work, it has very little connective tissue and cuts like butter. The trade is flavor: lean, with little marbling, it tastes milder than a ribeye or strip, so it often comes with a sauce, a butter or a bacon wrap.`,guest:`Tenderloin is the long, slender muscle along the spine that does almost no work, so it is exceptionally tender, lean and mild; the beef tenderloin is the cut that gives filet mignon. On Thanksgiving Day we served it two ways: beef tenderloin roasted with herbs under a peppercorn sauce, and pork tenderloin wrapped in bacon with a Louisiana cane syrup glaze.`,kitchen:`Identify the species and exact portion: filet mignon and Chateaubriand are beef tenderloin forms, not every loin cut.`,compare:`Loin is a wider anatomical region; tenderloin is one specific muscle within it.`,correction:``,sources:[{title:`Beef. It's What's For Dinner: Loin Primal`,url:`https://www.beefitswhatsfordinner.com/cuts/cut/44453/loin-primal`},{title:`BC Cook Articulation Committee: Pork: Meat Cutting and Processing for Food Service`,url:`https://opentextbc.ca/meatcutting/chapter/pork/`},{title:`USDA FSIS: Smoking Meat and Poultry`,url:`https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/smoking-meat-and-poultry`},{title:`Wikipedia: Filet mignon`,url:`https://en.wikipedia.org/wiki/Filet_mignon`},{title:`Britannica: filet mignon`,url:`https://britannica.com/topic/filet-mignon`},{title:`Merriam-Webster: filet mignon`,url:`https://www.merriam-webster.com/dictionary/filet%20mignon`},{title:`Wikipedia: Chateaubriand (dish)`,url:`https://en.wikipedia.org/wiki/Chateaubriand_(dish)`},{title:`Britannica: chateaubriand`,url:`https://www.britannica.com/topic/chateaubriand`},{title:`National Pork Board: Pro Tips For Pork Cuts`,url:`https://pork.org/wp-content/uploads/2025/05/Pro-Tips-For-Pork-Cuts.pdf`},{title:`NDSU Extension: Now You're Cookin'! Lean Pork`,url:`https://www.ag.ndsu.edu/PUBLICATIONS/food-nutrition/now-serving-lean-pork`},{title:`Etymonline: filet`,url:`https://www.etymonline.com/word/filet`}],reviewedOn:`2026-10-15`,say:`TEN-der-loyn`,background:`The tenderloin is the psoas major, a long muscle along the inside of the spine that does little work, which is why it is so tender. Its familiar names are French, though the usage is tangled. Filet mignon means dainty fillet, yet in France the phrase usually names pork or veal tenderloin, and the French call the beef cut filet de boeuf; American English took filet mignon for beef steak, and dictionaries date its use in English to the early nineteenth century. The Chateaubriand, a thick cut from the beef tenderloin, is widely held to be named for the writer and statesman François René de Chateaubriand (1768 to 1848), whose chef is said to have created it early in the nineteenth century. Pork has its own tenderloin, smaller and very lean, safe at 145 °F after a three minute rest.`,metAt:`Brennan's Thanksgiving Day 2026: Herb Roasted Beef Tenderloin and Bacon-Wrapped Pork Tenderloin`},{id:`cuts-veal`,term:`Veal`,category:`cuts`,aliases:[],definition:`The meat of calves, as against the beef of older cattle. Its lean is pale: the USDA’s own purchasing specification tells veal from the older calf class mainly by the color of the lean. In the United States most veal comes from young male dairy calves, and the USDA describes a typical veal calf as raised to about 16 to 18 weeks and up to 450 pounds. Cutlets and scaloppine are usually cut from the leg, most often the top round, and pounded thin before cooking.`,guest:`Veal is the meat of a young calf, paler and leaner than beef, and a meat New Orleans Creole cooks have long used for grillades. On our Thanksgiving menu it was pounded thin and simmered in gravy for the Veal Grillades.`,kitchen:`Cutlets for pounding come from the leg, usually the top round, sliced across the grain and pounded thin. Which cut the house used, and how it was braised, is the chef’s to say.`,compare:`Beef is its nearest neighbor: the same animal, older and darker in the lean. Grillades are made from either, and beef round is the common stand in, so ask the kitchen before you promise a guest veal.`,correction:``,sources:[{title:`Wikipedia: Veal`,url:`https://en.wikipedia.org/wiki/Veal`},{title:`American Veal Association: What Is Veal?`,url:`https://www.americanveal.com/about-veal`},{title:`USDA FSIS: Veal from Farm to Table (archived)`,url:`https://webarchive.library.unt.edu/web/20120915115241/http:/www.fsis.usda.gov/PDF/Veal_from_Farm_to_Table.pdf`},{title:`USDA FSIS: Petition to Define Veal`,url:`https://www.fsis.usda.gov/federal-register/petitions/request-fsis-define-veal-regulations`},{title:`Food Safety News: FSIS Does Not See Need for Changing Veal Terminology`,url:`https://www.foodsafetynews.com/2020/10/fsis-does-not-see-need-for-changing-veal-terminology/`},{title:`USDA AMS: IMPS 300, Fresh Veal and Calf`,url:`https://www.ams.usda.gov/sites/default/files/media/IMPS_300_Fresh_Veal_%26_Calf%5B1%5D.pdf`},{title:`Lobel’s: Cuts of Veal`,url:`https://lobels.com/cuts-of-veal`},{title:`ckbk: The Picayune’s Creole Cook Book, Veal`,url:`https://app.ckbk.com/section/thep19270c06s001ss004/veal`},{title:`ckbk: The Picayune’s Creole Cook Book, Grillades Breaded`,url:`https://app.ckbk.com/recipe/thep19270c06s001ss003r014/grillades-breaded`},{title:`Wikipedia: Grillades`,url:`https://en.wikipedia.org/wiki/Grillades`}],reviewedOn:`2026-11-27`,say:`VEEL`,background:`Veal is treated as a delicacy in French and Italian cooking, in dishes such as escalopes and paupiettes. Veal farming spread from Europe to the United States more than a century ago, the American Veal Association says, and it rests on the dairy herd, since most veal comes from male dairy calves, which give no milk. The USDA has no codified definition of veal, and in 2020 it declined a petition from the American Veal Association that sought one based on carcass weight. In New Orleans the Picayune’s Creole Cook Book gave veal a section of its own, and its breaded grillades began with a round of veal, the cut that the city’s grillades have long shared with beef round.`,metAt:`Brennan's Thanksgiving Day 2026: Veal Grillades`},{id:`fish-arcticchar`,term:`Arctic Char`,category:`fish`,aliases:[`Char`],ref:`c:fd_0108`,definition:`A cold-water fish in the salmon family. Populations include freshwater residents and fish that move between fresh and salt water; culinary flesh is often pink and delicately flaked.`,guest:`Arctic char is a cold-water salmon relative with a delicate flake.`,kitchen:`Confirm whether the portion is skin-on and how it is prepared. Use the supplier’s actual origin rather than assuming Iceland or Canada.`,compare:`Related to salmon and trout, but not a guaranteed midpoint between them in fat or flavor.`,correction:``,sources:[{title:`newsrelease.adfg.alaska.gov`,url:`https://newsrelease.adfg.alaska.gov/index.cfm?adfg=arcticchar.main`},{title:`adfg.alaska.gov`,url:`https://www.adfg.alaska.gov/static/education/wns/arctic_char.pdf`}],reviewedOn:`2026-10-15`},{id:`fish-crawfish`,term:`Crawfish`,category:`fish`,aliases:[`Crayfish`,`Crawdads`,`Mudbugs`],ref:`c:fd_0109`,definition:`A freshwater crustacean; the tail provides the principal commercial meat. Whole crawfish and peeled tail meat are different service forms.`,guest:`Crawfish has small, tender tail meat with a sweet shellfish flavor.`,kitchen:`Know whether the dish uses peeled tails or whole crawfish and confirm sourcing. The rich head material called fat is largely digestive-gland tissue.`,compare:`Crawfish is a crustacean, not a small finfish. A sauce can contain additional shellfish or dairy.`,correction:``,sources:[{title:`LSU AgCenter`,url:`https://www.lsuagcenter.com/~/media/system/8/3/a/a/83aa19ada7f446f2b00482956fd42a06/chapter10.pdf`}],reviewedOn:`2026-10-15`},{id:`fish-skatefish`,term:`Skate`,category:`fish`,aliases:[`Skate Fish`,`Skate Wing`,`Raie`],ref:`c:fd_0110`,definition:`A cartilaginous fish whose wing is a familiar restaurant cut. The wing’s muscle forms strands over a sheet of cartilage.`,guest:`Skate wing is a delicate, mildly sweet fish with flesh that separates into strands.`,kitchen:`Learn whether the kitchen serves the wing on or off its cartilage; explain the presentation if needed.`,compare:`Skate is a fish, not a bivalve or crustacean. Wings are the best-known cut, but cheeks are also used.`,correction:``,sources:[{title:`seafish.org`,url:`https://www.seafish.org/about-us/news-blogs/thornback-ray-from-north-west-english-waters-to-your-plate/`}],reviewedOn:`2026-10-15`},{id:`fish-flounder`,term:`Flounder`,category:`fish`,aliases:[`Fluke`,`Summer Flounder`],ref:`c:fd_0111`,definition:`A name used for several flatfish. Fillets are commonly lean, delicate and mild; summer flounder is also called fluke.`,guest:`Flounder is a delicate white fish with a fine, mild flavor.`,kitchen:`Confirm the species and cut; a thin fillet needs gentler handling than a thick loin.`,compare:`Halibut and turbot are also flatfish, but the market names are not interchangeable.`,correction:``,sources:[{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/summer-flounder`}],reviewedOn:`2026-10-15`},{id:`fish-grouper`,term:`Grouper`,category:`fish`,aliases:[],ref:`c:fd_0112`,definition:`A market name for several fish species. Red grouper, for example, has mild flesh with a firm, moist flake.`,guest:`Grouper is a firm white fish with a mild flavor and substantial flakes.`,kitchen:`Learn the actual species, origin and preparation; do not infer a local catch from the word grouper.`,compare:`Usually more substantial in texture than a thin flounder fillet; individual fish and cooking still matter.`,correction:``,sources:[{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/red-grouper`},{title:`myfwc.com`,url:`https://myfwc.com/research/saltwater/status-and-trends/finfish/`}],reviewedOn:`2026-10-15`},{id:`fish-halibut`,term:`Halibut`,category:`fish`,aliases:[],ref:`c:fd_0113`,definition:`A large flatfish sold in substantial portions. Pacific halibut has a mild, gently sweet flavor and firm, flaky flesh.`,guest:`Halibut has a mild, gently sweet flavor with a firm, generous flake.`,kitchen:`Protect the texture with controlled cooking; follow the kitchen’s approved endpoint rather than teaching undercooking as the solution to dryness.`,compare:`A thick halibut portion behaves differently from a thin flounder fillet. Both are flatfish.`,correction:``,sources:[{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/pacific-halibut`},{title:`U.S. Food and Drug Administration`,url:`https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-fresh-and-frozen-seafood-safely`}],reviewedOn:`2026-10-15`},{id:`fish-mussels`,term:`Mussels`,category:`fish`,aliases:[`Moules`],ref:`c:fd_0114`,definition:`Bivalve mollusks with hinged shells. Blue mussels have elongated dark shells and tender meat; they may be farmed on ropes or on the seabed.`,guest:`Mussels are tender shellfish with a gently sweet flavor.`,kitchen:`Follow receiving, storage and preparation procedures. Discard shells that remain closed after cooking, following FDA guidance.`,compare:`Mussels are different from clams and oysters. Shell shape and meat texture vary between these groups.`,correction:``,sources:[{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/blue-mussel`},{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/feature-story/fall-love-new-seafood-seafood-month`},{title:`U.S. Food and Drug Administration`,url:`https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-fresh-and-frozen-seafood-safely`}],reviewedOn:`2026-10-15`},{id:`fish-oysters`,term:`Oysters`,category:`fish`,aliases:[],ref:`c:fd_0115`,definition:`Bivalve shellfish whose flavor can range from sweet to briny. The named variety, growing area and preparation help describe what is served.`,guest:`Gulf oysters are the eastern oyster, the same species that grows along the Atlantic coast, and they can taste sweet, briny or a little of both, depending on where they grew. They go into our seafood gumbo, and on the Thanksgiving Day menu they were baked into the Rockefeller Gratin.`,kitchen:`Learn the day’s oyster names and whether each is raw, grilled, baked or otherwise cooked. Half shell describes presentation, not a guarantee of rawness.`,compare:`A coast alone does not guarantee one flavor. Mussels and clams are different bivalves.`,correction:``,sources:[{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/eastern-oyster/seafood`},{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/insight/oyster-recipes`},{title:`64 Parishes: Duba, the Plaquemines oyster`,url:`https://64parishes.org/duba-plaquemines-oyster`},{title:`Louisiana Folklife: Croatians in Southeastern Louisiana`,url:`https://louisianafolklife.org/LT/Articles_Essays/main_misc_croatians_s_la.html`},{title:`64 Parishes: Antoine's Restaurant`,url:`https://64parishes.org/entry/antoines-restaurant`}],reviewedOn:`2026-10-15`,say:`OY-sterz`,background:`The oyster of the Gulf is the eastern oyster, Crassostrea virginica, the same species that grows along the Atlantic coast, and it thrives in estuaries where river water meets the sea. In Louisiana the trade owes much to Croatian immigrants. Through the nineteenth century men from villages on the Dalmatian coast of the Adriatic, such as Duba, settled in Plaquemines Parish fishing towns like Olga, Empire and Buras, and they are widely credited with building the state’s commercial oyster industry. New Orleans cooks took the oyster in every direction: raw on the half shell, fried, simmered in gumbo and baked, as in oysters Rockefeller, created at Antoine’s in the French Quarter in 1899 by most accounts.`,metAt:`Brennan's Thanksgiving Day 2026: Rockefeller Gratin and Seafood Gumbo`},{id:`fish-roe`,term:`Roe`,category:`fish`,aliases:[],ref:`c:fd_0116`,definition:`Fish eggs, sold in different forms including fresh, salted, pasteurised, cooked and smoked products. The species and processing affect flavor and texture.`,guest:`Roe means fish eggs; it adds a distinctive texture, and cured varieties bring a savory, salty accent.`,kitchen:`Check species, preservation and package instructions before describing the product as raw or cured.`,compare:`Classical caviar is sturgeon roe; other fish eggs should be identified by species.`,correction:``,sources:[{title:`Food and Agriculture Organization`,url:`https://www.fao.org/gsfaonline/foods/details.html?d-3586470-o=1&d-3586470-s=3&d-49489-o=2&d-49489-s=1&id=162&print=true`}],reviewedOn:`2026-10-15`},{id:`fish-salmon`,term:`Salmon`,category:`fish`,aliases:[],ref:`c:fd_0117`,definition:`A group of fish valued for their pink-to-orange flesh and rich flavor. Species, farming or fishing method, feed and preparation affect the final product.`,guest:`Salmon has a rich flavor and a tender flake.`,kitchen:`Name the actual species and source when known. Do not claim every salmon has the same richness or life history.`,compare:`Trout and Arctic char are relatives, not synonyms. A species name is more useful than promising a fixed fat ranking.`,correction:``,sources:[{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/atlantic-salmon`}],reviewedOn:`2026-10-15`},{id:`fish-scallops`,term:`Scallops`,category:`fish`,aliases:[],ref:`c:fd_0118`,definition:`Bivalve shellfish; the pale round adductor muscle is the part commonly served in the United States. It has a sweet flavor and can be seared or gently cooked.`,guest:`Bay scallops are the small, sweet scallops of shallow bays, more tender than the larger sea scallops. On our Thanksgiving Day crudo they were served raw, so their natural sweetness came through, dressed with Meyer lemon, black truffle and radish.`,kitchen:`Control cooking rather than equating fully cooked with rubbery. FDA describes properly cooked scallop flesh as firm, pearly and opaque.`,compare:`Bay and sea scallops differ in typical size; king-trumpet mushroom scallops are a shaped vegetable preparation.`,correction:``,sources:[{title:`U.S. Food and Drug Administration`,url:`https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-fresh-and-frozen-seafood-safely`},{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/atlantic-sea-scallop`},{title:`New York Sea Grant: the bay scallop`,url:`https://seagrant.sunysb.edu/articles/r/23850`},{title:`Northeastern Naturalist (2026): bay scallops of New York's Peconic Bays`,url:`https://s3.amazonaws.com/assets.cce.cornell.edu/attachments/78564/2026.Tettelbach_et_al.Northeastern_Naturalist.pdf`},{title:`NOAA Fisheries Scientific Publications Office: The Bay Scallop, Argopecten irradians, Massachusetts through North Carolina`,url:`https://spo.nmfs.noaa.gov/content/bay-scallop-argopecten-irradians-massachusetts-through-north-carolina-its-biology-and`},{title:`New York State DEC: Bay scallop species assessment`,url:`https://extapps.dec.ny.gov/fs/programs/dfw/SWAP2025/Marine%20Invertebrates/Bay%20scallop.pdf`}],reviewedOn:`2026-10-15`,say:`SKAL-ups`,background:`The bay scallop, Argopecten irradians, lives in the eelgrass of shallow bays and sounds on the Atlantic coast and around the Gulf of Mexico, and it is short lived: it seldom lives two years, and in one study of New York's Peconic Bays fewer than one in a hundred harvested scallops had reached that age. From the 1870s to the mid 1980s its fishery from Massachusetts to North Carolina mattered both to the local economy and to the life of the towns that worked it. The scallop depends on its eelgrass, and when the eelgrass died off in the 1930s and again in the 1980s, scallop numbers and harvests fell hard. What reaches the plate is the adductor, the round muscle that closes the shell. Served on its own and raw, it is exempt under the FDA Food Code from the parasite freezing most raw fish needs.`,metAt:`Brennan's Thanksgiving Day 2026: Bay Scallop Crudo`},{id:`fish-snapper`,term:`Snapper`,category:`fish`,aliases:[`Red Snapper`],ref:`c:fd_0119`,definition:`A name covering multiple fish species, including red, gray and yellowtail snappers. Red snapper is one species, not the definition of every snapper.`,guest:`Snapper is a white fish with a mild flavor; there are several varieties.`,kitchen:`Confirm species and source. If served whole, explain that the fish includes its skeleton and small bones.`,compare:`Not every snapper has red skin. Some market names containing snapper can refer to unrelated fish, so check the label.`,correction:``,sources:[{title:`myfwc.com`,url:`https://myfwc.com/research/saltwater/status-and-trends/finfish/`},{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/vermilion-snapper/resources`}],reviewedOn:`2026-10-15`},{id:`fish-sturgeon`,term:`Sturgeon`,category:`fish`,aliases:[],ref:`c:fd_0120`,definition:`A group of fish with a largely cartilaginous skeleton and rows of bony plates called scutes. They are used for meat and, in appropriate species and products, caviar.`,guest:`Sturgeon is a substantial fish with a firm texture.`,kitchen:`Check species, legal source and preparation from the product record; meat and roe are separate products.`,compare:`Not a salmon despite sometimes being served smoked; its roe is the source of classical caviar.`,correction:``,sources:[{title:`dfw.state.or.us`,url:`https://www.dfw.state.or.us/fish/oscrp/cri/white_sturgeon_mitigation_and_restoration.asp`},{title:`Food and Agriculture Organization`,url:`https://www.fao.org/gsfaonline/foods/details.html?d-3586470-o=1&d-3586470-s=3&d-49489-o=2&d-49489-s=1&id=162&print=true`}],reviewedOn:`2026-10-15`},{id:`fish-tilefish`,term:`Tilefish`,category:`fish`,aliases:[`Golden Tilefish`],ref:`c:fd_0121`,definition:`A name used for several fish, including golden and blueline tilefish. These have mild, sweet white flesh with a firm but tender texture; confirm the species being served.`,guest:`Tilefish has mild, sweet white flesh and a firm, tender texture.`,kitchen:`Use the actual species and catch area on the supplier record; do not assume every tilefish comes from the same fishery.`,compare:`Golden and blueline tilefish are different species. A lobster-like flavor comparison does not make either shellfish or prove a single dietary cause.`,correction:``,sources:[{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/golden-tilefish`},{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/blueline-tilefish`}],reviewedOn:`2026-10-15`},{id:`fish-trout`,term:`Trout`,category:`fish`,aliases:[],ref:`c:fd_0122`,definition:`A name used for several salmon-family fish. Rainbow trout is widely used in cooking; steelhead is the sea-going form of the same species.`,guest:`Trout has a delicate flake; the flavor and richness depend on the variety and preparation.`,kitchen:`Learn which trout is on the menu, whether it is served whole or filleted, and whether the skin is included.`,compare:`Steelhead and rainbow trout are the same species with different life histories; not every fish called sea trout belongs to this group.`,correction:``,sources:[{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/steelhead`}],reviewedOn:`2026-10-15`},{id:`fish-turbot`,term:`Turbot`,category:`fish`,aliases:[],ref:`c:fd_0123`,definition:`A rounded European flatfish, sold wild-caught or farmed, prized for firm white flesh. It is different from Greenland turbot, also called Greenland halibut.`,guest:`Turbot is a firm, delicate flatfish.`,kitchen:`Confirm the exact fish. The similar market name Greenland turbot identifies a different species and texture.`,compare:`Turbot, halibut and flounder are distinct market choices; price does not define their identity or quality.`,correction:``,sources:[{title:`Food and Agriculture Organization`,url:`https://www.fao.org/fishery/docs/DOCUMENT/aquaculture/CulturedSpecies/file/en/en_turbot.htm`},{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/greenland-turbot`}],reviewedOn:`2026-10-15`},{id:`fish-wreckfish`,term:`Wreckfish`,category:`fish`,aliases:[`Stone Bass`],ref:`c:fd_0124`,definition:`A large fish with mild white flesh and substantial flakes. The United States has a fishery near the Charleston Bump, but the species has a much wider distribution.`,guest:`Wreckfish is a mild white fish with a firm, substantial flake.`,kitchen:`Confirm the catch area and supplier before describing it as local. Match cooking to the thickness of the portion.`,compare:`Its texture is often compared with grouper, but it is a different fish.`,correction:``,sources:[{title:`NOAA Fisheries`,url:`https://www.fisheries.noaa.gov/species/wreckfish`}],reviewedOn:`2026-10-15`},{id:`fish-gulfshrimp`,term:`Gulf Shrimp`,category:`fish`,aliases:[`Louisiana shrimp`,`White shrimp`,`Brown shrimp`],definition:`Wild shrimp caught in the Gulf, almost all of them one of three species: brown, white and pink. Brown and white shrimp come mainly from Louisiana and Texas waters; pink shrimp mostly from the west coast of Florida. In Louisiana’s inside waters brown shrimp are the catch of the spring season and white shrimp of the fall season. Species, size and where they were landed are on the supplier’s record.`,guest:`Gulf shrimp are wild shrimp from the bays and coastal waters of Louisiana and its neighbors, with a sweet, briny bite. They go into our seafood gumbo, and on the Thanksgiving Day menu they also went into the shrimp sauce piquante and the BBQ shrimp stuffing. Where tonight’s shrimp were landed is the kitchen’s to say.`,kitchen:`Peeled, often deveined, and added near the end of a dish so they stay tender; the shells can go into the stock.`,compare:`Brown and white shrimp are different species with different Louisiana seasons, brown in spring and early summer and white in the fall; the label, not the shell color, says which it is.`,correction:``,sources:[{title:`NOAA Fisheries: White Shrimp`,url:`https://www.fisheries.noaa.gov/species/white-shrimp`},{title:`NOAA Fisheries: Brown Shrimp`,url:`https://www.fisheries.noaa.gov/species/brown-shrimp`},{title:`NOAA Fisheries: Pink Shrimp`,url:`https://www.fisheries.noaa.gov/species/pink-shrimp`},{title:`Louisiana Department of Wildlife and Fisheries: Shrimp Season`,url:`https://wlf.louisiana.gov/page/shrimp-season`},{title:`64 Parishes: Shrimp Drying in Louisiana`,url:`https://64parishes.org/shrimp-drying-in-louisiana`},{title:`64 Parishes: Filipinos`,url:`https://64parishes.org/entry/filipinos`},{title:`WWNO: How a New Orleans immigrant created a global dried shrimp business`,url:`https://www.wwno.org/podcast/tripod-new-orleans-at-300/2015-10-08/the-little-company-that-could-how-a-new-orleans-immigrant-created-a-global-dried-shrimp-business`},{title:`National Park Service, Jean Lafitte: Ranger Recipes, Seafood`,url:`https://www.nps.gov/jela/learn/historyculture/ranger-recipes-seafood.htm`},{title:`Wikipedia: Manila Village`,url:`https://en.wikipedia.org/wiki/Manila_Village`}],reviewedOn:`2026-11-27`,say:`GULF SHRIMP`,background:`NOAA counts white shrimp as the first commercially important shrimp in the United States, fished as far back as 1709, and reports that almost all the white and brown shrimp the country harvests come from the Gulf, mainly off Louisiana and Texas. Part of the Louisiana catch was once dried in the sun. Chinese fishermen are credited with bringing commercial shrimp drying to Louisiana in the 1870s, spreading boiled shrimp across broad wooden platforms built on stilts above the marsh. Manila Village, which Filipino settlers built in Barataria Bay in the late 1800s, was the largest of those platform villages until Hurricane Betsy destroyed it in 1965. Louisiana has generally set its inshore seasons by species, brown shrimp from about May into July and white shrimp from about mid August into December.`,metAt:`Brennan's Thanksgiving Day 2026: Seafood Gumbo, Shrimp Sauce Piquante and Titus’ BBQ Shrimp Stuffing`},{id:`fish-bluecrab`,term:`Blue Crab`,category:`fish`,aliases:[`Atlantic blue crab`,`Callinectes sapidus`],definition:`A swimming crab of the Atlantic coast of the Americas and the Gulf, and the crab of Louisiana’s crabmeat. Picked meat is sold by grade: jumbo lump, the large white pieces from the two muscles that drive the swimming legs; lump, smaller and broken white pieces; and claw meat, darker and stronger in flavor. Grade names and piece sizes vary from packer to packer, so the packer’s description matters. A blue crab taken just after it molts is sold whole as a soft-shell crab.`,guest:`Blue crab is the sweet, delicate crab of the Gulf and the Atlantic coast; its Latin name means beautiful savory swimmer. In our seafood gumbo it adds a gentle sweetness against the smoky andouille and the brine of the oysters.`,kitchen:`Bought as picked meat by grade or as live crabs; large white lumps are folded in gently near the end so they stay whole. Which grade goes into the gumbo is the kitchen’s to say.`,compare:`Jumbo lump is the large white meat of the swimming leg muscles, kept whole for presentation; claw meat is darker and stronger, and suits soups and bisques.`,correction:``,sources:[{title:`NOAA Fisheries: Blue Crab`,url:`https://www.fisheries.noaa.gov/species/blue-crab`},{title:`Maryland Manual: Maryland State Crustacean, Blue Crab`,url:`https://msa.maryland.gov/msa/mdmanual/01glance/html/symbols/crab.html`},{title:`America’s Test Kitchen: Crabmeat 101`,url:`https://www.americastestkitchen.com/how_tos/5880-crabmeat-101`},{title:`Louisiana Department of Wildlife and Fisheries: 2014 Blue Crab Fishery Management Plan`,url:`https://www.wlf.louisiana.gov/assets/Resources/Publications/Marine_Fishery_Management_Plans/2014_Blue_Crab_Fishery_Management_Plan.pdf`},{title:`LSU AgCenter: Crab shedders persevere as Louisiana soft-shell crab industry shrinks`,url:`https://www.lsuagcenter.com/profiles/lbenedict/articles/page1543874830191`},{title:`Louisiana Sea Grant: A Declining Delicacy`,url:`https://www.laseagrant.org/?p=9073`},{title:`PeerJ: population genetics of the blue crab Callinectes sapidus`,url:`https://peerj.com/articles/7827`},{title:`Tasting Table: Here’s How The Grades Of Crab Meat Are Determined`,url:`https://www.tastingtable.com/1006248/heres-how-the-grades-of-crab-meat-are-determined`}],reviewedOn:`2026-11-27`,say:`BLOO KRAB`,background:`The blue crab was described and named in 1896 as Callinectes sapidus, from Greek words for beautiful and swimmer and the Latin for savory, so its name reads beautiful savory swimmer. It is native to the Atlantic coast of the Americas from Nova Scotia to northern Argentina, the Gulf included, and Louisiana’s crabbers have long worked its estuaries: the state’s 2014 management plan called Louisiana’s the largest blue crab fishery in the country, landing more than half the blue crab taken in the Gulf. Crabs grow by molting. Louisiana shedders hold peeler crabs in tanks until they slip their old shells and sell them as soft-shell crabs, a trade that has since shrunk.`,metAt:`Brennan's Thanksgiving Day 2026: Seafood Gumbo`},{id:`fish-redfish`,term:`Redfish`,category:`fish`,aliases:[`Red drum`,`Sciaenops ocellatus`,`Red`],definition:`Redfish is the Gulf and Atlantic name for the red drum, Sciaenops ocellatus, a fish of the drum family. Its mark is one large black spot near the base of the tail, sometimes several, which may draw a predator to the tail rather than the head; the Latin ocellatus refers to these eye like spots. It is common from Chesapeake Bay down the Atlantic coast and along the whole American Gulf coast into Mexico. On the Thanksgiving Day menu it was the fish of the Redfish Meunière.`,guest:`Redfish is the red drum, a Gulf Coast fish you know by the black spot near its tail. In New Orleans it is remembered for the blackened redfish craze of the 1980s. On Thanksgiving Day ours was cooked meunière, with brown butter, lemon and capers.`,kitchen:`Louisiana closed its commercial red drum fishery in 1988, and redfish farming, centered in Texas, grew up to supply restaurants. Where the house redfish came from, and how it was cut, was the kitchen’s to say at lineup.`,compare:`Black drum is its nearest neighbor and its cousin in the drum family: a black drum has whisker like barbels under its chin and no tail spot, and a deeper, high backed body, while a redfish is longer, has no barbels and carries the spot at its tail.`,correction:``,sources:[{title:`Texas Parks and Wildlife: Red Drum (Sciaenops ocellatus)`,url:`https://tpwd.texas.gov/huntwild/wild/species/reddrum`},{title:`Florida Museum: Red Drum`,url:`https://www.floridamuseum.ufl.edu/discover-fish/species-profiles/red-drum/`},{title:`Wikipedia: Red drum`,url:`https://en.wikipedia.org/wiki/Red_drum`},{title:`Louisiana Department of Wildlife and Fisheries: Red Drum`,url:`https://www.wlf.louisiana.gov/page/hot-topic-red-drum`},{title:`Louisiana State Legislature: RS 56:325.3`,url:`https://legis.la.gov/legis/Law.aspx?d=105209`},{title:`Smithsonian Magazine: Can the Redfish, a Gulf Coast Culinary Icon, Be Brought Back From the Brink?`,url:`https://www.smithsonianmag.com/science-nature/can-redfish-gulf-coast-culinary-icon-brought-back-from-brink-180986803/`},{title:`Alabama Aquaculture: How a Gulf Coast Chef Invented the Blackened Seafood Technique`,url:`https://aqua.alabama.gov/articles/story/history-of-blackened-seafood.html`},{title:`Food Republic: Why The Introduction Of Blackened Redfish Caused A Fishing Ban`,url:`https://www.foodrepublic.com/1631780/origin-why-redfish-banned/`},{title:`64 Parishes: Paul Prudhomme`,url:`https://64parishes.org/entry/paul-prudhomme`},{title:`Tasting Table: The Cajun Dish That Was So Trendy It Resulted In A Fishing Ban`,url:`https://tastingtable.com/1208474/the-cajun-dish-that-was-so-trendy-it-resulted-in-a-fishing-ban`},{title:`Texas Parks and Wildlife: Black Drum (Pogonias cromis)`,url:`https://tpwd.texas.gov/huntwild/wild/species/blackdrum`},{title:`Saveur: Blackened Redfish`,url:`https://www.saveur.com/article/Recipes/Blackened-Redfish`},{title:`Food52: Change the Way You Cook, the Blackening Technique`,url:`https://food52.com/blog/21243-change-the-way-you-cook-blackening-technique`},{title:`NOAA Fisheries: Gulf of Mexico Red Drum Historical Amendments and Rulemaking 1988 to 2002`,url:`https://www.fisheries.noaa.gov/action/gulf-mexico-red-drum-historical-amendments-and-rulemaking-1988-2002`},{title:`Agricultural Marketing Resource Center: Red Drum, or Redfish`,url:`https://www.agmrc.org/commodities-products/aquaculture/aquaculture-fin-fish-species/red-drum-or-redfish`},{title:`Mississippi State University Extension: Red Drum newsletter 2024`,url:`https://extension.msstate.edu/sites/default/files/newsletter/Newsletter-Red-Drum-2024.pdf`}],reviewedOn:`2026-11-27`,say:`RED-fish`,background:`In New Orleans redfish went national through one dish. Paul Prudhomme (1940 to 2015) opened K-Paul’s Louisiana Kitchen on Chartres Street in 1979, and there, in 1980, he began to serve blackened redfish: fillets dipped in butter, coated in a mix of paprika, ground peppers and dried herbs and seared in a very hot iron skillet until a dark crust formed. The dish became a national craze, demand for Gulf redfish soared and the species was badly overfished. Federal regulators closed commercial harvest in the Gulf’s federal waters in 1987, and Louisiana made red drum a recreational fishery only in 1988. Redfish farming, centered in Texas, grew up to supply restaurants.`,metAt:`Brennan's Thanksgiving Day 2026: Redfish Meunière`},{id:`dairy-chapelhillcreamery`,term:`Chapel Hill Creamery`,category:`dairy`,aliases:[],definition:`A cheesemaker in Chapel Hill, North Carolina, producing fresh and aged cow’s-milk cheeses. Its dairy collaborative includes both Jersey and Brown Swiss milk.`,guest:`Chapel Hill Creamery is a North Carolina maker of cow’s-milk cheeses, from fresh styles to aged wheels.`,kitchen:`Learn the exact wheel or tub name before service. Examples on the maker’s list include Carolina Moon, Hickory Grove and Calvander; verify the actual product’s milk treatment, ingredients and rind.`,compare:`The maker’s name is not a cheese style. Do not assume every cheese uses only the creamery’s own Jersey milk.`,correction:``,sources:[{title:`chapelhillcreamery.com`,url:`https://www.chapelhillcreamery.com/about`},{title:`chapelhillcreamery.com`,url:`https://www.chapelhillcreamery.com/our-cheeses`}],reviewedOn:`2026-10-15`},{id:`dairy-sweetgrassdairy`,term:`Sweet Grass Dairy`,category:`dairy`,aliases:[],definition:`A family-owned cheesemaker based in Thomasville, Georgia, known for cow’s-milk cheeses. Its range includes soft-ripened Green Hill, Asher Blue and Thomasville Tomme.`,guest:`Sweet Grass Dairy is a Georgia cheesemaker known for cow’s-milk cheeses in several styles.`,kitchen:`Read the current specification sheet for the named cheese. Green Hill is soft-ripened; Asher Blue is a blue cheese; they should not share one generic texture description.`,compare:`A producer is not a milk species or style. The current range contains both raw-milk and pasteurised products, so check the exact cheese.`,correction:``,sources:[{title:`sweetgrassdairy.com`,url:`https://sweetgrassdairy.com/`},{title:`sweetgrassdairy.com`,url:`https://sweetgrassdairy.com/pages/cheese`},{title:`sweetgrassdairy.com`,url:`https://sweetgrassdairy.com/pages/industry`}],reviewedOn:`2026-10-15`},{id:`dairy-spinningspidercreamery`,term:`Spinning Spider Creamery`,category:`dairy`,aliases:[],definition:`A family artisan goat dairy in Marshall, in North Carolina’s Madison County. It makes fresh, bloomy and aged goat cheeses.`,guest:`Spinning Spider is a mountain goat-dairy cheesemaker in North Carolina.`,kitchen:`Name the cheese as well as the maker. Its Bailey Mountain Tomme is an aged Alpine-style cheese; a fresh chèvre has a quite different texture. Confirm the current product specification.`,compare:`Do not describe every goat cheese as fresh or chalky. The same milk can become several cheese styles.`,correction:``,sources:[{title:`spinningspidercreamery.com`,url:`https://www.spinningspidercreamery.com/`},{title:`spinningspidercreamery.com`,url:`https://www.spinningspidercreamery.com/cheese/aged-cheese/`}],reviewedOn:`2026-10-15`},{id:`dairy-sequatchiecovecreamery`,term:`Sequatchie Cove Creamery`,category:`dairy`,aliases:[],definition:`An artisan cow’s-milk cheesemaker in Sequatchie, Tennessee, working with local dairy farmers and drawing on Savoie cheesemaking traditions.`,guest:`Sequatchie Cove Creamery makes artisan cow’s-milk cheeses in Tennessee.`,kitchen:`Check the named cheese: its range includes Shakerag, Cumberland, Coppinger and Walden. Use the current label for ingredients, milk treatment and rind information.`,compare:`Sequatchie Cove Creamery is a maker; Singing Brook is a different maker’s sheep’s-milk cheese.`,correction:``,sources:[{title:`sequatchiecovecheese.com`,url:`https://www.sequatchiecovecheese.com/`}],reviewedOn:`2026-10-15`},{id:`dairy-brebis`,term:`Brebis`,category:`dairy`,aliases:[],ref:`c:fd_0154`,definition:`French for ewe; on a cheese menu it indicates sheep’s-milk cheese. It may describe a fresh cheese or an aged style such as Ossau-Iraty.`,guest:`Brebis means sheep’s-milk cheese; it can be fresh and soft or aged and firm.`,kitchen:`Identify the maker and cheese. Blackberry Farm’s Brebis is a fresh cheese, while Singing Brook is aged; the general French word is broader than either product.`,compare:`Brebis identifies the milk animal, not one universal rind, age or texture.`,correction:``,sources:[{title:`ossau-iraty.fr`,url:`https://www.ossau-iraty.fr/decouvrir-l-ossau-iraty`},{title:`Blackberry Farm`,url:`https://theblackberrymagazine.com/stories/2026-good-food-award-winners`}],reviewedOn:`2026-10-15`},{id:`dairy-buttermilk`,term:`Buttermilk`,category:`dairy`,aliases:[],ref:`c:fd_0155`,definition:`Traditionally the liquid left after churning butter. Most retail cultured buttermilk is milk fermented with cultures, giving a tangy flavor; fat content varies by product.`,guest:`Buttermilk is cultured milk with a gentle, tangy flavor, the same buttermilk behind Southern biscuits and fried chicken. On Thanksgiving Day our turkey breast was brined in it, which seasons the meat and leaves a soft tang.`,kitchen:`Use the specified product in dressings or baking; check whether it is whole, low-fat or another formulation.`,compare:`It is not automatically low-fat, and cream plus lemon is not identical to cultured buttermilk.`,correction:``,sources:[{title:`mayfielddairy.com`,url:`https://www.mayfielddairy.com/products/buttermilk/whole-buttermilk-half-gallon/`},{title:`organicvalley.coop`,url:`https://www.organicvalley.coop/products/cultured-1-percent-buttermilk`},{title:`Wikipedia: Buttermilk`,url:`https://en.wikipedia.org/wiki/Buttermilk`},{title:`America’s Test Kitchen: Conventional vs. Real Buttermilk`,url:`https://www.americastestkitchen.com/how-tos/6549-conventional-vs-real-buttermilk`},{title:`EBSCO Research Starters: Buttermilk`,url:`https://ebsco.com/research-starters/nutrition-and-dietetics/buttermilk`},{title:`Star Tribune: Buttermilk: Not just for grandma anymore`,url:`https://www.startribune.com/buttermilk-not-just-for-grandma-anymore/191057861`},{title:`Chowhound: Why Buttermilk Is Used in Biscuits`,url:`https://www.chowhound.com/1686787/why-buttermilk-used-in-biscuits`},{title:`King Arthur Baking: The history of American biscuits`,url:`https://www.kingarthurbaking.com/blog/2023/01/30/history-of-american-biscuits`},{title:`Chowhound: Pickle Juice Vs Buttermilk for Fried Chicken`,url:`https://www.chowhound.com/2264098/pickle-juice-vs-buttermilk-fried-chicken-brine/`},{title:`Food Republic: Is Buttermilk an Essential Ingredient for Fried Chicken?`,url:`https://www.foodrepublic.com/1807281/fried-chicken-buttermilk-purpose/`}],reviewedOn:`2026-10-15`,say:`BUT-er-milk`,background:`Buttermilk began as the thin liquid left in the churn after butter was made from cultured cream. In the 1920s American dairies began adding cultures to milk and selling the result as buttermilk, and that cultured product, thicker than the churned kind, is what stores sell today; because most butter is now churned from uncultured sweet cream, most buttermilk is cultured separately. Its acid reacts with baking soda, which made it the classic liquid of Southern biscuits. Southern cooks also soak chicken in it before frying, because its lactic acid tenderizes the meat gently.`,metAt:`Brennan's Thanksgiving Day 2026: Roasted Buttermilk-Brined Turkey Breast`},{id:`dairy-chevre`,term:`Chèvre`,category:`dairy`,aliases:[],ref:`c:fd_0156`,definition:`French for goat; in American menus it often means a fresh, tangy goat’s-milk cheese, but goat cheeses also come in aged and other forms.`,guest:`Chèvre is French for goat, and here it means goat cheese: soft, white and gently tangy. On the Thanksgiving Day sweet potato agnolotti its tang balanced the sweet filling, the brown butter and the candied pecans.`,kitchen:`Check whether the recipe calls for soft fresh cheese or an aged cheese; they behave differently when crumbled, spread or heated.`,compare:`Goat milk names an ingredient, not one fixed texture. Chèvre and brebis refer to different milk animals.`,correction:``,sources:[{title:`spinningspidercreamery.com`,url:`https://www.spinningspidercreamery.com/`},{title:`spinningspidercreamery.com`,url:`https://www.spinningspidercreamery.com/cheese/aged-cheese/`},{title:`The Cheese Professor: The 5 AOP chèvres of the Loire`,url:`https://www.cheeseprofessor.com/blog/aop-chevres-cheeses-loire`},{title:`Murray's Cheese: The great goat cheeses of France's Loire Valley`,url:`https://blog.murrayscheese.com/?p=4923`},{title:`Wikipedia: Chabichou`,url:`https://en.wikipedia.org/wiki/Chabichou`},{title:`Tourisme Vienne: Chabichou`,url:`https://www.tourisme-vienne.com/en/prepare/made-in-vienna/Local-specialties/chabichou/`},{title:`Google Arts and Culture, Fondation du patrimoine: Poitou, land of goats`,url:`https://artsandculture.google.com/story/poitou-land-of-goats-fondation-du-patrimoine/BAWh1qRyqXTuJA?hl=en`},{title:`Munchies: The best cheese stories are made of lies`,url:`https://munchies.vice.com/articles/the-best-cheese-stories-are-made-of-lies`},{title:`culture: The goat ladies who built American chèvre`,url:`https://culturecheesemag.com/stories/goat-ladies-american-goat-cheese-history/`},{title:`NPR, The Salt: American goat cheese, from hippie chick to hip and chic (2011)`,url:`https://www.npr.org/sections/thesalt/2011/09/01/140124884/american-goat-cheese-from-hippie-chick-to-hip-and-chic`},{title:`The Conversation: Gold rush opportunists, hippie goat ladies, Latino newcomers: California entrepreneurs dream of cheese`,url:`https://theconversation.com/gold-rush-opportunists-hippie-goat-ladies-latino-newcomers-california-entrepreneurs-dream-of-cheese-79469`}],reviewedOn:`2026-10-15`,say:`SHEV-ruh`,background:`Chèvre is the French word for goat, and in France fromage de chèvre, goat cheese, is a family of its own. Several of France's protected goat cheeses come from the Loire Valley, among them Sainte-Maure de Touraine, Selles-sur-Cher, Valençay and Crottin de Chavignol, and from Poitou to the south comes Chabichou du Poitou, protected since 1990. A legend says the region's goats were left behind by the Umayyad army after its defeat near Poitiers in 732, but goats were kept there long before, and the story is told as legend more than history. In the United States, nearly all the goat cheese sold was imported from Europe, much of it from France, until about 1980. In the late 1970s and early 1980s small farmstead makers in Northern California began making fresh chèvre, restaurants put it on their salads, and that work helped start the American specialty cheese movement.`,metAt:`Brennan's Thanksgiving Day 2026: Sweet Potato Agnolotti`},{id:`dairy-cremefraiche`,term:`Crème Fraîche`,category:`dairy`,aliases:[],ref:`c:fd_0157`,definition:`Cultured cream with a thick, smooth texture and gentle tang. It is often richer and less sharp than ordinary sour cream.`,guest:`Crème fraîche is thick cultured cream with a gentle tang.`,kitchen:`Use it to finish sauces or spoon over dishes as the recipe directs. Its richness often helps it tolerate heat, but the result depends on formulation and method.`,compare:`Not whipped cream; sour cream is a related cultured product with a different usual flavor and fat level.`,correction:``,sources:[{title:`vermontcreamery.com`,url:`https://www.vermontcreamery.com/products/creme-fraiche`},{title:`vermontcreamery.com`,url:`https://www.vermontcreamery.com/blogs/learn/what-is-crme-frache`}],reviewedOn:`2026-10-15`},{id:`dairy-fromageblanc`,term:`Fromage Blanc`,category:`dairy`,aliases:[],ref:`c:fd_0158`,definition:`A fresh, soft white cheese made by culturing milk and draining the curd. Its flavor is mild and gently tangy; texture depends on drainage.`,guest:`Fromage blanc is a fresh white cheese, soft and gently tangy.`,kitchen:`Use as a spread, in a dessert or as a sauce ingredient as appropriate. Check the actual product for milk type and fat level.`,compare:`Different from ricotta’s usual heat-driven process. Fromage blanc may use a little rennet and gently warmed milk during making.`,correction:``,sources:[{title:`cheesemaking.com`,url:`https://cheesemaking.com/pages/fromage-blanc-cheese-making-recipe-instructions`}],reviewedOn:`2026-10-15`},{id:`dairy-parmesan`,term:`Parmesan`,category:`dairy`,aliases:[`Parmigiano-Reggiano`],ref:`c:fd_0159`,definition:`Parmesan commonly names a hard grating-cheese style in the United States. Parmigiano Reggiano is a specific protected Italian cow’s-milk cheese made under defined rules.`,guest:`Parmesan is a hard grating cheese with a savory, nutty character. The exact cheese used in the dish determines its origin and style.`,kitchen:`Read the label before naming a protected cheese. Authentic Parmigiano Reggiano has a minimum maturation of twelve months and uses calf rennet.`,compare:`A generic Parmesan label should not automatically be described as Parmigiano Reggiano. Neither age nor style alone establishes vegetarian suitability.`,correction:``,sources:[{title:`parmigianoreggiano.com`,url:`https://www.parmigianoreggiano.com/en-US/faq`},{title:`backend.parmigianoreggiano.com`,url:`https://backend.parmigianoreggiano.com/uploads/Single_document_PR_24042025_825de2b63f.pdf`}],reviewedOn:`2026-10-15`},{id:`dairy-singingbrook`,term:`Singing Brook`,category:`dairy`,aliases:[],definition:`Blackberry Farm’s aged sheep’s-milk cheese, with a firm rind and a nutty, buttery character. The maker describes a minimum maturation of five to six months.`,guest:`Singing Brook is an aged sheep’s-milk cheese from Blackberry Farm in Tennessee, with a nutty, buttery flavor.`,kitchen:`Use on a cheese board, shaved or grated as the dish requires. Check the current wheel’s label rather than inferring milk treatment or rennet from age.`,compare:`Compare with Manchego as a flavor and texture reference, not as the same protected cheese. It is not made by Sequatchie Cove Creamery.`,correction:``,sources:[{title:`Blackberry Farm`,url:`https://theblackberrymagazine.com/stories/ways-to-use-our-cheeses`}],reviewedOn:`2026-10-15`},{id:`sauces-roux`,term:`Roux`,category:`sauces`,aliases:[`Dark roux`,`Brown roux`],definition:`Flour cooked in fat and stirred until it reaches the color the dish needs, then used to thicken and flavor a sauce, soup or stew. French kitchens stop at white, blond or brown. Louisiana cooks often go much further, to the brown of dark chocolate. As it darkens it turns toasty and nutty and loses thickening power, so a dark roux brings flavor more than body.`,guest:`A roux is flour cooked slowly in fat until it turns brown and nutty, and it is where a Louisiana soup like our gumbo begins. The darker the cook takes it, the deeper and toastier the flavor, and the less it thickens.`,kitchen:`Stirred without a break over steady heat and judged by its color, not the clock. How dark the house takes the roux for each soup and sauce is a question for the chef.`,compare:`Okra and filé are the other two gumbo thickeners; a roux is the one cooked first, in fat, and it adds a toasted flavor as well as body.`,correction:``,sources:[{title:`CooksInfo: Roux`,url:`https://www.cooksinfo.com/roux`},{title:`Explore Louisiana: How to Make Roux`,url:`https://www.explorelouisiana.com/culinary/recipes/how-make-roux`},{title:`MICHELIN Guide: What Is Roux`,url:`https://guide.michelin.com/en/article/dining-in/what-is-roux-sg`},{title:`Saveur: Cajun Roux`,url:`https://www.saveur.com/article/Kitchen/Cajun-Roux`},{title:`CooksInfo: François Pierre de la Varenne`,url:`https://www.cooksinfo.com/francois-pierre-de-la-varenne`},{title:`Saveur: Dark Roux`,url:`https://www.saveur.com/article/recipes/dark-roux`}],reviewedOn:`2026-11-27`,say:`ROO`,background:`Roux is the French word for reddish, and the first written references to a roux in a sauce are usually traced to Le Cuisinier françois, a French cookbook of 1651, where flour cooked in fat thickens sauces, though the same book still thickens some dishes with bread. Those early roux were cooked to a reddish brown. By the middle of the eighteenth century French cookbooks were advising a paler one, and classical kitchens came to sort roux by color: white for béchamel, blond for velouté and brown for espagnole. Louisiana cooks carried the method the other way. A roux stirred long enough over steady heat, often half an hour or more, turns the brown of dark chocolate, and that dark roux became the start of a Cajun or Creole gumbo.`,metAt:`Brennan's Thanksgiving Day 2026: Seafood Gumbo, Turtle Soup and Shrimp Sauce Piquante`},{id:`sauces-holytrinity`,term:`Holy Trinity`,category:`sauces`,aliases:[`Trinity`,`Cajun holy trinity`],definition:`Chopped onion, celery and green bell pepper, cooked together at the start of many Cajun and Creole dishes. It is Louisiana’s version of the French mirepoix, with green bell pepper where the French use carrot. Cooks often use equal parts, or twice as much onion as each of the other two. It softens into the savory base of a gumbo or a sauce piquante before any spice goes in.`,guest:`The holy trinity is onion, celery and green bell pepper cooked down together, the way so much Louisiana cooking begins. It is why the gumbo tastes of Louisiana before a single spice goes in.`,kitchen:`Diced and sweated together near the start, often straight into the roux, until soft; garlic often joins it.`,compare:`Mirepoix is onion, celery and carrot; the trinity swaps the carrot for green bell pepper, which gives a greener, less sweet base.`,correction:``,sources:[{title:`LSU AgCenter: For whom the bell grows: A brief history of the Cajun holy trinity`,url:`https://www.lsuagcenter.com/articles/page1621432197656`},{title:`Wikipedia: Holy trinity (cooking)`,url:`https://en.wikipedia.org/wiki/Holy_trinity_(cooking)`},{title:`Explore Louisiana: The Holy Trinity of Cajun Cooking`,url:`https://www.explorelouisiana.com/culinary/recipes/behold-holy-trinity-cajun-cooking`}],reviewedOn:`2026-11-27`,say:`HOH-lee TRIN-ih-tee`,background:`The trinity is the Cajun and Creole answer to the French mirepoix of onion, celery and carrot, with green bell pepper in the carrot’s place. Why the pepper won is still argued. One account holds that the early French and Spanish settlers of Louisiana kept the onion and celery they knew but found carrots hard to come by. LSU AgCenter vegetable specialists doubt that peppers were ever cheaper or easier to grow than carrots there, and suggest tradition and taste kept the pepper in the pot. The name nods to the Christian Trinity and the Catholic faith of many early settlers. It was most likely popularized in the early 1980s by the Opelousas born chef Paul Prudhomme (1940 to 2015).`,metAt:`Brennan's Thanksgiving Day 2026: Seafood Gumbo, Turtle Soup and Shrimp Sauce Piquante`},{id:`sauces-piperade`,term:`Piperade`,category:`sauces`,aliases:[`Pipérade`],definition:`A dish of the Basque country and Gascony, in southwest France: onions, green peppers and tomatoes softened together and seasoned with piment d’Espelette, the dried red pepper of the Basque town of Espelette. It is eaten on its own, often with eggs or ham, or used as a pepper and tomato base under other food. Its red, green and white echo the colors of the Basque flag, by coincidence.`,guest:`Piperade is a Basque dish of peppers, onion and tomato cooked down slowly together, traditionally seasoned with Espelette pepper, a red pepper of gentle heat. On our Thanksgiving menu it went beside the Veal Grillades, with the gravy, the grits and a poached egg.`,kitchen:`The onions, peppers and tomatoes are sautéed slowly until soft and their juices cook down. Whether the house piperade carried Espelette pepper is the chef’s to confirm at lineup.`,compare:`Ratatouille is its nearest neighbor: both are slow cooked vegetables of southern France, but ratatouille is Provençal and built on eggplant and zucchini, while piperade is Basque and is pepper, onion and tomato, with Espelette pepper as the tell.`,correction:``,sources:[{title:`Wikipedia: Piperade`,url:`https://en.wikipedia.org/wiki/Piperade`},{title:`James Beard Foundation: Eat This Word, Pipérade`,url:`https://www.jamesbeard.org/stories/eat-this-word-piprade`},{title:`French Property: Piperade Basque`,url:`https://www.french-property.com/regions/midi_pyrenees/food-gastronomy/piperade`},{title:`Wikipedia: Espelette pepper`,url:`https://en.wikipedia.org/wiki/Espelette_pepper`},{title:`Piment d’Espelette AOP: Espelette Pepper`,url:`https://www.pimentdespelette.com/espelette-pepper/`},{title:`Piment d’Espelette AOP: Press File 2018`,url:`https://www.pimentdespelette.com/wp-content/uploads/2019/06/dossier-de-presse-en-anglais.pdf`},{title:`Ministère de l’Agriculture: Piment d’Espelette`,url:`https://agriculture.gouv.fr/telecharger/136890`},{title:`INAO: Cahier des charges, Piment d’Espelette`,url:`https://www.inao.gouv.fr/fichier/CDCPimentDEspelette.pdf`},{title:`Evous: Piperade ou ratatouille`,url:`https://www.evous.fr/terres-et-saveurs/au-potager/poivron-ou-piment/piperade-ou-ratatouille-recettes,1183150.html`},{title:`Food Network: What Is Ratatouille?`,url:`https://www.foodnetwork.com/how-to/packages/food-network-essentials/what-is-ratatouille`},{title:`Tasting Table: Eggs Pipérade`,url:`https://www.tastingtable.com/1031997/eggs-piperade-the-veggie-infused-basque-eggs-you-should-know`}],reviewedOn:`2026-11-27`,say:`pee-peh-RAHD`,background:`Piperade takes its name from piper, the word for pepper in Gascon and in Basque, itself from the Latin for black pepper. Wikipedia gives Gascony and the Basque Country as its home, while a French regional guide calls it a recipe of Béarn that the Basque country later took up. Its pepper came from the Americas: chili peppers reached France in the sixteenth century, and the producers of Espelette say that nobody knows exactly when it reached them, though the first traces of the pepper there appear around 1650. Piment d’Espelette is now a protected name. The producers formed a syndicate in 1993, the pepper became an AOC on 29 May 2000 and an AOP in 2002, and it may be grown in ten communes of the Basque country, two of them in full and eight in part.`,metAt:`Brennan's Thanksgiving Day 2026: the piperade on the Veal Grillades`},{id:`sauces-miso`,term:`Miso`,category:`sauces`,aliases:[`Miso paste`,`Shiro miso`,`White miso`],definition:`A Japanese paste of soybeans fermented with salt and koji, the mold Aspergillus oryzae grown on rice, barley or the soybeans themselves. Shiro, or white, miso is fermented for a shorter time with a higher share of koji, so it is mild and sweet; aka, or red, miso ferments longer and is darker, saltier and stronger. A spoonful brings salt and deep savory flavor, umami, to soups and glazes and, in pastry, to caramel and baked sweets. On the Thanksgiving Day menu it was the savory note in the Sweet Potato Pot de Crème.`,guest:`Miso, said MEE-soh, is a Japanese fermented soybean paste. A little in a dessert works much as the salt does in a salted caramel: it brings a savory depth that makes the sweetness taste rounder. In our Sweet Potato Pot de Crème it sat with cinnamon and marshmallow, so the custard was never simply sweet.`,kitchen:`Pastry cooks reach for white miso in sweets and use it sparingly, cutting back the other salt, because too much overwhelms the sugar. Which miso the house used, and whether it went into the custard or a caramel, was the kitchen’s to say; miso is soy, so every soy question goes to the kitchen.`,compare:`Soy sauce is its nearest neighbor, a seasoning of the same fermented soybean family: soy sauce is a thin liquid you pour, miso a thick paste you stir in. Among misos, color is the tell: the paler the miso, the milder and sweeter it is.`,correction:``,sources:[{title:`Ministry of Agriculture, Forestry and Fisheries of Japan: Soy sauce and miso`,url:`https://www.maff.go.jp/e/policies/market/dento_syoku/bunrui/syouyu-miso.html`},{title:`Kikkoman Institute for International Food Culture, Food Culture journal: the history of miso and soy sauce`,url:`https://www.kikkoman.com/en/kiifc/journal/pdf_01/e_012_015.pdf`},{title:`Wikipedia: Miso`,url:`https://en.wikipedia.org/wiki/Miso`},{title:`America’s Test Kitchen: Miso Primer`,url:`https://www.americastestkitchen.com/how-tos/5718-miso-primer`},{title:`MasterClass: Types of Miso Paste`,url:`https://www.masterclass.com/articles/types-of-miso-paste`},{title:`King Arthur Baking: A beginner’s guide to baking with miso`,url:`https://www.kingarthurbaking.com/blog/2021/12/13/a-beginners-guide-to-baking-with-miso`},{title:`Tasting Table: 8 Expert Tips For Baking With Miso`,url:`https://www.tastingtable.com/1947695/bake-with-miso-expert-tips/`},{title:`America’s Test Kitchen: Miso Caramel Sauce`,url:`https://www.americastestkitchen.com/recipes/17031-miso-caramel-sauce`}],reviewedOn:`2026-11-27`,say:`MEE-soh`,background:`Miso grew from the fermented seasonings of China, which the Japanese called hishio, though when and how it reached Japan is disputed: one account carries it with Buddhism in the sixth century, and Japan’s agriculture ministry records a theory that it came from the Korean kingdom of Goguryeo in 666. The first written record in Japan is the Taihō Code of 701, which names it misho, a word unknown in China, read as not yet hishio. The paste is made by mixing cooked soybeans with salt and koji, the mold Aspergillus oryzae, and leaving it to ferment, and the length of that rest and the share of koji give the many regional misos their colors and strengths. Far from Japan, pastry cooks have taken mild white miso into sweets, most often as miso caramel, for its salt and savory depth.`,metAt:`Brennan's Thanksgiving Day 2026: Sweet Potato Pot de Crème`},{id:`sauces-sherry`,term:`Sherry`,category:`sauces`,aliases:[`Aged Sherry`,`Jerez`,`Xérès`],definition:`A fortified wine from the Jerez district of Andalusia, in southern Spain. It ages in a solera, tiers of barrels in which the wine drawn for bottling from the oldest is replaced from the next younger, so every bottle blends many years. The dry styles run from pale fino, aged under a film of yeast called flor, through amontillado, which starts under flor and then ages in contact with air, to darker, richer oloroso. In the kitchen a splash of dry, aged sherry finishes a rich soup.`,guest:`We finish the turtle soup with a splash of aged Sherry, the fortified wine of Jerez in southern Spain. Its dry, nutty taste lifts the richness of the soup, much as a squeeze of lemon lifts a piece of fish.`,kitchen:`Which Sherry finishes the soup, and whether it goes in at the stove or at the table, is a lineup question. Tell any guest avoiding alcohol that it is in the soup, and never promise that it cooks off.`,compare:`Fino and manzanilla age under flor and stay pale; amontillado begins under flor and then ages with air; oloroso ages with air and is darker and richer. The menu prints aged Sherry, not which style.`,correction:``,sources:[{title:`Consejo Regulador, sherry.wine: History of Sherry`,url:`https://www.sherry.wine/sherry-region/history-of-sherry`},{title:`GOV.UK protected food and drink names: Amontillado`,url:`https://www.gov.uk/protected-food-drink-names/amontillado`},{title:`GOV.UK protected food and drink names: Criaderas y Soleras`,url:`https://www.gov.uk/protected-food-drink-names/criaderas-y-soleras`},{title:`Tienda: Adventure, War and Sherry`,url:`https://www.tienda.com/learn-about-spain/adventure-war-and-sherry`},{title:`Brennan's New Orleans: Turtle Soup recipe`,url:`https://www.brennansneworleans.com/recipes/turtle-soup/`},{title:`Consejo Regulador, sherry.wine: The Consejo Regulador`,url:`https://www.sherry.wine/sherry-region/consejo-regulador`},{title:`Library of Congress: Sir Francis Drake, the Cádiz raid`,url:`https://www.loc.gov/collections/sir-francis-drake/articles-and-essays/drake-biography/the-cadiz-raid/`},{title:`The Drinks Business: Drake and the sherry of Cádiz`,url:`https://thedrinksbusiness.com/?p=210576`}],reviewedOn:`2026-11-27`,say:`SHAIR-ee`,background:`Sherry takes its name from Jerez de la Frontera, which with Sanlúcar de Barrameda and El Puerto de Santa María makes the sherry triangle of Cádiz. English drinkers knew it as sack, and in 1587 Francis Drake (about 1540 to 1596) raided Cádiz and carried off close to three thousand casks of it. William Shakespeare (1564 to 1616) gave Falstaff a speech in praise of sherris sack in Henry IV, Part 2. In 1933 Spain's first wine statute recognized the denominación de origen Jerez, and in 1935 its Consejo Regulador, the first in Spain, was set up to keep its rules. In the Creole kitchen sherry is a finish: Brennan's published turtle soup recipe adds it with the egg, spinach and lemon at the end.`,metAt:`Brennan's Thanksgiving Day 2026: Classic Turtle Soup, finished with aged Sherry`},{id:`sauces-vinaigrette`,term:`Vinaigrette`,category:`sauces`,aliases:[`Sauce vinaigrette`,`Oil and vinegar dressing`],definition:`A cold sauce of oil and an acid, usually vinegar, whisked with salt and pepper, often with a little mustard to help it hold. The usual starting point is about three parts oil to one of vinegar, adjusted by taste for the oil and vinegar in hand. Whisking breaks the oil into tiny droplets through the vinegar, a temporary emulsion that separates as it stands and is whisked again before use. Flavored vinaigrettes add fruit, herbs, shallot or garlic.`,guest:`A vinaigrette is a light dressing of oil and vinegar whisked together, bright and sharp. On Thanksgiving Day ours was a cherry vinaigrette, so it brought sweet, tart red fruit to the bitter endive and the satsuma.`,kitchen:`Whisked or shaken just before it dresses the leaves, because it separates as it stands, and tasted for balance; the salad is dressed at the last moment so the leaves stay crisp. What goes into the cherry vinaigrette beyond cherry is the kitchen's to say.`,compare:`Mayonnaise is its nearest neighbor among emulsified sauces: egg yolk holds a mayonnaise in a thick, lasting emulsion, while a vinaigrette has no yolk, stays pourable and separates as it stands.`,correction:``,sources:[{title:`Wikipedia: Vinaigrette`,url:`https://en.wikipedia.org/wiki/Vinaigrette`},{title:`The Kitchen Project: Why is it called vinaigrette?`,url:`https://kitchenproject.com/history/SaladDressing/Vinaigrette-History.htm`},{title:`Literary Hub: Did the Italians actually teach the French the art of the vinaigrette?`,url:`https://lithub.com/did-the-italians-actually-teach-the-french-the-art-of-the-vinaigrette/`},{title:`Miele: Vinaigrette`,url:`https://www.miele.co.za/domestic/3475.htm`},{title:`Dictionary.com: vinaigrette`,url:`https://www.dictionary.com/browse/vinaigrette`},{title:`Food Network Kitchen: Simple Vinaigrette`,url:`https://www.foodnetwork.com/recipes/food-network-kitchen/simple-vinaigrette-3363078`},{title:`Chowhound: Use the classic 3 to 1 method to create perfect salad dressing`,url:`https://www.chowhound.com/2229425/classic-three-to-one-method-for-perfect-salad-dressing/`},{title:`Wikipedia: French dressing`,url:`https://en.wikipedia.org/wiki/French_dressing`}],reviewedOn:`2026-11-27`,say:`vin-uh-GRET`,background:`Vinaigrette is the diminutive of the French vinaigre, vinegar, a word that itself means sour wine. The word is older than the dressing: in Le Viandier, a French cookbook of the fourteenth century, it names a meat dish, not a cold sauce. The modern sense was printed in the Dictionnaire de l'Académie française in 1694, which described a cold sauce of vinegar, oil, salt, pepper, parsley and chives. English took the word at the end of the seventeenth century, and John Evelyn (1620 to 1706) used it in Acetaria, his book on salads, in 1699. In nineteenth century American cookbooks, French dressing meant this plain dressing of oil and vinegar. In classical French cooking a vinaigrette dresses salads and, as a cold sauce, goes with artichokes, asparagus and leeks.`,metAt:`Brennan's Thanksgiving Day 2026: Endive Satsuma Salad, with a cherry vinaigrette`},{id:`sauces-jus`,term:`Jus`,category:`sauces`,aliases:[`Au jus`,`Jus lié`],definition:`French for juice: on a menu, a light sauce made from the juices a roast gives up as it cooks, often reduced to concentrate its flavor. It is thinner and clearer than a flour gravy. Served unthickened, the meat is said to come au jus, in its own juice; thickened lightly with a starch such as arrowroot or cornstarch, it becomes a jus lié. The turkey on the Thanksgiving Day menu came with a cranberry and rosemary jus.`,guest:`A jus, said zhoo, is a light sauce made from the roast’s own juices, thinner and brighter than a flour gravy, so it seasons the meat without weighing it down. Ours on Thanksgiving Day carried tart cranberry and piney rosemary for the turkey.`,kitchen:`The kitchen builds a jus from the pan juices and stock, reduces it for flavor and strains it; a little starch slurry turns it into a jus lié. Whether the cranberry and rosemary jus was thickened at all was a question for lineup.`,compare:`Gravy is the nearest neighbor: a gravy is thickened, usually with flour, and coats the meat, while a jus is thin and glossy, and even a jus lié is thickened only lightly with a clear starch.`,correction:``,sources:[{title:`MICHELIN Guide: What Is Jus?`,url:`https://guide.michelin.com/en/article/dining-out/what-is-jus`},{title:`Wikipedia: Au jus`,url:`https://en.wikipedia.org/wiki/Au_jus`},{title:`ckbk: Fond lié`,url:`https://app.ckbk.com/section/prof36725c08s001ss002sss006ssss003sssss001/fond-lie`},{title:`Glorious Food Glossary: Jus lié`,url:`https://www.glorious-food-glossary.com/cms/glossary/glossary-j/1330-jus-lie.html`},{title:`ckbk: Jus`,url:`https://app.ckbk.com/reference/form15594b01s001e019/jus`},{title:`Online Etymology Dictionary: jus`,url:`https://www.etymonline.com/fr/word/jus`},{title:`Wiktionary: jus`,url:`https://en.wiktionary.org/wiki/jus`},{title:`Britannica: French dip`,url:`https://www.britannica.com/topic/French-dip`},{title:`Wikipedia: French dip`,url:`https://en.wikipedia.org/wiki/French_dip`},{title:`Snopes: Was the French Dip Sandwich Invented in Los Angeles?`,url:`https://www.snopes.com/fact-check/french-dip/`}],reviewedOn:`2026-11-27`,say:`ZHOO`,background:`The word goes back to the Latin ius, broth, sauce or juice, which became jus in Old French; the English word juice comes from the same root by another road. In the French kitchen a jus is the natural juice a meat releases as it cooks, and the word has also named a clear or lightly thickened brown stock, especially of veal. A jus lié is a brown stock or jus thickened lightly with arrowroot or cornstarch. American menus took up the phrase au jus for beef served with its own juices, and it is tied above all to the French dip sandwich, roast beef on a roll dipped in jus, which two Los Angeles restaurants, Philippe’s and Cole’s, each claim to have invented early in the twentieth century.`,metAt:`Brennan's Thanksgiving Day 2026: the cranberry and rosemary jus of the Roasted Buttermilk-Brined Turkey Breast`},{id:`sauces-sauceaupoivre`,term:`Sauce au Poivre`,category:`sauces`,aliases:[`Au poivre`,`Peppercorn sauce`,`Steak au poivre`],definition:`French for sauce with pepper: the pan sauce of steak au poivre, built on coarsely crushed peppercorns. In the classic, the steak is pressed into cracked pepper and seared, then the pan is deglazed with Cognac or brandy over softened shallots and finished with cream, or with stock in lighter versions. Filet mignon, from the tenderloin, is the classic cut for it. On the Thanksgiving Day menu it came with the herb roasted beef tenderloin.`,guest:`Au poivre, said oh PWAHV, is French for with pepper: in the bistro classic, a pan sauce of cracked peppercorns, a splash of Cognac and cream. On Thanksgiving Day it dressed our herb roasted beef tenderloin, the same lean, tender cut the classic is made with.`,kitchen:`In the classic the peppercorns are crushed coarsely rather than ground fine, and the Cognac is cooked off in the pan before the cream goes in. Whether ours carried Cognac and cream, and how much pepper, was a question for lineup, and the spirit matters to some guests.`,compare:`Steak Diane is the nearest neighbor, another pan sauce of the classic steakhouse, but Diane leans on Worcestershire sauce, often with mustard, while au poivre leans on crushed peppercorns, Cognac and cream.`,correction:``,sources:[{title:`Wikipedia: Steak au poivre`,url:`https://en.wikipedia.org/wiki/Steak_au_poivre`},{title:`Cook's Info: Steak au Poivre`,url:`https://www.cooksinfo.com/steak-au-poivre/`},{title:`Steak au Poivre, a history and recipe (PDF)`,url:`https://cbwineprogram.com/pdf/steakaupoivre.pdf`},{title:`Tasting Table: Steak Diane Vs Steak Au Poivre: What's The Difference?`,url:`https://www.tastingtable.com/1841690/steak-diane-vs-au-poivre/`},{title:`Wikipedia: Steak Diane`,url:`https://en.wikipedia.org/wiki/Steak_Diane`}],reviewedOn:`2026-11-27`,say:`SOHS oh PWAHV`,background:`Steak au poivre is a dish of the French restaurant, and who first made it is disputed. In 1950 the chef of a Paris restaurant said he had created it in 1930; another Paris chef answered that he had made it first, in 1919 or 1920, and Larousse Gastronomique records versions said to date from 1905 in Paris and 1910 in Monte Carlo, so no single origin story holds. What every claim shares is the method: a steak, classically filet mignon, coated in crushed peppercorns, pan fried and served with a quick sauce made in the same pan, most often with Cognac and cream. Its nearest neighbor, steak Diane, is a steak sauced in the pan with Worcestershire, and at the height of its popularity it was often flamed at the table.`,metAt:`Brennan's Thanksgiving Day 2026: Herb Roasted Beef Tenderloin`},{id:`sauces-saucepiquante`,term:`Sauce Piquante`,category:`sauces`,aliases:[`Sauce piquant`,`Sauce picante`],definition:`A hot, tomato based Louisiana stew more than a sauce, usually begun on a roux with onion, celery and bell pepper, then simmered with tomatoes and pepper until thick. It smothers whatever the cook has, chicken, rabbit, turtle, alligator or shrimp, and it is served over rice. The name is French for a sharp, pricking taste. In a French kitchen sauce piquante is a different thing: a brown sauce sharpened with vinegar, shallots and chopped gherkins.`,guest:`Sauce piquante is a Cajun country classic: meat or seafood simmered in a peppery tomato gravy built on a roux with onion, celery and bell pepper, and served over rice. Piquante means sharp, and the dish is known for its pepper. On our Thanksgiving menu it was shrimp in a Creole tomato gravy over popcorn rice pilaf, finished with pickled peppers.`,kitchen:`Built like a stew: the roux, then the onion, celery and bell pepper, then tomato and stock, simmered until it thickens. How dark the roux goes, how hot the pepper runs and when the shrimp go in are the chef’s calls, so ask at lineup before you promise a guest the heat.`,compare:`Shrimp Creole is its nearest neighbor: both are shrimp in a tomato sauce over rice, but a sauce piquante is usually started on a roux and runs hotter. Étouffée, the other cousin, is a roux gravy with little or no tomato.`,correction:``,sources:[{title:`Wikipedia: Cajun cuisine`,url:`https://en.wikipedia.org/wiki/Cajun_cuisine`},{title:`Atlas Obscura: Turtle Sauce Picante`,url:`https://www.atlasobscura.com/foods/turtle-sauce-picante`},{title:`Merriam-Webster: Piquant`,url:`https://www.merriam-webster.com/dictionary/piquant`},{title:`The French Cooking Academy: Escoffier Sauce Piquante`,url:`https://www.thefrenchcookingacademy.com/recipes/escoffier-sauce-piquante`},{title:`CooksInfo: French Sauces`,url:`https://www.cooksinfo.com/french-sauces/`},{title:`ckbk: The Picayune’s Creole Cook Book, Piquant Sauce`,url:`https://app.ckbk.com/recipe/thep19270c10s001r019/piquant-sauce`},{title:`Wikipedia: Picayune Creole Cookbook`,url:`https://en.wikipedia.org/wiki/Picayune_Creole_Cookbook`}],reviewedOn:`2026-11-27`,say:`sohs pee-KAHNT`,background:`Piquant comes from the French verb piquer, to prick or sting, and in English it names a sharp, biting taste. In classical French cooking sauce piquante is one of the brown sauces: a reduction of shallots, white wine and vinegar finished with a brown sauce, chopped gherkins and herbs, the version Auguste Escoffier (1846 to 1935) set down. The Picayune’s Creole Cook Book, first published in New Orleans in 1900 and expanded in 1901, printed a Piquant Sauce among its sauces. In Cajun country the name came to mean something heartier. Cajun and Creole cooks use it for a hot, tomato based sauce that smothers meat and rice, a stew begun on a roux and the holy trinity and cooked with chicken, rabbit, turtle, alligator or seafood. When or where the Louisiana dish first took the French name, no record shows.`,metAt:`Brennan's Thanksgiving Day 2026: Shrimp Sauce Piquante`},{id:`sauces-tomatogravy`,term:`Tomato Gravy`,category:`sauces`,aliases:[`Creole tomato gravy`],definition:`A Southern gravy of fat and flour cooked into a roux, then simmered with tomatoes and a little broth, milk or water until thick and savory. Bacon drippings are the old fat and butter the common stand in, and many cooks add a pinch of sugar to soften the acid. The roux is what makes it a gravy and not a plain tomato sauce. On the Thanksgiving Day menu a Creole tomato gravy was the sauce of the Shrimp Sauce Piquante.`,guest:`Tomato gravy is a Southern classic: a roux of flour and fat simmered with tomatoes into a thick, savory sauce, rounder and richer than a plain tomato sauce. On our Thanksgiving shrimp sauce piquante it was a Creole tomato gravy, spooned over the rice.`,kitchen:`The flour cooks in the fat until it starts to color, then the tomatoes and liquid go in and it simmers until it coats a spoon, tasted for acid along the way. What went into the house Creole tomato gravy, and how hot it ran, was the kitchen’s to say.`,compare:`New Orleans red gravy is its nearest neighbor: red gravy is the slow cooked tomato sauce of the city’s Sicilian families, and cooks disagree on whether it takes a roux, while a Southern tomato gravy is always built on one and cooked quickly. The long simmer and the Sicilian table are the tell.`,correction:``,sources:[{title:`James Beard Foundation: Tomato Gravy`,url:`https://www.jamesbeard.org/recipes/tomato-gravy`},{title:`Saveur: Tomato Gravy`,url:`https://www.saveur.com/article/Recipes/Tomato-Gravy`},{title:`Tasting Table: Tomato and Bacon Grease Make for a Simple Southern Gravy`,url:`https://www.tastingtable.com/1469799/tomato-bacon-grease-southern-gravy`},{title:`Blind Pig and the Acorn: Tomato Gravy`,url:`https://blindpigandtheacorn.com/tomato-gravy/`},{title:`AOL: What Is Tomato Gravy?`,url:`https://www.aol.com/news/tomato-gravy-203936678.html`},{title:`Southern Cultures: Red Gravy`,url:`https://www.southerncultures.org/article/red-gravy`},{title:`NOLA History Guy: Five Italian Contributions to New Orleans`,url:`https://nolahistoryguy.com/five-italian-contributions-to-new-orleans/`},{title:`Wikipedia: Italians in New Orleans`,url:`https://en.wikipedia.org/wiki/Italians_in_New_Orleans`},{title:`The Gumbo Pages: New Orleans Red Gravy`,url:`https://www.gumbopages.com/food/sauces/red-gravy.html`}],reviewedOn:`2026-11-27`,say:`tuh-MAY-toh GRAY-vee`,background:`Tomato gravy belongs to the Southern home kitchen and to thrift: a spoon of flour in the bacon drippings, then tomatoes, fresh from the garden or home canned. In southern Appalachia it is a breakfast gravy over biscuits, and Saveur notes it as a partner for biscuits in parts of Mississippi, Alabama and Florida. New Orleans has a tomato gravy story of its own. Sicilian immigrants came through the port in great numbers from about 1885 to 1915, and their slow cooked tomato sauce became the city’s red gravy, a name that set it apart from the brown gravies New Orleans cooks had made for generations. Whether a roux belongs in it is still argued: some cooks call for one and many recipes leave it out.`,metAt:`Brennan's Thanksgiving Day 2026: the Creole tomato gravy of the Shrimp Sauce Piquante`},{id:`sauces-brownbutter`,term:`Brown Butter`,category:`sauces`,aliases:[`Beurre noisette`,`Browned butter`],definition:`Butter cooked past melting until its water boils away and its milk solids toast to a golden brown, giving a nutty smell and taste. The French call it beurre noisette, hazelnut butter, for its color and aroma. The toasted solids stay in the butter, which is what sets it apart from clarified butter. On the Thanksgiving Day menu it finished the Redfish Meunière and the Sweet Potato Agnolotti, and it went into the spinach of the Turtle Soup.`,guest:`Brown butter is butter cooked gently until it turns golden and smells of toasted hazelnuts; the French call it beurre noisette, hazelnut butter. It gives a warm, nutty richness. On Thanksgiving Day it was on the redfish with lemon and capers, on the sweet potato agnolotti, and in the spinach of our turtle soup.`,kitchen:`The butter melts, foams and sputters while the water cooks off, then goes quiet as the solids start to brown, and from there it darkens fast, so it is watched and taken off the heat the moment it smells nutty. Lemon or other acid goes in at the end for a meunière.`,compare:`Beurre noir is its nearest neighbor: black butter, cooked further until the solids are very dark, then sharpened with lemon or vinegar. Clarified butter goes the other way, with the milk solids taken out so nothing browns. Golden solids and a hazelnut smell are the tell of brown butter.`,correction:``,sources:[{title:`Wikipedia: Beurre noisette`,url:`https://en.wikipedia.org/wiki/Brown_butter`},{title:`Wikipedia: Beurre noir`,url:`https://en.wikipedia.org/wiki/Beurre_noir`},{title:`Office québécois de la langue française: beurre noisette`,url:`https://vitrinelinguistique.oqlf.gouv.qc.ca/fiche-gdt/fiche/26557043/beurre-noisette`},{title:`The Daily Meal: What Is Beurre Noisette?`,url:`https://www.thedailymeal.com/eat/what-beurre-noisette/`},{title:`America's Test Kitchen: How to Make Browned Butter`,url:`https://www.americastestkitchen.com/articles/how-to-make-browned-butter`},{title:`America's Test Kitchen: Why Is Browned Butter So Delicious`,url:`https://www.americastestkitchen.com/articles/4007-why-is-browned-butter-so-dang-delicious`},{title:`Wikipedia: Meunière sauce`,url:`https://en.wikipedia.org/wiki/Meuni%C3%A8re_sauce`},{title:`Wikipedia: Louis Camille Maillard`,url:`https://en.wikipedia.org/wiki/Louis_Camille_Maillard`},{title:`NPR: 100 Years Ago, Maillard Taught Us Why Our Food Tastes Better Cooked`,url:`https://www.npr.org/blogs/thesalt/2012/10/10/162636059/100-years-ago-maillard-taught-us-why-our-food-tastes-better-cooked`}],reviewedOn:`2026-11-27`,say:`brown BUH-tur`,background:`Brown butter asks only butter and heat. The French name, beurre noisette, means hazelnut butter, for the color of the browned solids and the nutty smell. Taken further it becomes beurre noir, black butter, sharpened with lemon or vinegar and served with eggs, fish and vegetables. With lemon and parsley, brown butter is the meunière sauce of the classic sole and trout. The science came later. The flavor comes from the milk solids, whose sugars and amino acids react as they toast. That browning bears the name of the French physician and chemist Louis Camille Maillard (1878 to 1936), who described the reaction of amino acids with sugars in 1912.`,metAt:`Brennan's Thanksgiving Day 2026: Redfish Meunière, Sweet Potato Agnolotti and the brown butter spinach of the Turtle Soup`},{id:`grains-popcornrice`,term:`Popcorn Rice`,category:`grains`,aliases:[`Louisiana popcorn rice`,`Della rice`],definition:`A Louisiana aromatic long grain rice of the Della type that smells of popcorn as it cooks. The aroma comes from a compound called 2-acetyl-1-pyrroline, the same one behind the scent of jasmine and basmati rice. It cooks up dry and fluffy with separate grains, like an ordinary American long grain. That suits a gumbo or a pilaf, where the grains should hold their shape.`,guest:`Popcorn rice is a Louisiana long grain that really does smell of popcorn as it cooks, from the same natural aroma that perfumes jasmine and basmati. It stays fluffy and separate, so it holds up under the gumbo, as it did on Thanksgiving Day in the pilaf beneath the shrimp sauce piquante.`,kitchen:`Cooked like a standard long grain: on its own for the gumbo, and toasted in fat before the liquid goes in for the pilaf, so the grains stay separate.`,compare:`Jasmine rice carries the same aroma compound but cooks softer and stickier; popcorn rice cooks up drier and more separate, like an ordinary long grain.`,correction:``,sources:[{title:`LSU AgCenter: Specialty Rices for Louisiana`,url:`https://www.lsuagcenter.com/portals/communications/publications/agmag/archive/2003/summer/specialty-rices-for-louisiana`},{title:`LSU AgCenter: LSU AgCenter Releases Two New Rice Varieties for 2012`,url:`https://www.lsuagcenter.com/portals/our_offices/research_stations/rice/features/publications/lsu-agcenter-releases-two-new-rice-varieties-for-2012`},{title:`Rice Farming: Louisiana, Texas Release Long Grain Varieties`,url:`https://www.ricefarming.com/departments/feature/louisiana-texas-release-long-grain-varieties/`},{title:`LSU Research: Full Servings`,url:`https://www.lsu.edu/research/news/2020/1020-varietydevelopment.php`},{title:`LSU AgCenter: History of the H. Rouse Caffey Rice Research Station`,url:`https://www.lsuagcenter.com/portals/our_offices/research_stations/rice/features/history%20of%20the%20station`}],reviewedOn:`2026-11-27`,say:`POP-korn RYSE`,background:`Popcorn rice is the Della type of aromatic long grain, bred in Louisiana at the LSU AgCenter Rice Research Station, which was established at Crowley in 1909. Della was released in the 1970s for American cooks who wanted a fluffy, separate long grain with a popcorn aroma. It cooked and smelled as hoped but grew tall, yielded little and tended to lodge, falling over in the field. So the station went on breeding shorter Della type varieties, among them Dellrose and Dellmont, and then Della-2, released for 2012. The aroma that gives the rice its name is 2-acetyl-1-pyrroline, the compound LSU AgCenter credits for the popcorn scent of Della, Dellmont and Dellrose.`,metAt:`Brennan's Thanksgiving Day 2026: Seafood Gumbo, and the popcorn rice pilaf under the Shrimp Sauce Piquante`},{id:`grains-grits`,term:`Grits`,category:`grains`,aliases:[`Corn grits`],definition:`Dried corn ground coarse and cooked slowly in liquid into a thick, soft porridge, the everyday corn dish of the American South. Grits are traditionally ground from dent corn, a starchy field corn. Stone ground grits keep the germ and take far longer to cook than quick grits, which are milled finer. Some grits are ground from hominy, corn first treated with an alkali, and many are not.`,guest:`Grits are coarsely ground dried corn, cooked slowly into a soft, creamy porridge, a dish the South learned from the Native peoples who first ground corn for it. On our Thanksgiving menu they were cheddar grits under the Veal Grillades, the old New Orleans pairing of grillades and grits.`,kitchen:`Grits want a long, gentle cook and frequent stirring so they thicken without sticking: stone ground grits can take most of an hour where quick grits take minutes, and some millers advise soaking them overnight. Which grits and which cheddar the house used are the kitchen’s to confirm.`,compare:`Polenta is its nearest neighbor: both are ground dried corn cooked into porridge, but grits are traditionally ground from softer, starchier dent corn and cook up creamier, while Italian polenta is traditionally ground from hard flint corn and holds a firmer body. Hominy, the whole treated kernel, is a different thing again.`,correction:``,sources:[{title:`Wikipedia: Grits`,url:`https://en.wikipedia.org/wiki/Grits`},{title:`Britannica: Grits`,url:`https://www.britannica.com/EBchecked/topic/246451/grits`},{title:`Etymonline: Grits`,url:`https://www.etymonline.com/word/grits`},{title:`America’s Test Kitchen: All About Cornmeal, Grits and Polenta`,url:`https://www.americastestkitchen.com/guides/7918-all-about-cornmeal-grits-and-polenta`},{title:`Anson Mills: What You Need to Know About Corn`,url:`https://ansonmills.com/grain_notes/13`},{title:`Anson Mills: Simple Buttered Pencil Cob Grits`,url:`https://ansonmills.com/recipes/531`},{title:`Justia: Georgia Code 50 3 78, State Official Prepared Food`,url:`https://law.justia.com/codes/georgia/2021/title-50/chapter-3/article-3/section-50-3-78/`},{title:`State Symbols USA: Georgia Prepared Food`,url:`https://statesymbolsusa.org/node/1589`},{title:`Barry Popik: Grillades`,url:`https://barrypopik.com/blog/grillades`},{title:`Dictionary.com: Grits`,url:`https://www.dictionary.com/browse/grits`}],reviewedOn:`2026-11-27`,say:`GRITS`,background:`Corn porridge is Native American before it is Southern: colonists in the South learned the dish in the 1600s from Native peoples who ground maize. The English word is not Native. Grits comes from the Old English grytt, coarse meal, while hominy comes from a Virginia Algonquian word for parched corn that John Smith wrote down, and in colonial times the two names were used interchangeably. Grits became the daily corn dish of the South, and in 2002 Georgia named grits its official prepared food. Milling gives the dish two faces: quick and instant grits, milled finer, cook in minutes, while the older stone ground grits keep the germ and need a long, slow pot. In New Orleans grits are the bed for grillades; a breakfast menu in the Times-Democrat listed grillades and grits in 1900.`,metAt:`Brennan's Thanksgiving Day 2026: the cheddar grits of the Veal Grillades`},{id:`grains-agnolotti`,term:`Agnolotti`,category:`grains`,aliases:[`Agnellotti`,`Agnolòt`],definition:`A filled pasta of Piedmont in northwest Italy, made by folding a sheet or strip of pasta over small mounds of filling and pressing it shut, so each piece has a fold along one edge. The classic Piedmontese filling is roasted meat, pork and veal, first made to use up the leftovers of a roast. The small pinched kind are agnolotti del plin, plin meaning pinch in Piedmontese. Vegetable fillings, such as sweet potato, are modern variations on the shape.`,guest:`Agnolotti are a filled pasta from Piedmont in northern Italy, made by folding one sheet of pasta over the filling and pressing it closed. On Thanksgiving Day ours were filled with sweet potato and finished in brown butter with candied pecans and goat cheese: the flavors of the holiday in an Italian shape.`,kitchen:`The pasta is rolled thin, the filling piped along it, the sheet folded over and sealed and the pieces cut, then cooked briefly in salted water and finished in the pan with the sauce. What is in the filling beyond sweet potato is a lineup question.`,compare:`Ravioli are the nearest neighbor: ravioli are often made by sealing a filling between two sheets of pasta, while agnolotti fold one sheet over it, so one edge of each piece is a fold. Agnolotti del plin are the small pinched form of the same pasta.`,correction:``,sources:[{title:`Wikipedia: Agnolotti`,url:`https://en.wikipedia.org/wiki/Agnolotti`},{title:`Gambero Rosso: Agnolotti del plin, dove mangiarli in Piemonte`,url:`https://www.gamberorosso.it/ristoranti/agnolotti-plin-dove-mangiarli-piemonte/`},{title:`Italia Italy: Agnolotti alla piemontese`,url:`https://www.italia-italy.org/en/ric743-ricette-di-cucina-piemonte/agnolotti-alla-piemontese`},{title:`CooksInfo: Agnolotti`,url:`https://www.cooksinfo.com/agnolotti`},{title:`Great British Chefs: How to make agnolotti`,url:`https://www.greatbritishchefs.com/how-to-cook/how-to-make-agnolotti/amp`},{title:`Air Dolomiti: Agnolotti del Plin, the typical recipe to try in Turin`,url:`https://www.airdolomiti.eu/destinations/turin/destinations-turin-what-to-eat/agnolotti-del-plin-the-typical-recipe-to-try-in-turin`},{title:`Pasta Evangelists: A taste of Piedmont, agnolotti del plin`,url:`https://pastaevangelists.com/blogs/blog/taste-of-piedmont-agnolotti-del-plin`},{title:`Wiktionary: agnolotto`,url:`https://en.wiktionary.org/wiki/agnolotto`},{title:`Merriam-Webster: agnolotti`,url:`https://www.merriam-webster.com/dictionary/agnolotti`}],reviewedOn:`2026-11-27`,say:`ah-nyoh-LOT-tee`,background:`Agnolotti belong to Piedmont, in the northwest of Italy, and especially to the Monferrato hills and the country around Alessandria and Asti. They began as a thrifty dish, a way to use the leftover meat of a roast, and in Monferrato and Turin the classic filling is still roast pork and veal. Where the name comes from is not settled. One story credits a Monferrato cook called Angelot, or Angiolino, with the first of them; another ties the word to the Latin anulus, a ring, for the round shape of early agnolotti. The cook is told as legend, and no record settles the word. The small pinched form, agnolotti del plin, takes its name from plin, the Piedmontese word for a pinch, for the pinch of the fingers that seals each little parcel.`,metAt:`Brennan's Thanksgiving Day 2026: Sweet Potato Agnolotti`},{id:`grains-polenta`,term:`Polenta`,category:`grains`,aliases:[`Cornmeal porridge`],definition:`Cornmeal cooked slowly in water or stock into a porridge, long a staple of northern Italy. Served soft, it is spooned out loose and creamy; left to cool, it sets firm and can be sliced and grilled or fried. Traditional Italian polenta is ground from hard flint corn, which keeps more body than the softer dent corn behind Southern grits. On the Thanksgiving Day menu polenta sat under the bacon-wrapped pork tenderloin.`,guest:`Polenta is the cornmeal porridge of northern Italy, cooked slowly until smooth, a close cousin of our Southern grits. On Thanksgiving Day it sat under the bacon-wrapped pork tenderloin, a mild, corn-sweet base for the cane syrup glaze and the mustard greens.`,kitchen:`Cornmeal goes into simmering liquid in a slow stream while it is whisked, so it does not lump, then cooks with regular stirring until the grains are tender. Whether ours was served soft or set, and what enriched it, was a question for lineup.`,compare:`Grits are the nearest neighbor: both are ground dried corn, but grits are traditionally ground from softer, starchier dent corn and cook up creamier, while Italian polenta is traditionally ground from hard flint corn and holds a firmer, more toothsome body. Color is no test, as either can be yellow.`,correction:``,sources:[{title:`Wikipedia: Polenta`,url:`https://en.wikipedia.org/wiki/Polenta`},{title:`Apollo Magazine: How polenta caused a stir in Venice`,url:`https://apollo-magazine.com/polenta-venice-pietro-longhi-mexico/`},{title:`University of Primorska Press: maize in the Venetian lands`,url:`https://zalozba.upr.si/ISBN/978-961-6963-16-9/files/basic-html/page28.html`},{title:`Italy Heritage: Polenta`,url:`https://www.italyheritage.com/cuisine/food/polenta.htm`},{title:`ZME Science: The story of polenta and its journey from poor man's food to classy delicacy`,url:`https://www.zmescience.com/science/historic-foods-the-story-of-polenta-and-its-journey-from-poor-mans-food-to-classy-delicacy`},{title:`America's Test Kitchen: All About Cornmeal, Grits, and Polenta`,url:`https://www.americastestkitchen.com/articles/7918-all-about-cornmeal-grits-and-polenta`},{title:`Food Network: Grits vs Polenta`,url:`https://www.foodnetwork.com/how-to/packages/food-network-essentials/grits-vs-polenta`},{title:`MasterClass: Polenta vs. Grits Explained`,url:`https://www.masterclass.com/articles/polenta-vs-grits-explained`}],reviewedOn:`2026-11-27`,say:`poh-LEN-tuh`,background:`Polenta is older than corn in Italy. Romans ate grain mushes called puls and pulmentum, and before maize Italians cooked polenta from farro, millet, spelt, chestnut flour or chickpeas. Maize reached Europe from the Americas in the sixteenth century, and the Republic of Venice was among the first places in Italy to grow it not as a curiosity but as a field crop. After a famine in the 1590s maize spread quickly across the Venetian mainland, and cornmeal polenta became the everyday food of the northern Italian countryside, a poor man's dish for centuries before it found its way onto restaurant plates, where it is now served soft, or set and grilled, beside meats and stews.`,metAt:`Brennan's Thanksgiving Day 2026: Bacon-Wrapped Pork Tenderloin`},{id:`grains-pilaf`,term:`Pilaf`,category:`grains`,aliases:[`Pilau`,`Pilaff`],definition:`A way of cooking rice in which the dry grains are first stirred in hot fat, often with onion, then simmered in a measured amount of stock until the liquid is absorbed. The fat coats each grain and sets the starch on its surface, so the rice cooks up fluffy and separate rather than sticky. Spices, vegetables, meat or nuts can go into the pot. On the Thanksgiving Day menu a pilaf of popcorn rice sat under the Shrimp Sauce Piquante.`,guest:`A pilaf is rice toasted in butter or oil before the stock goes in, so every grain stays separate and picks up a light, toasty flavor. Under our Thanksgiving shrimp sauce piquante it was a pilaf of Louisiana popcorn rice, there to catch the tomato gravy.`,kitchen:`The aromatics soften in the fat, the rice is stirred in until it is coated and turns opaque, then hot stock goes in at a set ratio and the pot is covered and left to cook gently until the liquid is gone. What the house cooked into its popcorn rice pilaf was a question for lineup.`,compare:`Plain boiled or steamed rice is its nearest neighbor: that rice goes straight into the water, while a pilaf is toasted in fat first and cooked in stock. The toasting is the tell, and it is why the grains stay apart.`,correction:``,sources:[{title:`Wikipedia: Pilaf`,url:`https://en.wikipedia.org/wiki/Pilaf`},{title:`Merriam-Webster: Pilaf`,url:`https://www.merriam-webster.com/dictionary/pilaf`},{title:`Encyclopaedia Iranica: Berenj, Rice in Cooking`,url:`https://www.iranicaonline.org/articles/berenj-rice/berenj-rice-iii-in-cooking/`},{title:`The Culinary Pro: Rice Pilaf`,url:`https://www.theculinarypro.com/rice-pilaf`},{title:`ckbk: The Pilaf Method`,url:`https://app.ckbk.com/section/prof36725c13s001ss002sss003ssss003/the-pilaf-method`},{title:`America’s Test Kitchen: Shrimp and Okra Perloo`,url:`https://www.americastestkitchen.com/articles/8465-lavish-love-on-your-guests-with-shrimp-and-okra-perloo`},{title:`Yahoo: How Perloo’s West African Roots Shape the Lowcountry Dish`,url:`https://www.yahoo.com/lifestyle/articles/perloos-west-african-roots-shape-225247526.html`}],reviewedOn:`2026-11-27`,say:`pih-LAHF`,background:`Pilaf came into English through the Turkish pilav, from the Persian polow, and Merriam-Webster dates its first known English use to 1609. In Persian the word is first attested in a fourteenth century satirical poem, Mouse and Cat, and its recipes appear in two Safavid cookbooks compiled in the 1520s and the 1590s. In Iran a polow is rice cooked with other ingredients layered into the pot, set against chelow, rice cooked on its own. The dish and its name spread widely, to India as pulao and to the Carolina coast as pilau, where enslaved West Africans and their Gullah Geechee descendants cooked it with the rice they grew. There it became perloo, a one pot dish of rice cooked in stock with shrimp or chicken, a cousin of the pilaf under a Louisiana sauce piquante.`,metAt:`Brennan's Thanksgiving Day 2026: the popcorn rice pilaf under the Shrimp Sauce Piquante`},{id:`sweets-potdecreme`,term:`Pot de Crème`,category:`sweets`,aliases:[`Pots de crème`,`Pot de creme`],definition:`A loose French custard of cream, milk and egg yolks, baked gently until just set and served in the small pot or ramekin it was baked in. The name means pot of cream, and in French kitchens crème also means custard. It is softer and lighter than crème brûlée, made with less cream and finished with no burnt sugar crust, and it is eaten with a spoon from its pot, never turned out. On the Thanksgiving Day menu it was the Sweet Potato Pot de Crème, with miso, cinnamon and marshmallow fluff.`,guest:`A pot de crème, said poh duh KREM, is a silky French custard, baked gently and served in the little pot it set in; the name means pot of cream. Ours on Thanksgiving Day was made with sweet potato, with a touch of miso, cinnamon and marshmallow fluff: the holiday casserole remade as a French custard.`,kitchen:`The custard is baked low and gently, usually in a water bath, and taken out while the center still trembles, because too much heat curdles the egg and makes the custard grainy and weeping. How the house set the sweet potato custard, and how the fluff was finished, was the kitchen’s to say at lineup.`,compare:`Crème brûlée is its nearest neighbor: both are baked custards served in their dish, but crème brûlée is richer, heavier in cream and yolk, baked in a wider, shallower ramekin and topped with a crust of burnt sugar. A pot de crème is softer and has no crust. Crème caramel, the third of the family, is the one turned out onto the plate in its own caramel.`,correction:``,sources:[{title:`Wikipedia: Pot de crème`,url:`https://en.wikipedia.org/wiki/Pot_de_cr%C3%A8me`},{title:`CooksInfo: Pots de Crème`,url:`https://www.cooksinfo.com/pots-de-creme/`},{title:`Cooper Hewitt, Smithsonian Design Museum: A French Porcelain Cup for English Cream`,url:`https://www.cooperhewitt.org/2019/07/15/a-french-porcelain-cup-for-english-cream`},{title:`Tasting Table: Pots De Crème Vs Crème Brûlée: What’s The Difference?`,url:`https://www.tastingtable.com/1674715/pots-de-creme-vs-creme-brulee-difference`},{title:`Miss Buttercup: Pot de Crème vs Crème Brûlée`,url:`https://www.missbuttercup.com/pot-de-creme-vs-creme-brulee/`},{title:`Wikipedia: Crème caramel`,url:`https://en.wikipedia.org/wiki/Cr%C3%A8me_caramel`},{title:`America’s Test Kitchen: Why Gentle Heat Guarantees Smooth Custards`,url:`https://www.americastestkitchen.com/articles/1667-why-gentle-heat-guarantees-smooth-custards`},{title:`Victoria and Albert Museum: Custard cup and cover, Mennecy`,url:`https://collections.vam.ac.uk/item/O308680`}],reviewedOn:`2026-11-27`,say:`poh duh KREM`,background:`Pot de crème is French for pot of cream, and in French kitchens crème serves for custard as well as for cream, so the name says custard in its pot. The name belongs as much to the vessel as to the dessert: it was made and served in a small porcelain cup, often lidded. French porcelain makers turned out such cups in the eighteenth century. The Cooper Hewitt, Smithsonian Design Museum holds a soft paste porcelain custard pot made at Mennecy around 1770, and notes that the French name for custard, crème anglaise, means English cream, and that the cup was made while the French fashion for all things English was in full swing. In most kitchens today a plain ramekin stands in for the lidded pot. At Brennan’s on Thanksgiving Day the custard was made with sweet potato.`,metAt:`Brennan's Thanksgiving Day 2026: Sweet Potato Pot de Crème`},{id:`sweets-custard`,term:`Custard`,category:`sweets`,aliases:[`Crème anglaise`,`Baked custard`,`Stirred custard`],definition:`Egg cooked gently in milk or cream until the egg proteins set the liquid. Stirred over low heat it stays pourable and is crème anglaise; baked, usually in a water bath, it sets firm enough to spoon or slice, as in pot de crème, crème brûlée and crème caramel. In a milk and egg custard the proteins thicken at about 79 to 83 C (175 to 185 F), and only a few degrees past that they tighten into curds and squeeze out water. On the Thanksgiving Day menu it was the base of the Sweet Potato Pot de Crème, and a French style vanilla ice cream is a stirred custard churned and frozen.`,guest:`A custard is simply eggs cooked gently in milk or cream until they set it, silky rather than firm. Our Sweet Potato Pot de Crème on Thanksgiving Day was a baked custard, made with sweet potato and served in its little pot. A French style vanilla ice cream is a custard too, churned as it freezes.`,kitchen:`Gentle heat is the whole craft: a stirred custard comes off the heat as it coats the back of a spoon, and a baked one comes out of its water bath while the center still trembles, since a few degrees too many make it grainy and weeping. Whether the vanilla ice cream with the Bananas Foster starts from a custard base is the kitchen’s to confirm.`,compare:`Its two forms are the first tell: a stirred custard, crème anglaise, pours, while a baked custard holds its shape in the dish. In ice cream the egg is the tell: French style ice cream is a custard with egg yolks, dense and smooth, while Philadelphia style has no egg and freezes icier.`,correction:``,sources:[{title:`Online Etymology Dictionary: custard`,url:`https://www.etymonline.com/word/custard`},{title:`Merriam-Webster: custard`,url:`https://www.merriam-webster.com/dictionary/custard`},{title:`Project Gutenberg: The Forme of Cury, a Roll of Ancient English Cookery Compiled about A.D. 1390`,url:`https://www.gutenberg.org/cache/epub/8102/pg8102.html`},{title:`Foods of England: Crustard of Flesshe`,url:`https://foodsofengland.info/crustardoffleshe.html`},{title:`Wikipedia: Forme of Cury`,url:`https://en.wikipedia.org/wiki/Forme_of_Cury`},{title:`America’s Test Kitchen: Custard Basics`,url:`https://www.americastestkitchen.com/lessons/articles/1420-custard-basics`},{title:`America’s Test Kitchen: Why Gentle Heat Guarantees Smooth Custards`,url:`https://www.americastestkitchen.com/articles/1667-why-gentle-heat-guarantees-smooth-custards`},{title:`ckbk, On Food and Cooking: Dilution Demands Delicacy`,url:`https://app.ckbk.com/reference/food00011c02s001e006se002/dilution-demands-delicacy`},{title:`Modern Pastry and Plated Dessert Techniques: Coagulation`,url:`https://opentextbc.ca/modernpastryandplateddesserts/chapter/coagulation/`},{title:`King Arthur Baking: Ice cream two ways`,url:`https://www.kingarthurbaking.com/blog/2018/08/24/ice-cream-two-ways`},{title:`ckbk, On Food and Cooking: Styles of Ice Cream`,url:`https://app.ckbk.com/reference/food00011c01s001e004se004se003/styles-of-ice-cream`},{title:`Cooper Hewitt, Smithsonian Design Museum: A French Porcelain Cup for English Cream`,url:`https://www.cooperhewitt.org/2019/07/15/a-french-porcelain-cup-for-english-cream`}],reviewedOn:`2026-11-27`,say:`KUS-terd`,background:`The word custard began as the name of a pie, not of its filling. Middle English crustarde or crustade meant a dish baked in a crust, from Latin crusta, crust. The Forme of Cury, the roll of recipes compiled about 1390 and credited to the master cooks of Richard II (1367 to 1400), gives crustardes of meat and of fish, pies in which beaten eggs strained through a cloth are poured over the filling before baking. By the early 1600s the word had slipped from the crust to the creamy egg filling itself. French cooks came to call the stirred version crème anglaise, English cream, and that same stirred custard, churned as it freezes, is the base of a French style ice cream.`,metAt:`Brennan's Thanksgiving Day 2026: Sweet Potato Pot de Crème, and the vanilla ice cream with World Famous Bananas Foster`},{id:`sweets-marshmallowfluff`,term:`Marshmallow Fluff`,category:`sweets`,aliases:[`Marshmallow creme`,`Fluff`],definition:`A brand of marshmallow creme: soft, spoonable whipped marshmallow sold in jars, made since 1920 by Durkee-Mower, a Massachusetts candy firm. Its jar label has listed corn syrup, sugar, dried egg white and vanillin, with no gelatin, so it gets its lift from whipped egg white rather than the gelatin of a marshmallow. It is sweet, sticky and light. On the Thanksgiving Day menu it went with the Sweet Potato Pot de Crème, a nod to the sweet potato casserole under marshmallows.`,guest:`Marshmallow Fluff is marshmallow creme in a jar, a New England sweet since 1920: soft, whipped marshmallow made with egg white. On our Sweet Potato Pot de Crème it was a wink at the sweet potato casserole with marshmallows that so many families bake for Thanksgiving.`,kitchen:`Whether the house used the jarred brand or whipped its own marshmallow, and whether it was toasted, was a question for lineup. Marshmallow creme carries egg white, so egg questions go to the kitchen with every other allergy question.`,compare:`A marshmallow is its nearest neighbor: a marshmallow is set firm with gelatin, so it can be cut and holds its shape, while the creme stays soft and spoonable, lifted by egg white, and carries no gelatin.`,correction:``,sources:[{title:`Marshmallow Fluff: History of Marshmallow Fluff`,url:`https://marshmallowfluff.com/history-of-marshmallow-fluff/`},{title:`Lemelson-MIT: Archibald Query`,url:`https://lemelson.mit.edu/resources/archibald-query`},{title:`NPR, The Salt: What The Fluff? Celebrates A Century Of Peanut Butter’s Marshmallow Friend`,url:`https://www.npr.org/sections/thesalt/2017/09/30/553966235/what-the-fluff-celebrates-a-century-of-peanut-butters-marshmallow-friend`},{title:`Wikipedia: Marshmallow creme`,url:`https://en.wikipedia.org/wiki/Marshmallow_creme`},{title:`Boston.com: For 100 years, Fluff has stuck to its Somerville roots, but the story isn’t that simple`,url:`https://www.boston.com/news/food/2017/09/22/for-100-years-fluff-has-stuck-to-its-somerville-roots-but-the-story-isnt-that-simple`},{title:`Kroger: Marshmallow Fluff product listing`,url:`https://www.kroger.com/p/marshmallow-fluff/0005260011216`},{title:`Open Food Facts: Marshmallow Fluff`,url:`https://world.openfoodfacts.org/product/0052600112751/marshmallow-fluff`},{title:`Mental Floss: The Long, Sweet History of Marshmallows`,url:`https://www.mentalfloss.com/food/candy/long-sweet-history-marshmallows`},{title:`Saveur: The Magical Journey of Marshmallows`,url:`https://www.saveur.com/marshmallow-history-magic`},{title:`Smithsonian Magazine: How Marshmallow Topped Sweet Potato Casserole Became a Thanksgiving Classic`,url:`https://www.smithsonianmag.com/smart-news/happy-100-birthday-marshmallow-sweet-potato-180967245/`},{title:`Mental Floss: 9 Sweet Facts About Marshmallow Fluff`,url:`https://www.mentalfloss.com/article/74155/9-sweet-facts-about-marshmallow-fluff`},{title:`Marshmallow Fluff: History of Marshmallow Fluff (company history)`,url:`https://marshmallowfluff.com/history/`}],reviewedOn:`2026-11-27`,say:`MARSH-mel-oh FLUF`,background:`Marshmallow takes its name from a plant, the marsh mallow, Althaea officinalis, whose root sap French confectioners of the nineteenth century whipped with sugar and egg white into a soft paste, pâte de guimauve; gelatin later took the place of the root and gave the firm marshmallow. Marshmallow Fluff came from the soft side of that family. Archibald Query (1873 to 1964), a confectioner of Somerville, Massachusetts, made a marshmallow creme in his kitchen in 1917 and sold it door to door until the sugar shortages of the World War I years set his trade back. Two veterans of that war from Swampscott, who formed a partnership to make Fluff in 1920, bought his formula, and their firm, Durkee-Mower, which moved to a factory in Lynn in 1929, built the brand. Earlier marshmallow cremes did exist, so Fluff was not the first, but it is the name that stuck.`,metAt:`Brennan's Thanksgiving Day 2026: Sweet Potato Pot de Crème`},{id:`sweets-candiednuts`,term:`Candied Nuts`,category:`sweets`,aliases:[`Candied pecans`,`Candied hazelnuts`,`Sugared nuts`],definition:`Nuts coated in cooked sugar that sets hard and crisp around each one. Some are tossed in a sugar syrup that dries to a sandy crust, others in sugar taken to caramel, which sets in a glassy amber shell. The coating brings sweetness and snap against the soft richness of the nut. On the Thanksgiving Day menu they were candied pecans on the Sweet Potato Agnolotti and candied hazelnuts on the Chocolate and Orange Tart.`,guest:`Candied nuts are nuts cooked in sugar until each one wears a crisp, sweet coat. On Thanksgiving Day there were candied pecans on the sweet potato agnolotti, a sweet crunch against the brown butter and goat cheese, and candied hazelnuts on the chocolate and orange tart.`,kitchen:`Candied nuts are cooled spread apart, so they set crisp and separate rather than in one clump. How the house candied its pecans and hazelnuts was the kitchen’s to say, and every nut question goes to the kitchen and the service note.`,compare:`The New Orleans praline is its nearest neighbor: a praline is a soft, creamy patty of pecans set in brown sugar, butter and cream, while candied nuts are single nuts, each in its own crisp coat. The candied nut is in fact closer to the first French praline, a whole almond in caramelized sugar.`,correction:``,sources:[{title:`Wikipedia: Praline (nut confection)`,url:`https://en.wikipedia.org/wiki/Praline_(nut_confection)`},{title:`New Orleans Historical: Praline or Pecan Candy`,url:`https://neworleanshistorical.org/items/show/259`},{title:`64 Parishes: Pralines`,url:`https://64parishes.org/entry/pralines`},{title:`Wikipedia: Candied almonds`,url:`https://en.wikipedia.org/wiki/Candied_almonds`},{title:`Love and Lemons: Candied Pecans`,url:`https://www.loveandlemons.com/candied-pecans`},{title:`Once Upon a Chef: Sweet and Spicy Candied Pecans`,url:`https://www.onceuponachef.com/recipes/sweet-spicy-candied-pecans.html`},{title:`Taste of Home: Candied Pecans`,url:`https://www.tasteofhome.com/recipes/candied-pecans`},{title:`Wikipedia: César de Choiseul, 1st Duke of Choiseul`,url:`https://en.wikipedia.org/wiki/C%C3%A9sar_de_Choiseul,_1st_Duke_of_Choiseul`},{title:`Saveur: Pralines: How They Cook ’Em in New Orleans`,url:`https://www.saveur.com/story/food/pralines-in-new-orleans`}],reviewedOn:`2026-11-27`,say:`KAN-deed NUTS`,background:`The line of sugared nuts that leads to New Orleans begins with the French praline. The first pralines were whole almonds coated in caramelized sugar, and tradition names them for César de Choiseul, duc du Plessis-Praslin (1598 to 1675), whose cook is said to have made them, a story told often and never proven. A New Orleans story credits the Ursuline nuns, who came to the city in the eighteenth century, with bringing the candy, though 64 Parishes treats that story as legend. African American cooks in the kitchens of the French colonists, with pecans growing all around them, put pecans in place of almonds and added milk, and the praline turned into the soft, creamy patty the city knows. A single candied pecan, crisp in its own coat of sugar, keeps closer to the original French sweet.`,metAt:`Brennan's Thanksgiving Day 2026: candied pecans on the Sweet Potato Agnolotti and candied hazelnuts on the Chocolate and Orange Tart`},{id:`sweets-bananasfoster`,term:`Bananas Foster`,category:`sweets`,aliases:[],definition:`Bananas cooked in a pan of butter, brown sugar and cinnamon with banana liqueur, then flamed with rum and spooned warm over vanilla ice cream. It was created in 1951 at Owen Brennan’s Vieux Carré restaurant on Bourbon Street in New Orleans and named for a friend of his, the chairman of the New Orleans Crime Commission. At Brennan’s it is made and flamed at the table, for two or more.`,guest:`Bananas Foster was created by Brennan’s in 1951. We cook the bananas in butter, brown sugar and cinnamon with a little banana liqueur, flame them with rum right here at your table, and spoon them warm over cold vanilla ice cream. It is made in one pan, for two or more of you.`,kitchen:`The cart goes out set with the pan, the burner, the butter, sugar, cinnamon, liqueur, rum and bananas, the rum measured into a small vessel before it comes near a flame. Who flames it, and the house procedure, are set by the manager at lineup; on Thanksgiving Day the sheet listed the tableside flambé as an addition to the three course menu.`,compare:`Its nearest neighbor is crêpes Suzette, the other classic dessert flamed at the table: there thin crêpes are warmed in a sauce of caramelized sugar, butter, orange juice and zest and flamed with an orange liqueur. Bananas and rum over ice cream, against crêpes and orange liqueur, are the tell.`,correction:``,sources:[{title:`Brennan’s New Orleans: Traditions`,url:`https://www.brennansneworleans.com/traditions/`},{title:`Wikipedia: Bananas Foster`,url:`https://en.wikipedia.org/wiki/Bananas_Foster`},{title:`CBS News: Recipe: Brennan’s Bananas Foster`,url:`https://www.cbsnews.com/news/recipe-brennans-bananas-foster`},{title:`New Orleans & Company: The Legend of Bananas Foster, a Brennan’s New Orleans Original`,url:`https://www.neworleans.com/community/post/the-legend-of-bananas-foster-a-brennans-new-orleans-original/`},{title:`Tasting Table: The History Behind Bananas Foster And The Person It’s Named For`,url:`https://tastingtable.com/1550998/how-bananas-foster-got-its-name`},{title:`Wikipedia: Owen Brennan (restaurateur)`,url:`https://en.wikipedia.org/wiki/Owen_Brennan_(restaurateur)`},{title:`Fox News: Closure of Brennan’s in New Orleans spotlights family feuds`,url:`https://www.foxnews.com/food-drink/closure-of-brennans-in-new-orleans-spotlights-family-feuds`},{title:`Wikipedia: Brennan’s`,url:`https://en.wikipedia.org/wiki/Brennan%27s`},{title:`New Orleans Historical: Brennan’s Restaurant`,url:`https://neworleanshistorical.org/items/show/1502`},{title:`64 Parishes: New Orleans as a Nexus of Power`,url:`https://64parishes.org/new-orleans-as-a-nexus-of-power`},{title:`Legacy.com: Ella Brennan (1925 to 2018), New Orleans Restaurateur`,url:`https://www.legacy.com/news/ella-brennan-1925-2018-new-orleans-restaurateur`},{title:`Nation’s Restaurant News: Fine dining pioneer Ella Brennan dies at 92`,url:`https://www.nrn.com/restaurant-executives/fine-dining-pioneer-ella-brennan-dies-at-92`},{title:`Wikipedia: Crêpes Suzette`,url:`https://en.wikipedia.org/wiki/Cr%C3%AApes_Suzette`},{title:`Brennan’s New Orleans: Bananas Foster recipe`,url:`https://www.brennansneworleans.com/recipes/bananas-foster/`},{title:`NPR: The Sweet Success Of Bananas Foster Has An Unsavory Past`,url:`https://www.npr.org/sections/thesalt/2016/09/30/493157144/the-sweet-success-of-bananas-foster-has-an-unsavory-past`}],reviewedOn:`2026-11-27`,say:`buh-NAN-uhz FAWS-ter`,background:`Bananas Foster was created in 1951 at the Vieux Carré, the restaurant Owen Brennan (1910 to 1955) ran on Bourbon Street before the family business moved. He asked for a new dessert made with bananas and named it for his friend, the chairman of the New Orleans Crime Commission. Bananas were close at hand: the house’s own history tells of a surplus at the family’s produce business, and New Orleans was then a major port of entry for bananas from Central America. Accounts differ on whose hands made it. The house credits its chef of the day, and the family’s telling credits Ella Brennan (1925 to 2018), Owen’s sister, with him, drawing on a banana dish their mother made at home. After Owen’s death the restaurant moved in 1956 to 417 Royal Street, and the dessert went with it.`,metAt:`Brennan's Thanksgiving Day 2026: World Famous Bananas Foster`},{id:`sweets-icecream`,term:`Ice Cream`,category:`sweets`,aliases:[`Vanilla ice cream`,`Vanilla bean ice cream`],definition:`A frozen dessert of cream, milk and sugar, churned as it freezes so that air is whipped in and the ice crystals stay small. In the United States the FDA’s standard of identity requires ice cream to carry at least 10 percent milkfat, and a version richer in egg yolk may be labeled frozen custard or French ice cream. The air whipped in is called overrun: premium ice creams carry little of it and eat dense, while light, fluffy ones carry more. On the Thanksgiving Day menu it was the vanilla bean ice cream under the Bananas Foster.`,guest:`Under the Bananas Foster is vanilla ice cream, cold and creamy, and the warm bananas and rum caramel are spooned straight over it. That meeting of hot and cold, as the ice cream just begins to melt into the sauce, is the heart of the dish.`,kitchen:`The ice cream is scooped just before the bananas and sauce go over it, so it softens under the warm sauce at the table and not before. Which ice cream goes under the Foster, the housemade vanilla the regular menu prints or the New Orleans Ice Cream Co. vanilla bean the Thanksgiving sheet printed, is the chef’s to confirm at lineup.`,compare:`Its nearest neighbor is gelato, which usually carries less butterfat than ice cream’s legal floor of 10 percent, has less air whipped in because it is churned more slowly, and is served warmer, so it eats denser and softer. More cream and more air are the tell of ice cream.`,correction:``,sources:[{title:`eCFR: 21 CFR 135.110, Ice cream and frozen custard`,url:`https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-135/subpart-B/section-135.110`},{title:`Mass.gov: I scream for ice cream law`,url:`https://www.mass.gov/news/i-scream-for-ice-cream-law`},{title:`NPR: Why Scream For Gelato Instead Of Ice Cream? Here’s The Scoop`,url:`https://www.npr.org/sections/thesalt/2015/06/16/413223571/why-scream-for-gelato-instead-of-ice-cream-heres-the-scoop`},{title:`Mental Floss: The difference between ice cream and gelato`,url:`https://www.mentalfloss.com/food/ice-cream/what-is-difference-between-ice-cream-and-gelato`},{title:`Monticello: Ice Cream`,url:`https://www.monticello.org/encyclopedia/ice-cream`},{title:`Smithsonian Magazine: Make Thomas Jefferson’s Recipe for Ice Cream`,url:`https://www.smithsonianmag.com/history/thomas-jefferson-ice-cream-recipe-180975200/`},{title:`Library of Congress, American Treasures: Jefferson’s Recipe for Vanilla Ice Cream`,url:`https://webarchive.library.unt.edu/eot2008/20090507150134/http://www.loc.gov/exhibits/treasures/tri034.html`},{title:`Google Patents: US3254A, Artificial freezer`,url:`https://patents.google.com/patent/US3254`},{title:`Wikipedia: Nancy M. Johnson`,url:`https://en.wikipedia.org/wiki/Nancy_M._Johnson`},{title:`University of Guelph, Ice Cream Technology: Ice Cream History and Folklore`,url:`https://books.lib.uoguelph.ca/icecreamtechnologyebook/chapter/ice-cream-history-and-folklore/`},{title:`National Geographic: How long has everyone screamed for ice cream?`,url:`https://www.nationalgeographic.com/history/history-magazine/article/how-long-everyone-screamed-for-ice-cream`},{title:`Penn State: Probing Question: What is the difference between ice cream and gelato?`,url:`https://www.psu.edu/news/research/story/probing-question-what-difference-between-ice-cream-and-gelato`}],reviewedOn:`2026-11-27`,say:`ICE kreem`,background:`The earliest known ice cream recipe recorded by an American is in the hand of Thomas Jefferson (1743 to 1826): a vanilla ice cream, undated but most likely written down during his years in France in the 1780s, now held by the Library of Congress. Monticello’s own historians note that the popular claim that he introduced ice cream to the country is false; he is credited only with that first recorded recipe. In 1843 a patent was granted for an artificial freezer, cranked by hand, that made it far easier to churn at home. In 1851 a Baltimore milk dealer began making it wholesale, the start of the American ice cream industry. The United States later set a legal standard of identity for it, with its floor of 10 percent milkfat.`,metAt:`Brennan's Thanksgiving Day 2026: the vanilla bean ice cream under World Famous Bananas Foster`},{id:`sweets-chocolateandorange`,term:`Chocolate and Orange`,category:`sweets`,aliases:[`Chocolate orange`,`Orangette`],definition:`The pairing of chocolate with orange, carried as zest, candied peel, juice or an orange liqueur. The bright, slightly bitter orange lifts the weight of cocoa, and the pairing is an old one: seventeenth century chocolate drinks were already scented with orange flower water. Its classic confection is the orangette, a strip of candied orange peel dipped in dark chocolate. On the Thanksgiving Day menu it was the Chocolate and Orange Tart, with candied hazelnuts.`,guest:`Chocolate and orange is an old partnership: the bright, slightly bitter orange keeps rich chocolate from feeling heavy. On Thanksgiving Day our Chocolate and Orange Tart set the two together in a tart, with candied hazelnuts for crunch, a holiday chocolate dessert for the end of a big meal.`,kitchen:`Orange can go into a chocolate dessert as zest steeped in the cream, as candied peel, as juice or as an orange liqueur. How the tart carried its orange, and how dark its chocolate was, was the pastry kitchen’s to say at lineup.`,compare:`Its nearest neighbor is the orangette, the same pairing as a confection: candied peel coated in chocolate, eaten by hand. In a tart the chocolate is the body and the orange the accent; in an orangette the orange peel is the body and the chocolate its coat. Which one is the body is the tell.`,correction:``,sources:[{title:`Colonial Williamsburg: Chocolate`,url:`https://research.colonialwilliamsburg.org/foundation/journal/winter12/chocolate.cfm`},{title:`Project Gutenberg: Chocolate: or, An Indian Drinke (1652)`,url:`https://www.gutenberg.org/cache/epub/21271/pg21271-images.html`},{title:`Paris Gourmet: History of orange aiguillettes`,url:`https://www.parisgourmet.com/magazine/history-of-orange-aiguillettes`},{title:`La Maison du Chocolat: Orangettes`,url:`https://www.lamaisonduchocolat.com/en_us/orangettes-case-38-pieces`},{title:`Wikipedia: Terry’s Chocolate Orange`,url:`https://en.wikipedia.org/wiki/Terry%27s_Chocolate_Orange`},{title:`Grace’s Guide: Joseph Terry and Sons`,url:`https://www.gracesguide.co.uk/Joseph_Terry_and_Sons`},{title:`YorkMix: The origins and history of the Terry’s Chocolate Orange in York`,url:`https://www.yorkmix.com/the-origins-and-history-of-the-terrys-chocolate-orange-in-york`},{title:`HuffPost UK: Forget Milk Chocolate Oranges, Terry’s Chocolate Apple Came First`,url:`https://huffingtonpost.co.uk/entry/terrys-chocolate-apple-orange-history_uk_66fd0ceae4b0d70dca9fa2f0`},{title:`Making and Knowing Project: Chocolate (field notes presentation)`,url:`https://fieldnotes.makingandknowing.org/mainSpace/files/Chocolate-Presentation-PDF.pdf`},{title:`University of York, Borthwick Institute: Unwrapping the Terry’s Chocolate Apple`,url:`https://blogs.york.ac.uk/borthwick-institute/2013/09/06/unwrapping-the-terrys-chocolate-apple/`}],reviewedOn:`2026-11-27`,say:`CHAWK-lit and OR-inj`,background:`Chocolate met orange soon after it reached Europe. In 1652 a London translation of a Spanish treatise, printed as Chocolate: or, An Indian Drinke, gave a recipe for the drink that listed orange flower water among its flavorings, beside sugar, long red pepper, cloves, aniseed and almonds. Confectioners later made the pairing solid in the orangette, a strip of candied orange peel dipped in dark chocolate, a classic of French chocolate making. In England, Terry’s of York launched its Chocolate Orange in 1932, a ball of orange flavored chocolate shaped like the fruit, after a Chocolate Apple it had made from 1926. On the Thanksgiving Day menu at Brennan’s the pairing came as a tart, finished with candied hazelnuts.`,metAt:`Brennan's Thanksgiving Day 2026: Chocolate and Orange Tart`}]},n=t.entries,r=t.categories